INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23242, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "希望就是心里想要一件事发生。", "primary_collocate": null, "pronunciation": "xī wàng", "ipa": "ɕi˥ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我希望明天天气好。", "target_word": "希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望我们多读书。", "target_word": "希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈希望我早点回家。", "target_word": "希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望你能来我的生日会。", "target_word": "希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他希望自己学会游泳。", "target_word": "希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都希望世界和平。", "target_word": "希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一直希望去中国看看。", "target_word": "希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家希望比赛那天不要下雨。", "target_word": "希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她希望哥哥给她买一本书。", "target_word": "希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望你每天都快乐。", "target_word": "希望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "心里想要某件事发生或实现，后面常带小句", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a37e-859d-480a-acef-93c3977707a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "希望", "is_correct": true, "explanation": "希望表示心里想要天气好，符合句意。"}, {"text": "决定", "is_correct": false, "explanation": "语义：“决定”是人主观作出的选择，明天的天气不是人能决定的。"}, {"text": "保证", "is_correct": false, "explanation": "搭配：“保证”通常用于人能负责的事，不能说“保证天气好”。"}, {"text": "发现", "is_correct": false, "explanation": "语义：“发现”表示看到已经存在的情况，不能用于还没到来的明天。"}], "explanations": {"希望": "希望表示心里想要天气好，符合句意。", "决定": "语义：“决定”是人主观作出的选择，明天的天气不是人能决定的。", "保证": "搭配：“保证”通常用于人能负责的事，不能说“保证天气好”。", "发现": "语义：“发现”表示看到已经存在的情况，不能用于还没到来的明天。"}, "sentence_index": 0, "correct_answer": "希望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你希望立刻把手机交出来！", "explanation": "这里应该用〈必须〉。“希望”只表示心里想要，不能用来对别人下达命令；带叹号的命令语气应用“必须”。"}, {"text": "我希望两张票。", "explanation": "这里应该用〈要〉。要可以直接带名词作宾语；希望后面一般接小句或动词，不直接带“两张票”这类名词。"}, {"text": "我昨天希望了一场电影。", "explanation": "这里应该用〈看〉。“希望”表示心里想要某事发生，不能带“一场电影”这样的名词，也不用于已经做完的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "希望", "is_correct": true, "explanation": "希望表示心里一直想要去中国看看，符合句意。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不赞成别人的做法，一个人不会用它来说自己想去做的事。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“一直想去中国看看”的心愿相反。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”要针对已有的打算或对象，“一直放弃去中国看看”不通。"}], "explanations": {"希望": "希望表示心里一直想要去中国看看，符合句意。", "反对": "语义：“反对”表示不赞成别人的做法，一个人不会用它来说自己想去做的事。", "讨厌": "语义：“讨厌”表示厌恶，与“一直想去中国看看”的心愿相反。", "放弃": "搭配：“放弃”要针对已有的打算或对象，“一直放弃去中国看看”不通。"}, "sentence_index": 6, "correct_answer": "希望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我希望他的手机。", "explanation": "这里应该用〈借〉。“希望”后面不能直接带名词作宾语，“借”可以直接带“他的手机”。"}, {"text": "我希望这个计划。", "explanation": "这里应该用〈同意〉。同意可以直接带“计划”作宾语；希望后面一般接小句或动词，不直接带这类名词。"}, {"text": "听到这个坏消息，他很希望。", "explanation": "这里应该用〈难过〉。“希望”是想要某事发生的动词，不能表示听到坏消息后的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我希望了这次考试顺利。", "corrected_sentence": "我希望这次考试顺利。", "error_description": "错误：“希望了”。正确：“希望”。“希望”是表示心理想要的动词，不能直接带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我希望了他早点回来。", "corrected_sentence": "我希望他早点回来。", "error_description": "错误：“希望了”。正确：“希望”。“希望”是心理动词，后面不能直接加“了”，应说“我希望他早点回来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
