INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23250, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "坐地铁就是坐地下跑的火车。", "primary_collocate": null, "pronunciation": "zuò dì tiě", "ipa": "tswo˥˩ ti˥˩ tʰjɛ˨˩˦", "syllable_count": 3, "sentences": [{"text": "早高峰的时候，我宁愿坐地铁，也不想开车。", "target_word": "坐地铁", "complexity_tier": "T3", "furigana": "zǎo gāo fēng de shí hou wǒ nìng yuàn zuò dì tiě yě bù xiǎng kāi chē", "sentence_source": "generated"}, {"text": "北京有很多人坐地铁上下班。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子第一次坐地铁，觉得很新鲜。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐地铁要先买票，再进站。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上十点以后，还可以坐地铁回家。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐地铁到公园只要二十分钟。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国游客喜欢坐地铁，因为方便又便宜。", "target_word": "坐地铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不开车，平时都坐地铁。", "target_word": "坐地铁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "坐地铁的人太多了，我没有座位。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天我一般坐地铁去上班。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "坐了地铁", "label": "体标"}, {"form": "坐过地铁", "label": "体标"}], "register": "中性", "sense_fingerprint": "乘坐在地下行驶的火车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ed7dbc-a6e5-40ee-911c-fb724370c835') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坐地铁", "is_correct": true, "explanation": "正确。「坐地铁」是早高峰时的出行方式，与「不想开车」形成对比。"}, {"text": "洗车", "is_correct": false, "explanation": "语义：洗车与出行选择无关，「宁愿洗车」在早高峰的语境中说不通。"}, {"text": "修车", "is_correct": false, "explanation": "搭配：「修车」是维修车辆，不能作为「宁愿……也不想开车」中的出行替代。"}, {"text": "买车", "is_correct": false, "explanation": "语义：买车仍然以开车为前提，与「也不想开车」的意图矛盾。"}], "explanations": {"坐地铁": "正确。「坐地铁」是早高峰时的出行方式，与「不想开车」形成对比。", "洗车": "语义：洗车与出行选择无关，「宁愿洗车」在早高峰的语境中说不通。", "修车": "搭配：「修车」是维修车辆，不能作为「宁愿……也不想开车」中的出行替代。", "买车": "语义：买车仍然以开车为前提，与「也不想开车」的意图矛盾。"}, "sentence_index": 0, "correct_answer": "坐地铁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地铁司机每天坐地铁，驾驶列车把乘客送到终点。", "explanation": "这里应该用〈开〉。驾驶列车应说「开地铁」；「坐地铁」指乘客乘车，不能表示驾驶。"}, {"text": "我住在十楼，每天坐地铁上楼回家。", "explanation": "这里应该用〈坐电梯〉。上下楼要坐电梯，「坐地铁」指乘坐地下行驶的列车出行。"}, {"text": "他坐地铁，一路开车到学校。", "explanation": "「坐地铁」表示乘车，与「开车」的驾驶动作矛盾，两个动作不能指同一种出行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坐地铁", "is_correct": true, "explanation": "正确。「坐地铁」与「方便又便宜」的交通评价相符，表示游客的出行选择。"}, {"text": "排队", "is_correct": false, "explanation": "语义：排队不会带来「方便又便宜」的好评，与句子的评价语义矛盾。"}, {"text": "生病", "is_correct": false, "explanation": "语义：游客不会因为生病而喜欢某样事物，「生病」与「方便又便宜」的评价不符。"}, {"text": "失业", "is_correct": false, "explanation": "搭配：「喜欢」后接「失业」不符合语义，句子无法理解为对交通的评价。"}], "explanations": {"坐地铁": "正确。「坐地铁」与「方便又便宜」的交通评价相符，表示游客的出行选择。", "排队": "语义：排队不会带来「方便又便宜」的好评，与句子的评价语义矛盾。", "生病": "语义：游客不会因为生病而喜欢某样事物，「生病」与「方便又便宜」的评价不符。", "失业": "搭配：「喜欢」后接「失业」不符合语义，句子无法理解为对交通的评价。"}, "sentence_index": 6, "correct_answer": "坐地铁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在车站坐地铁买票，排了很长的队。", "explanation": "「坐地铁」只能指乘车，在站内买票、排队时还没有乘车，不能说「坐地铁」。"}, {"text": "乘客要先坐地铁，再进站。", "explanation": "这里应该用〈检票〉。进站前要先检票，「坐地铁」指乘车，应在进站后，顺序不能颠倒。"}, {"text": "我在站台坐地铁，等了十分钟。", "explanation": "这里应该用〈等车〉。等车时还没上车，「坐地铁」指已经乘车，不能用于站台上的等候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们坐地铁公园，很快就到了。", "corrected_sentence": "我们坐地铁去公园，很快就到了。", "error_description": "漏字错误：「坐地铁」后要接表示去往的动词「去」，「坐地铁公园」不通，应为「坐地铁去公园」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天坐地铁了去上班。", "corrected_sentence": "我昨天坐地铁去上班。", "error_description": "了的位置错误：「了」不能紧跟宾语「地铁」之后，「坐地铁了去上班」不通，应删去「了」，正确为「我昨天坐地铁去上班」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
