INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23256, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "住就是人在一个地方生活。", "primary_collocate": null, "pronunciation": "zhù", "ipa": "ʈʂu˥˩", "syllable_count": 1, "sentences": [{"text": "我家住在北京。", "target_word": "住", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你住哪儿？", "target_word": "住", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在这个城市住了三年。", "target_word": "住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想住在离学校近的地方。", "target_word": "住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥一个人住，我和爸妈住在一起。", "target_word": "住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间很大，可以住四个人。", "target_word": "住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以前在上海住过两年。", "target_word": "住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人喜欢住在安静的地方，不喜欢吵。", "target_word": "住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶家的楼不高，她一个人住着很舒服。", "target_word": "住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来我家玩吧，晚上可以住在这儿。", "target_word": "住", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "住了", "label": "体标"}, {"form": "住过", "label": "体标"}, {"form": "住着", "label": "体标"}], "register": "中性", "sense_fingerprint": "在某处居住、过日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce010c66-d877-4df7-8147-8f6d54c7cf13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23256, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "住", "is_correct": true, "explanation": "正确：「住」（zhù）意思是居住。"}, {"text": "主", "is_correct": false, "explanation": "「主」（zhǔ，第三声）与 zhù（第四声）声调不同，意思是主人。"}, {"text": "猪", "is_correct": false, "explanation": "「猪」（zhū，第一声）与 zhù（第四声）声调不同，意思是猪。"}, {"text": "竹", "is_correct": false, "explanation": "「竹」（zhú，第二声）与 zhù（第四声）声调不同，意思是竹子。"}], "explanations": {"住": "正确：「住」（zhù）意思是居住。", "主": "「主」（zhǔ，第三声）与 zhù（第四声）声调不同，意思是主人。", "猪": "「猪」（zhū，第一声）与 zhù（第四声）声调不同，意思是猪。", "竹": "「竹」（zhú，第二声）与 zhù（第四声）声调不同，意思是竹子。"}, "sentence_index": null, "correct_answer": "住"}, "level_3": {"options": [{"text": "住", "is_correct": true, "explanation": "正确：「住」表示在某处生活，与「我家……在北京」相合。"}, {"text": "坐", "is_correct": false, "explanation": "语义：「坐」是坐下的动作，不能表示家的居住地。"}, {"text": "站", "is_correct": false, "explanation": "语义：「站」是站立，不能说明家位于哪里。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：「搬」后面接「到」，不接「在」，不说「搬在北京」。"}], "explanations": {"住": "正确：「住」表示在某处生活，与「我家……在北京」相合。", "坐": "语义：「坐」是坐下的动作，不能表示家的居住地。", "站": "语义：「站」是站立，不能说明家位于哪里。", "搬": "搭配：「搬」后面接「到」，不接「在」，不说「搬在北京」。"}, "sentence_index": 0, "correct_answer": "住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把车住在路边。", "explanation": "这里应该用〈停〉。「住」指人或动物居住，车辆停放要说「停」，不说「住在」。"}, {"text": "他把钱住在银行里。", "explanation": "这里应该用〈存〉。「住」指人或动物居住，钱存放在银行要说「存」。"}, {"text": "这块石头住在山谷的东边。", "explanation": "这里应该用〈位于〉。「住」指人或动物生活在某处，石头的位置要说「位于」，不说「住在」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23256, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "住", "is_correct": true, "explanation": "正确：「住」（zhù）意思是居住。"}, {"text": "煮", "is_correct": false, "explanation": "「煮」（zhǔ，第三声）与 zhù（第四声）声调不同，意思是煮。"}, {"text": "珠", "is_correct": false, "explanation": "「珠」（zhū，第一声）与 zhù（第四声）声调不同，意思是珠子。"}, {"text": "烛", "is_correct": false, "explanation": "「烛」（zhú，第二声）与 zhù（第四声）声调不同，意思是蜡烛。"}], "explanations": {"住": "正确：「住」（zhù）意思是居住。", "煮": "「煮」（zhǔ，第三声）与 zhù（第四声）声调不同，意思是煮。", "珠": "「珠」（zhū，第一声）与 zhù（第四声）声调不同，意思是珠子。", "烛": "「烛」（zhú，第二声）与 zhù（第四声）声调不同，意思是蜡烛。"}, "sentence_index": null, "correct_answer": "住"}, "level_3": {"options": [{"text": "住", "is_correct": true, "explanation": "正确：「住过」表示在上海生活过，与「以前在上海」相合。"}, {"text": "哭", "is_correct": false, "explanation": "语义：「哭」是哭泣，与「在上海……过两年」无关。"}, {"text": "跳", "is_correct": false, "explanation": "语义：「跳」是跳动，不能表示在上海的居住。"}, {"text": "躺", "is_correct": false, "explanation": "搭配：「躺」指身体平卧，不能用在「在上海……过两年」这种说法里。"}], "explanations": {"住": "正确：「住过」表示在上海生活过，与「以前在上海」相合。", "哭": "语义：「哭」是哭泣，与「在上海……过两年」无关。", "跳": "语义：「跳」是跳动，不能表示在上海的居住。", "躺": "搭配：「躺」指身体平卧，不能用在「在上海……过两年」这种说法里。"}, "sentence_index": 6, "correct_answer": "住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在椅子上住了很久。", "explanation": "这里应该用〈坐〉。「住」指人或动物居住，坐在椅子上要说「坐」，不说「住」。"}, {"text": "这张桌子住了很多文件。", "explanation": "这里应该用〈放〉。「住」指人或动物居住，文件摆在桌上要说「放」，不说「住」。"}, {"text": "他的手机住在口袋里。", "explanation": "这里应该用〈装〉。「住」的主语应是人或动物，手机放在口袋里要说「装」，不说「住在」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EX