INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在这座城市了住五年。", "corrected_sentence": "她在这座城市住了五年。", "error_description": "错误形式：「了住」。正确形式：「住了」。「了」表示完成，应紧跟动词「住」，不能放在「住」前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在老家住过过三年。", "corrected_sentence": "我在老家住过三年。", "error_description": "重复「过」：「住过过三年」应为「住过三年」。一个动词后只用一个「过」，多加的「过」要去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23258, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坏处", "is_correct": true, "explanation": "正确：「坏处」与「好处」相反，指对人不利的方面。"}, {"text": "颜色", "is_correct": false, "explanation": "与「好处」无反义关系，只是普通名词。"}, {"text": "名字", "is_correct": false, "explanation": "与「好处」无反义关系，只是普通名词。"}, {"text": "方向", "is_correct": false, "explanation": "与「好处」无反义关系，只是普通名词。"}], "correct_answer": "坏处", "explanations": {"坏处": "正确：「坏处」与「好处」相反，指对人不利的方面。", "颜色": "与「好处」无反义关系，只是普通名词。", "名字": "与「好处」无反义关系，只是普通名词。", "方向": "与「好处」无反义关系，只是普通名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
