INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23258, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "好处是事情好的地方，能让人开心或有用。", "primary_collocate": null, "pronunciation": "hǎo chu", "ipa": "xɑʊ˨˩ ʈʂʰu", "syllable_count": 2, "sentences": [{"text": "早睡早起对身体有好处。", "target_word": "好处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多喝水有很多好处。", "target_word": "好处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学一门外语有什么好处？", "target_word": "好处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样做对你没有好处。", "target_word": "好处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "住在学校旁边的好处是走路就能到教室。", "target_word": "好处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个办法都有好处，也有坏处。", "target_word": "好处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐地铁的好处是不会堵车。", "target_word": "好处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他帮了我很多，我不能只想自己的好处。", "target_word": "好处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多读书的好处，你以后会慢慢知道。", "target_word": "好处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动的好处很多，比如睡得好、心情好。", "target_word": "好处", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个好处", "label": "量词"}, {"form": "好處", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人有利、有用的方面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce010c66-d877-4df7-8147-8f6d54c7cf13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好处", "is_correct": true, "explanation": "正确：「好处」指对人有利的方面，与「对身体有」相合。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：「对身体有声音」不成立，「有」后面的名词要能表示对身体的作用。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不是对身体的作用，与早睡早起的意义不符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：「名字」与身体健康无关，句子意思说不通。"}], "explanations": {"好处": "正确：「好处」指对人有利的方面，与「对身体有」相合。", "声音": "搭配：「对身体有声音」不成立，「有」后面的名词要能表示对身体的作用。", "颜色": "语义：「颜色」不是对身体的作用，与早睡早起的意义不符。", "名字": "语义：「名字」与身体健康无关，句子意思说不通。"}, "sentence_index": 0, "correct_answer": "好处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早睡有一只好处：第二天精神好。", "explanation": "这里应该用〈个〉。「只」用于动物等，不能用来数「好处」，应说「一个好处」。"}, {"text": "我今天遇到一件好处，心里很高兴。", "explanation": "这里应该用〈好事〉。「好处」指对人有利的方面，遇到令人高兴的事要说「好事」。"}, {"text": "他在比赛中占有好处。", "explanation": "这里应该用〈优势〉。「好处」指具体有利的方面，说竞争中的有利位置要用「优势」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好处", "is_correct": true, "explanation": "正确：「坐地铁的好处」指坐地铁的有利之处，与「不会堵车」相合。"}, {"text": "速度", "is_correct": false, "explanation": "语义：「速度」说的是快慢，不能用来说明「不会堵车」这个优点。"}, {"text": "方向", "is_correct": false, "explanation": "语义：「方向」指去向，与「不会堵车」这个优点无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」一般用于人或物的重量，不用来说交通方式的特点。"}], "explanations": {"好处": "正确：「坐地铁的好处」指坐地铁的有利之处，与「不会堵车」相合。", "速度": "语义：「速度」说的是快慢，不能用来说明「不会堵车」这个优点。", "方向": "语义：「方向」指去向，与「不会堵车」这个优点无关。", "体重": "搭配：「体重」一般用于人或物的重量，不用来说交通方式的特点。"}, "sentence_index": 6, "correct_answer": "好处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的好处很快，一下子就做完了。", "explanation": "这里应该用〈速度〉。「好处」指对人有利的方面，不能用来说快慢，说快慢要用「速度」。"}, {"text": "这次考试的好处很高，大家都松了口气。", "explanation": "这里应该用〈成绩〉。「好处」指对人有利的方面，说考试的分数高低要用「成绩」。"}, {"text": "散步有一朵好处，能让人放松。", "explanation": "这里应该用〈个〉。「好处」是抽象名词，「朵」用于花、云等具体事物，不能用来数「好处」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "多吃蔬菜对健康好处。", "corrected_sentence": "多吃蔬菜对健康有好处。", "error_description": "漏了动词「有」：「对健康好处」应为「对健康有好处」。「好处」作宾语，前面要有动词「有」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条新路有两只好处：车少了，也快了。", "corrected_sentence": "这条新路有两个好处：车少了，也快了。", "error_description": "量词错误：「两只好处」应为「两个好处」。「只」用于动物等，「好处」要用量词「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
