INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23260, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放出去，比如汽车放出废气。", "primary_collocate": null, "pronunciation": "pái fàng", "ipa": "pʰaɪ˧˥ fɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "工厂不能随便排放废水。", "target_word": "排放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车每天都排放很多废气。", "target_word": "排放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂把废水排放到河里。", "target_word": "排放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要求工厂少排放有害气体。", "target_word": "排放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动车不排放废气，对空气好。", "target_word": "排放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排放太多的烟，城市的空气就会变差。", "target_word": "排放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河很脏，因为附近的工厂排放了废水。", "target_word": "排放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司已经停止排放有害气体。", "target_word": "排放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天很多房子烧煤，排放的烟特别多。", "target_word": "排放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车排放的气体比旧车少。", "target_word": "排放", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排放了", "label": "体标（了）"}, {"form": "排放过", "label": "体标（过）"}, {"form": "排放量", "label": "复合"}], "register": "书面", "sense_fingerprint": "把废气废水等排出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fde7ad18-0ff2-44e3-844c-df7b9ce4ca9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排放", "is_correct": true, "explanation": "“排放”指把废水排出去，与“不能随便”的语境相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：工厂不会喝废水，句意荒谬。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象一般是人或动物，不说喂废水。"}, {"text": "吃", "is_correct": false, "explanation": "语义：废水不能吃，与句意冲突。"}], "explanations": {"排放": "“排放”指把废水排出去，与“不能随便”的语境相符。", "喝": "语义：工厂不会喝废水，句意荒谬。", "喂": "搭配：“喂”的对象一般是人或动物，不说喂废水。", "吃": "语义：废水不能吃，与句意冲突。"}, "sentence_index": 0, "correct_answer": "排放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察排放了一批囚犯。", "explanation": "这里应该用〈释放〉。排放专指把废气、废水等排出，囚犯要用释放。"}, {"text": "教室里排放了一阵笑声。", "explanation": "这里应该用〈发出〉。排放用于废气、废水等物质，声音要用发出。"}, {"text": "她排放了一份礼物。", "explanation": "这里应该用〈送出〉。排放只用于废气、废水等，送礼物要说送出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排放", "is_correct": true, "explanation": "“排放”与“河很脏”的因果关系相符：工厂排出废水，河就变脏。"}, {"text": "净化", "is_correct": false, "explanation": "语义：净化废水会让河变干净，与“很脏”的因果矛盾。"}, {"text": "过滤", "is_correct": false, "explanation": "语义：过滤废水会减少污染，与“很脏”的因果矛盾。"}, {"text": "饮", "is_correct": false, "explanation": "搭配：“饮”的对象一般是水或饮品，不说饮废水。"}], "explanations": {"排放": "“排放”与“河很脏”的因果关系相符：工厂排出废水，河就变脏。", "净化": "语义：净化废水会让河变干净，与“很脏”的因果矛盾。", "过滤": "语义：过滤废水会减少污染，与“很脏”的因果矛盾。", "饮": "搭配：“饮”的对象一般是水或饮品，不说饮废水。"}, "sentence_index": 6, "correct_answer": "排放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玫瑰排放出浓郁的香味。", "explanation": "这里应该用〈散发〉。排放用于废气、废水等，香味要说散发。"}, {"text": "植物排放阳光。", "explanation": "这里应该用〈吸收〉。植物是吸收阳光，不说排放阳光。"}, {"text": "他排放了很多邮票。", "explanation": "这里应该用〈收集〉。排放用于废气、废水等，邮票要说收集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂以前排放了过废水。", "corrected_sentence": "这家工厂以前排放过废水。", "error_description": "体标错误：“排放过”表示曾经排放，“了”和“过”不能同时用在动词后，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂偷偷排放了一根有害气体。", "corrected_sentence": "工厂偷偷排放了一股有害气体。", "error_description": "量词错误：“排放”的宾语“气体”应用“股”计量，“根”用于细长的东西，不能说“一根有害气体”，应说“一股有害气体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
