INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23261, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西从一个地方送到另一个地方。", "primary_collocate": null, "pronunciation": "yùn sòng", "ipa": "yn˥˩ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "快递员骑车运送包裹到每家每户。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路很窄，大车不能运送货物进来。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的工作是用卡车运送家具。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些书运送到新学校去。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运送这些鱼要用很多冰。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们昨天用船运送了三百箱苹果。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器可以自动运送零件。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为大雨，饮料今天没有运送到商店。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用马运送粮食到市场。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司明天会运送新桌子到我们家。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运送了", "label": "体标"}, {"form": "运送过", "label": "体标"}, {"form": "运送着", "label": "体标"}], "register": "中性", "sense_fingerprint": "把货物从一地送到另一地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'febd06f6-a99e-46e8-8a20-fd50029520d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23261, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运送", "is_correct": true, "explanation": "运送：把包裹从一处送到另一处，此处指快递员把包裹送到各家。"}, {"text": "乘坐", "is_correct": false, "explanation": "搭配：“乘坐”的宾语是交通工具，不能说乘坐包裹。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”的宾语是车辆，不能带“包裹”作宾语。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指使劲扔或跌落，与把包裹送到各家的意思不符。"}], "explanations": {"运送": "运送：把包裹从一处送到另一处，此处指快递员把包裹送到各家。", "乘坐": "搭配：“乘坐”的宾语是交通工具，不能说乘坐包裹。", "驾驶": "配价：“驾驶”的宾语是车辆，不能带“包裹”作宾语。", "摔": "语义：“摔”指使劲扔或跌落，与把包裹送到各家的意思不符。"}, "sentence_index": 0, "correct_answer": "运送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请把这些书运送到桌子上去。", "explanation": "这里应该用〈放〉。运送指把东西从较远的地方送到另一地，把书放在同屋的桌上应说〈放〉。"}, {"text": "他把这个好消息运送给了大家。", "explanation": "这里应该用〈传递〉。运送只用于实际的货物或人，消息应说〈传递〉。"}, {"text": "爸爸每天运送自己去公司。", "explanation": "这里应该用〈坐车〉。运送的对象是货物或他人，人自己去公司应说〈坐车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运送", "is_correct": true, "explanation": "运送：把零件从一处送到另一处，此处指机器自动把零件送到需要的地方。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，句中是机器处理零件，不能说机器吃零件。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物、鞋袜，不能说穿零件。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”需要有思考能力的人作主语，机器自动送零件的句子里不能说讨论。"}], "explanations": {"运送": "运送：把零件从一处送到另一处，此处指机器自动把零件送到需要的地方。", "吃": "语义：“吃”指进食，句中是机器处理零件，不能说机器吃零件。", "穿": "搭配：“穿”的宾语是衣物、鞋袜，不能说穿零件。", "讨论": "语义：“讨论”需要有思考能力的人作主语，机器自动送零件的句子里不能说讨论。"}, "sentence_index": 6, "correct_answer": "运送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们运送了整整一天的时光。", "explanation": "这里应该用〈度过〉。运送的对象是人或货物，时间不能被运送，应说〈度过〉。"}, {"text": "老师每天运送很多知识给学生。", "explanation": "这里应该用〈传授〉。运送只用于实际的货物或人，知识应说〈传授〉。"}, {"text": "这把椅子运送了我。", "explanation": "这里应该用〈载〉。运送的主语须是人或车船等交通工具，椅子不能运送人，这里混淆了“运送”与“载”（载人移动）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "快递员骑车运送包裹在小区里的每户人家。", "corrected_sentence": "快递员骑车运送包裹到小区里的每户人家。", "error_description": "“在”应改为“到”。运送的终点要用“到”引出，“在”表示位置，不能接在运送后作目的地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司明天会运送了一套新桌子到我们家。", "corrected_sentence": "公司明天会运送一套新桌子到我们家。", "error_description": "“了”应删去。“明天”指将来，动作还没发生，不能用表示完成的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
