INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工厂或汽车排出的、没用的、脏脏的气体。", "primary_collocate": null, "pronunciation": "fèi qì", "ipa": "feɪ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "汽车跑的时候会排出废气。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟囱里冒出了黑色的废气。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢站在大卡车后面闻废气。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的废气让附近的空气很脏。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废气对小孩的身体不好。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车排出一股废气，我赶快捂住鼻子。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车不会产生废气。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上没有工厂，也没有废气。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，吸入太多废气会头疼。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车的废气比旧车少很多。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股废气", "label": "量词"}, {"form": "工业废气", "label": "复合"}], "register": "中性", "sense_fingerprint": "工厂或汽车排出的没用的脏气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'febd06f6-a99e-46e8-8a20-fd50029520d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23264, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "废气", "is_correct": true, "explanation": "废气（fèiqì）即正确答案：工厂或汽车排出的、没用的、脏的气体。"}, {"text": "费力", "is_correct": false, "explanation": "费力（fèilì）与废气（fèiqì）后一音节声母不同（l 与 q），意思是费劲、吃力。"}, {"text": "匪气", "is_correct": false, "explanation": "匪气（fěiqì）与废气（fèiqì）第一音节声调不同（第三声与第四声），意思是土匪的作风。"}, {"text": "费事", "is_correct": false, "explanation": "费事（fèishì）与废气（fèiqì）后一音节声母不同（sh 与 q），意思是麻烦。"}], "explanations": {"废气": "废气（fèiqì）即正确答案：工厂或汽车排出的、没用的、脏的气体。", "费力": "费力（fèilì）与废气（fèiqì）后一音节声母不同（l 与 q），意思是费劲、吃力。", "匪气": "匪气（fěiqì）与废气（fèiqì）第一音节声调不同（第三声与第四声），意思是土匪的作风。", "费事": "费事（fèishì）与废气（fèiqì）后一音节声母不同（sh 与 q），意思是麻烦。"}, "sentence_index": null, "correct_answer": "废气"}, "level_3": {"options": [{"text": "废气", "is_correct": true, "explanation": "正确：汽车跑时排出的是废气，这与“排出”搭配，符合句意。"}, {"text": "垃圾", "is_correct": false, "explanation": "搭配：“排出”后接气体，不说排出垃圾，汽车跑时也不排出垃圾。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块是固体，汽车跑的时候不会排出冰块。"}, {"text": "铁块", "is_correct": false, "explanation": "语义：铁块是固体，不会从汽车里排出。"}], "explanations": {"废气": "正确：汽车跑时排出的是废气，这与“排出”搭配，符合句意。", "垃圾": "搭配：“排出”后接气体，不说排出垃圾，汽车跑时也不排出垃圾。", "冰块": "语义：冰块是固体，汽车跑的时候不会排出冰块。", "铁块": "语义：铁块是固体，不会从汽车里排出。"}, "sentence_index": 0, "correct_answer": "废气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "烟囱里冒出了一只废气。", "explanation": "这里应该用〈股〉。废气是气体，量词用“股”，应说“一股废气”，不说“一只”。"}, {"text": "山上的废气很清新。", "explanation": "这里应该用〈空气〉。废气是排出的脏气体，不能用“清新”形容；形容清新要用空气。"}, {"text": "我渴了，想喝一杯废气。", "explanation": "这里应该用〈水〉。废气是排出的脏气体，不能喝；口渴要喝水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废气", "is_correct": true, "explanation": "正确：骑自行车不排废气，句中“产生”的是废气，与语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是固体，骑自行车不会产生石头。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电是自然现象，与骑车无关，不会因骑车而产生。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“产生”多接热量、气体、结果，不接花朵。"}], "explanations": {"废气": "正确：骑自行车不排废气，句中“产生”的是废气，与语境相符。", "石头": "语义：石头是固体，骑自行车不会产生石头。", "闪电": "语义：闪电是自然现象，与骑车无关，不会因骑车而产生。", "花朵": "搭配：“产生”多接热量、气体、结果，不接花朵。"}, "sentence_index": 6, "correct_answer": "废气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把废气放进了冰箱。", "explanation": "这里应该用〈牛奶〉。废气是气体，不能放进冰箱保存；冰箱放的是食物。"}, {"text": "我们用废气装饰房间。", "explanation": "这里应该用〈鲜花〉。废气是有害无用的气体，不能用来装饰；装饰房间要用鲜花之类的东西。"}, {"text": "他用废气写字。", "explanation": "这里应该用〈钢笔〉。写字要用书写工具，废气不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆老汽车排出一只黑色的废气。", "corrected_sentence": "这辆老汽车排出一股黑色的废气。", "error_description": "“废气”的量词应为“股”，应说“一股废气”，不说“一只废气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把废气收集起去了。", "corrected_sentence": "工人把废气收集起来了。", "error_description": "趋向补语应说“起来”，不说“起去”，应说“把废气收集起来”，不说“把废气收集起去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
