INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23266, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用语言或文字说出事物的样子或经过。", "primary_collocate": null, "pronunciation": "miáo shù", "ipa": "mjɑʊ˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "请你描述一下那个人的样子。", "target_word": "描述", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用简单的话描述了那个地方。", "target_word": "描述", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能描述一下昨天的天气吗？", "target_word": "描述", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家描述了小城的生活。", "target_word": "描述", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子描述不好自己的心情。", "target_word": "描述", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察请他描述当时的情况。", "target_word": "描述", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把看到的东西都描述出来了。", "target_word": "描述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章描述了春天的美。", "target_word": "描述", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请用三个词描述你的家乡。", "target_word": "描述", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人慢慢描述着年轻时的故事。", "target_word": "描述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "描述了", "label": "体标"}, {"form": "描述着", "label": "体标"}], "register": "中性", "sense_fingerprint": "用语言或文字说出事物的样子或经过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5fcf5b-556e-47e4-b003-813f3f632225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "描述", "is_correct": true, "explanation": "正确。“描述”表示用语言说出样子，符合“请你说说那个人的样子”的语境。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器或器物，不能修理“样子”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间或地面，不能用于“样子”。"}, {"text": "责备", "is_correct": false, "explanation": "语义：“责备”表示批评过错，与“说出样子”的意思无关。"}], "explanations": {"描述": "正确。“描述”表示用语言说出样子，符合“请你说说那个人的样子”的语境。", "修理": "搭配：“修理”的对象是机器或器物，不能修理“样子”。", "打扫": "搭配：“打扫”的对象是房间或地面，不能用于“样子”。", "责备": "语义：“责备”表示批评过错，与“说出样子”的意思无关。"}, "sentence_index": 0, "correct_answer": "描述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他描述了三次澡。", "explanation": "这里应该用〈洗〉。“描述”是用语言或文字说出样子，洗澡是身体动作，要说“洗”，不能说“描述”。"}, {"text": "他用铅笔描述了一只猫的轮廓。", "explanation": "这里应该用〈勾勒〉。“描述”只用于语言或文字，用铅笔沿着轮廓画出来要说“勾勒”。"}, {"text": "实验描述了这个理论是对的。", "explanation": "这里应该用〈证明〉。“描述”只是说出样子或经过，不能用来证实对错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "描述", "is_correct": true, "explanation": "正确。“描述”表示用语言说出看到的东西，符合“她把看到的东西说出来”的语境。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱出看到的东西”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热做熟食物，与“说明所见之物”的意思不合。"}, {"text": "嚼", "is_correct": false, "explanation": "搭配：“嚼”指咀嚼食物，不能用来说明看到的东西。"}], "explanations": {"描述": "正确。“描述”表示用语言说出看到的东西，符合“她把看到的东西说出来”的语境。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱出看到的东西”。", "煮": "语义：“煮”指用水加热做熟食物，与“说明所见之物”的意思不合。", "嚼": "搭配：“嚼”指咀嚼食物，不能用来说明看到的东西。"}, "sentence_index": 6, "correct_answer": "描述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他描述了三下门。", "explanation": "这里应该用〈敲〉。“描述”是用语言说出样子，敲门是身体动作，要说“敲”，不能说“描述”。"}, {"text": "他描述了新同事的名字。", "explanation": "这里应该用〈介绍〉。“介绍”用于说出人或事物的基本情况，如名字；“描述”侧重说出样子。"}, {"text": "他描述了三个数的和。", "explanation": "这里应该用〈计算〉。“描述”是说出样子或经过，数的和要用“计算”得出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那件事描述了一个。", "corrected_sentence": "他把那件事描述了一遍。", "error_description": "动量补语量词错误：描述的动作次数应用“遍”（或“次”），不能用“个”，应说“描述了一遍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇日记描述了出他的童年。", "corrected_sentence": "这篇日记描述出了他的童年。", "error_description": "补语位置错误：“出”是趋向补语，应紧跟动词，说“描述出了”，不能说“描述了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
