INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23268, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说的话或者一些字。", "primary_collocate": null, "pronunciation": "cí", "ipa": "tsʰɨ˧˥", "syllable_count": 1, "sentences": [{"text": "这个词是什么意思？", "target_word": "词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会写这个词。", "target_word": "词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把词写在卡片上，让我们背。", "target_word": "词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用这个词说一句话。", "target_word": "词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词太难了，我不认识。", "target_word": "词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的每个词我都听懂了。", "target_word": "词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想不起来那个词怎么说。", "target_word": "词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不知道用哪个词才对。", "target_word": "词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能把这个词写在黑板上吗？", "target_word": "词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个词的意思差不多。", "target_word": "词", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个词", "label": "量词"}, {"form": "詞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "语言中能单独使用的字或话，如一个词、新词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "词", "is_correct": true, "explanation": "正确答案。“词”指语言中能单独使用的字或话。"}, {"text": "次", "is_correct": false, "explanation": "cì（第四声）与 cí（第二声）声调不同，“次”意思是次数。"}, {"text": "刺", "is_correct": false, "explanation": "cì（第四声）与 cí（第二声）声调不同，“刺”意思是尖锐的东西。"}, {"text": "池", "is_correct": false, "explanation": "chí 与 cí 声母不同（ch 与 c），“池”意思是水池。"}, {"text": "迟", "is_correct": false, "explanation": "chí 与 cí 声母不同（ch 与 c），“迟”意思是晚、慢。"}], "explanations": {"词": "正确答案。“词”指语言中能单独使用的字或话。", "次": "cì（第四声）与 cí（第二声）声调不同，“次”意思是次数。", "刺": "cì（第四声）与 cí（第二声）声调不同，“刺”意思是尖锐的东西。", "池": "chí 与 cí 声母不同（ch 与 c），“池”意思是水池。", "迟": "chí 与 cí 声母不同（ch 与 c），“迟”意思是晚、慢。"}, "sentence_index": null, "correct_answer": "词"}, "level_3": {"options": [{"text": "词", "is_correct": true, "explanation": "“词”是语言中能单独使用的字或话，这里问的是词语的意思，正好相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，“这个桌子是什么意思”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“是什么意思”问的应是有含义的词语或句子，不能用来问“天气”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是供玩耍的物品，没有可以询问的字面含义，这里说不通。"}], "explanations": {"词": "“词”是语言中能单独使用的字或话，这里问的是词语的意思，正好相符。", "桌子": "语义：“桌子”是家具，“这个桌子是什么意思”说不通。", "天气": "搭配：“是什么意思”问的应是有含义的词语或句子，不能用来问“天气”。", "玩具": "语义：“玩具”是供玩耍的物品，没有可以询问的字面含义，这里说不通。"}, "sentence_index": 0, "correct_answer": "词"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说了三只词。", "explanation": "这里的量词应该用〈个〉。“词”用“个”计数，“只”一般用于动物或成对的东西。"}, {"text": "他会说三种词。", "explanation": "这里应该用〈语言〉。“词”指单个词语，不指语言体系，会说几种语言要说〈语言〉。"}, {"text": "这个词有主语和谓语。", "explanation": "这里应该用〈句子〉。“词”是单个词语，没有主语和谓语，要说〈句子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "词", "is_correct": true, "explanation": "“词”是语言中能单独使用的字或话，这里说的是想不起来的那个词怎么说，正好相符。"}, {"text": "唱", "is_correct": false, "explanation": "语法：“那个”后须接名词，“唱”是动词，“那个唱怎么说”不成立。"}, {"text": "跑", "is_correct": false, "explanation": "语法：“那个”后须接名词，“跑”是动词，“那个跑怎么说”不成立。"}, {"text": "走", "is_correct": false, "explanation": "语法：“那个”后须接名词，“走”是动词，“那个走怎么说”不成立。"}], "explanations": {"词": "“词”是语言中能单独使用的字或话，这里说的是想不起来的那个词怎么说，正好相符。", "唱": "语法：“那个”后须接名词，“唱”是动词，“那个唱怎么说”不成立。", "跑": "语法：“那个”后须接名词，“跑”是动词，“那个跑怎么说”不成立。", "走": "语法：“那个”后须接名词，“走”是动词，“那个走怎么说”不成立。"}, "sentence_index": 6, "correct_answer": "词"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一瓶词。", "explanation": "这里应该用〈词典〉。“瓶”用于瓶装的东西，“词”不能用“瓶”计量，买的应是“一本词典”。"}, {"text": "这个词很好吃。", "explanation": "这里应该用〈菜〉。“词”是语言单位，不能吃，说食物好吃要用〈菜〉。"}, {"text": "这个词有三段。", "explanation": "这里应该用〈文章〉。“词”是单个词语，不能分段，说段落要用〈文章〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只词我以前没听过。", "corrected_sentence": "这个词我以前没听过。", "error_description": "“词”的量词应用“个”，“只”一般用于动物或成对的东西，不能说“这只词”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我查了一下这个词们的意思。", "corrected_sentence": "我查了一下这个词的意思。", "error_description": "“词”不能加“们”表示复数，应说“这个词”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变好", "is_correct": true, "explanation": "正确：“变好”与“变坏”互为反义，表示变得好。"}, {"text": "存放", "is_correct": false, "explanation": "存放是动词，指保存物品，与“变坏”没有反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "生长是动词，指生物的发育增长，与“变坏”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是动词，指快速移动身体，与“变坏”没有反义关系。"}], "correct_answer": "变好", "explanations": {"变好": "正确：“变好”与“变坏”互为反义，表示变得好。", "存放": "存放是动词，指保存物品，与“变坏”没有反义关系。", "生长": "生长是动词，指生物的发育增长，与“变坏”没有反义关系。", "跑步": "跑步是动词，指快速移动身体，与“变坏”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变好", "is_correct": true, "explanation": "正确：“变好”与“变坏”互为反义，表示变得好。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是动词，指在水中运动，与“变坏”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是动词，指发出有节奏的声音，与“变坏”没有反义关系。"}, {"text": "写信", "is_correct": false, "explanation": "写信是动词，指用文字传递消息，与“变坏”没有反义关系。"}], "correct_answer": "变好", "explanations": {"变好": "正确：“变好”与“变坏”互为反义，表示变得好。", "游泳": "游泳是动词，指在水中运动，与“变坏”没有反义关系。", "唱歌": "唱歌是动词，指发出有节奏的声音，与“变坏”没有反义关系。", "写信": "写信是动词，指用文字传递消息，与“变坏”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变得不好。", "primary_collocate": null, "pronunciation": "biàn huài", "ipa": "pjɛn˥˩ xwaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他的心情突然变坏了，一句话也不说。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换了新老板，饭店的服务变坏了。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变坏，我们不能去爬山了。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的关系变坏了，现在很少说话。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脾气越来越大，人也变坏了。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天饭菜不放冰箱，很容易变坏。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼睛变坏了，看书要戴眼镜。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做了错事以后，他的名声变坏了。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的学习习惯变坏了，作业总是不做。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里车太多，空气变坏了，大家都咳嗽。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变坏了", "label": "体标"}, {"form": "变坏过", "label": "体标"}, {"form": "變壞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "状态、关系、心情等变得不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'febd06f6-a99e-46e8-8a20-fd50029520d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变坏", "is_correct": true, "explanation": "变坏（biànhuài）即正确答案，指变得不好。"}, {"text": "变化", "is_correct": false, "explanation": "变化（biànhuà）与变坏（biànhuài）韵尾不同（a 与 ai），意思是改变、变动。"}, {"text": "变换", "is_correct": false, "explanation": "变换（biànhuàn）与变坏（biànhuài）韵尾不同（an 与 ai），意思是改换、转换。"}, {"text": "变快", "is_correct": false, "explanation": "变快（biànkuài）与变坏（biànhuài）声母不同（k 与 h），意思是速度变快。"}], "explanations": {"变坏": "变坏（biànhuài）即正确答案，指变得不好。", "变化": "变化（biànhuà）与变坏（biànhuài）韵尾不同（a 与 ai），意思是改变、变动。", "变换": "变换（biànhuàn）与变坏（biànhuài）韵尾不同（an 与 ai），意思是改换、转换。", "变快": "变快（biànkuài）与变坏（biànhuài）声母不同（k 与 h），意思是速度变快。"}, "sentence_index": null, "correct_answer": "变坏"}, "level_3": {"options": [{"text": "变坏", "is_correct": true, "explanation": "正确：“变坏”表示心情转坏，与后句“一句话也不说”相符。"}, {"text": "变甜", "is_correct": false, "explanation": "搭配：“甜”说的是味道，心情不说变甜，也不符合句意。"}, {"text": "变长", "is_correct": false, "explanation": "语义：心情不会变长，与句意不符。"}, {"text": "变远", "is_correct": false, "explanation": "语义：“远”说的是距离，心情不会变远。"}], "explanations": {"变坏": "正确：“变坏”表示心情转坏，与后句“一句话也不说”相符。", "变甜": "搭配：“甜”说的是味道，心情不说变甜，也不符合句意。", "变长": "语义：心情不会变长，与句意不符。", "变远": "语义：“远”说的是距离，心情不会变远。"}, "sentence_index": 0, "correct_answer": "变坏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的营业时间变坏了，客人越来越少。", "explanation": "这里应该用〈延长〉。营业时间的调整说“延长”或“缩短”；“变坏”指事物性质转坏，不用于时间。"}, {"text": "他这个月变坏了好几公斤。", "explanation": "这里应该用〈变瘦〉。体重减少要说“变瘦”，不说“变坏”。"}, {"text": "下午的影子变坏了。", "explanation": "这里应该用〈变长〉。影子的长短变化说“变长”，影子没有好坏之分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变坏", "is_correct": true, "explanation": "正确：眼睛变坏即视力下降，所以要戴眼镜，与句意相符。"}, {"text": "变轻", "is_correct": false, "explanation": "语义：眼睛不会“变轻”，与视力下降的语境不符。"}, {"text": "变凉", "is_correct": false, "explanation": "语义：眼睛不会“变凉”，也不能说明需要戴眼镜。"}, {"text": "变涨", "is_correct": false, "explanation": "搭配：“涨”用于价格、水位，不说眼睛变涨。"}], "explanations": {"变坏": "正确：眼睛变坏即视力下降，所以要戴眼镜，与句意相符。", "变轻": "语义：眼睛不会“变轻”，与视力下降的语境不符。", "变凉": "语义：眼睛不会“变凉”，也不能说明需要戴眼镜。", "变涨": "搭配：“涨”用于价格、水位，不说眼睛变涨。"}, "sentence_index": 6, "correct_answer": "变坏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树一年变坏了两米。", "explanation": "这里应该用〈变高〉。树长高是高度的增加，不是变好或变坏，应说“变高”。"}, {"text": "春天到了，草地变坏了。", "explanation": "这里应该用〈变绿〉。草地变绿是颜色的变化，不表示变坏，应说“变绿”。"}, {"text": "全市的人口变坏了不少。", "explanation": "这里应该用〈增加〉。人口数量增多说“增加”，人口不能“变坏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的情绪很变坏了，大家都很担心。", "corrected_sentence": "他的情绪慢慢变坏了，大家都很担心。", "error_description": "副词“很”不能修饰动作动词“变坏”，应说“慢慢变坏了”，不说“很变坏了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店开了十年，服务变坏着。", "corrected_sentence": "这家店开了十年，服务变坏了。", "error_description": "“变坏”表示已经发生的变化，要用“了”；“着”表示持续的状态，不能说“变坏着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
