INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23272, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "坐车、坐船、坐飞机。", "primary_collocate": null, "pronunciation": "chéng zuò", "ipa": "ʈʂʰɤŋ˧˥ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "去北京可以乘坐高铁，也可以坐飞机。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他乘坐大船去了海上的小岛。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人乘坐公共汽车不用买票。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没乘坐过船。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘坐这趟火车要三个小时。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，她乘坐出租车回家。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘坐地铁去机场又快又便宜。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们乘坐旅游车参观了老城。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘坐飞机前，要先检查行李。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请乘坐下一班车，这辆车已经满了。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乘坐了", "label": "体标"}, {"form": "乘坐过", "label": "体标"}, {"form": "乘坐着", "label": "体标"}], "register": "中性", "sense_fingerprint": "坐车、坐船、坐飞机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'febd06f6-a99e-46e8-8a20-fd50029520d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘坐", "is_correct": true, "explanation": "乘坐：搭乘交通工具前往，此处指坐高铁去北京。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复，句中要表达的是去北京的出行方式。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”带的是货物，不能说搬运高铁去北京。"}, {"text": "检修", "is_correct": false, "explanation": "语义：“检修”指检查维修，与去北京的意思不符。"}], "explanations": {"乘坐": "乘坐：搭乘交通工具前往，此处指坐高铁去北京。", "修理": "语义：“修理”指修复，句中要表达的是去北京的出行方式。", "搬运": "搭配：“搬运”带的是货物，不能说搬运高铁去北京。", "检修": "语义：“检修”指检查维修，与去北京的意思不符。"}, "sentence_index": 0, "correct_answer": "乘坐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在屋里乘坐椅子看书。", "explanation": "这里应该用〈坐〉。乘坐的宾语须是交通工具，椅子不是，应说“坐在椅子上”。"}, {"text": "我每天乘坐马上学。", "explanation": "这里应该用〈骑〉。乘坐指坐在交通工具里，骑马要说〈骑〉。"}, {"text": "他把行李乘坐上楼。", "explanation": "这里应该用〈搬〉。乘坐的对象是交通工具，行李应说〈搬〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乘坐", "is_correct": true, "explanation": "乘坐：搭乘交通工具出行，此处指乘地铁去机场。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”指在水中活动，地铁不能游泳，与句意不合。"}, {"text": "维修", "is_correct": false, "explanation": "语义：“维修”指修理保养，与去机场的出行意思不符。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”带的是货物，不能说搬运地铁去机场。"}], "explanations": {"乘坐": "乘坐：搭乘交通工具出行，此处指乘地铁去机场。", "游泳": "语义：“游泳”指在水中活动，地铁不能游泳，与句意不合。", "维修": "语义：“维修”指修理保养，与去机场的出行意思不符。", "搬运": "搭配：“搬运”带的是货物，不能说搬运地铁去机场。"}, "sentence_index": 6, "correct_answer": "乘坐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我乘坐那辆车开回家，车很快。", "explanation": "这里应该用〈驾驶〉。乘坐指作为乘客坐车，句中说“开”，应说〈驾驶〉。"}, {"text": "我们乘坐了一个小时的快乐。", "explanation": "这里应该用〈享受〉。乘坐的对象是交通工具，快乐不能被乘坐，应说〈享受〉。"}, {"text": "他乘坐一只狗去学校。", "explanation": "这里应该用〈牵〉。乘坐的宾语是交通工具，狗不是，应说“牵着一只狗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去上海可以乘坐了高铁，也可以乘坐飞机。", "corrected_sentence": "去上海可以乘坐高铁，也可以乘坐飞机。", "error_description": "“了”应删去。“可以”表示可能，后面的动词不能带表示完成的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们明天乘坐了旅游车去参观老城。", "corrected_sentence": "他们明天乘坐旅游车去参观老城。", "error_description": "“了”应删去。“明天”指将来，动作尚未发生，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c48b7bcf-cc68-48db-82c2-61b39f838ec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己管住自己，不让自己做不该做的事。", "primary_collocate": null, "pronunciation": "zì zhì", "ipa": "tsɨ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "老师说，学会自制才能少犯错误。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很想玩手机，但能自制，先写完了作业。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她努力自制，没有乱买东西。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生气就骂人，很难自制。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，他很难过，却能自制。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥的人要自制，不能总吃甜食。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，大人也要自制，不能总发脾气。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对游戏，小孩往往不能自制。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一时冲动想打人，好在能够自制。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越是着急，越要自制，不要乱说话。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自制力", "label": "复合"}, {"form": "自制了", "label": "体标"}], "register": "中性", "sense_fingerprint": "管住自己，不做不该做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '248b86e3-a7bf-40e2-bf37-3951132d833d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自制", "is_correct": true, "explanation": "正确。“学会自制”指管住自己，与“少犯错误”的语境相符。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”是不加约束，与“才能少犯错误”的因果关系相反。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”是推迟做事，与“少犯错误”没有合理的因果关系。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：「吵闹」是喧哗，与「少犯错误」没有因果联系，句意不通。"}], "explanations": {"自制": "正确。“学会自制”指管住自己，与“少犯错误”的语境相符。", "放纵": "语义：“放纵”是不加约束，与“才能少犯错误”的因果关系相反。", "拖延": "语义：“拖延”是推迟做事，与“少犯错误”没有合理的因果关系。", "吵闹": "语义：「吵闹」是喧哗，与「少犯错误」没有因果联系，句意不通。"}, "sentence_index": 0, "correct_answer": "自制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很难自制。", "explanation": "这里应该用〈搬动〉。自制的主语只能是人，石头管不住自己，应说很难搬动。"}, {"text": "他很快自制住了局面。", "explanation": "这里应该用〈控制〉。自制只指约束自己，不能用来指控制局面。"}, {"text": "他总是自制地抢别人的东西。", "explanation": "这里应该用〈随便〉。自制指克制自己，不能修饰“抢别人的东西”这类失去约束的行为，表示行为随意要说随便。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自制", "is_correct": true, "explanation": "正确。“大人也要自制”指管住自己，与“不能总发脾气”相呼应。"}, {"text": "撒谎", "is_correct": false, "explanation": "语义：“撒谎”与“不能总发脾气”的劝诫语境不相关，句子读成了劝人撒谎。"}, {"text": "失控", "is_correct": false, "explanation": "语义：“失控”与“不能总发脾气”的要求相反，读起来自相矛盾。"}, {"text": "伤害", "is_correct": false, "explanation": "语义：「伤害」指损害他人，与「不能总发脾气」的劝诫语境不符，句子读不通。"}], "explanations": {"自制": "正确。“大人也要自制”指管住自己，与“不能总发脾气”相呼应。", "撒谎": "语义：“撒谎”与“不能总发脾气”的劝诫语境不相关，句子读成了劝人撒谎。", "失控": "语义：“失控”与“不能总发脾气”的要求相反，读起来自相矛盾。", "伤害": "语义：「伤害」指损害他人，与「不能总发脾气」的劝诫语境不符，句子读不通。"}, "sentence_index": 6, "correct_answer": "自制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一见到蛇就很自制地大哭起来。", "explanation": "这里应该用〈害怕〉。自制指克制自己，与“大哭”的失控反应相矛盾，表示恐惧要说害怕。"}, {"text": "他很会自制孩子。", "explanation": "这里应该用〈照顾〉。自制只能约束自己，不能以他人为对象。"}, {"text": "他拒绝了朋友的邀请，还把朋友自制住了。", "explanation": "这里应该用〈拦住〉。自制只能约束自己，不能以别人为对象，应说拦住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很生气，但能自制自己，没有骂人。", "corrected_sentence": "他很生气，但能自制，没有骂人。", "error_description": "错误：“自制”本身就是“管住自己”，不能再带宾语“自己”，应删去“自己”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看到糖果，弟弟往往不能自制自己。", "corrected_sentence": "看到糖果，弟弟往往不能自制。", "error_description": "错误：“自制”已含“管住自己”的意思，不能再带宾语“自己”，应删去“自己”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23276, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
