INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23276, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在一般情况下大多如此。", "primary_collocate": null, "pronunciation": "tōng cháng", "ipa": "tʰʊŋ˥ tʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我通常七点起床。", "target_word": "通常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末他通常在家看书。", "target_word": "通常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她通常坐地铁去上班。", "target_word": "通常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天这里通常很冷。", "target_word": "通常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们通常在学校吃午饭。", "target_word": "通常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师通常不会迟到。", "target_word": "通常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我通常先做作业，再玩儿手机。", "target_word": "通常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通常周日商店人很多。", "target_word": "通常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他通常喝茶，不喝咖啡。", "target_word": "通常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸通常晚上八点才回家。", "target_word": "通常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "通常", "label": "基本形式"}], "register": "中性", "sense_fingerprint": "在一般情况下经常这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37088c36-b988-4c59-bd87-98a844545e6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23276, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通常", "is_correct": true, "explanation": "正确答案。通常（tōng cháng）意思是一般情况下经常如此。"}, {"text": "通畅", "is_correct": false, "explanation": "chàng（第四声）与 cháng（第二声）声调不同，意思是畅通、顺利。"}, {"text": "铜厂", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）、chǎng（第三声）与 cháng（第二声）声调不同，意思是加工铜的工厂。"}, {"text": "同唱", "is_correct": false, "explanation": "tóng 与 tōng、chàng 与 cháng 的声调都不同，意思是一起唱。"}], "explanations": {"通常": "正确答案。通常（tōng cháng）意思是一般情况下经常如此。", "通畅": "chàng（第四声）与 cháng（第二声）声调不同，意思是畅通、顺利。", "铜厂": "tóng（第二声）与 tōng（第一声）、chǎng（第三声）与 cháng（第二声）声调不同，意思是加工铜的工厂。", "同唱": "tóng 与 tōng、chàng 与 cháng 的声调都不同，意思是一起唱。"}, "sentence_index": null, "correct_answer": "通常"}, "level_3": {"options": [{"text": "通常", "is_correct": true, "explanation": "“通常”表示一般情况下经常这样，与“我七点起床”的习惯说法相符。"}, {"text": "几乎", "is_correct": false, "explanation": "语义：“几乎”表示接近但未达到，与“七点”这样确定的时间冲突。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示出乎意料的一次性事件，与表示习惯的起床语境不合。"}, {"text": "一下子", "is_correct": false, "explanation": "搭配：“一下子”指短时间内全部完成，不用来描述每天固定的起床时间。"}], "explanations": {"通常": "“通常”表示一般情况下经常这样，与“我七点起床”的习惯说法相符。", "几乎": "语义：“几乎”表示接近但未达到，与“七点”这样确定的时间冲突。", "突然": "语义：“突然”表示出乎意料的一次性事件，与表示习惯的起床语境不合。", "一下子": "搭配：“一下子”指短时间内全部完成，不用来描述每天固定的起床时间。"}, "sentence_index": 0, "correct_answer": "通常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在路上通常遇见了老同学。", "explanation": "这里应该用〈偶然〉。通常表示一般情况下经常如此，“遇见老同学”是一次性的事情，要用“偶然”。"}, {"text": "考试的时候，他通常想起了那个公式。", "explanation": "这里应该用〈突然〉。通常强调经常性，“想起那个公式”是临时的一次反应，要用“突然”。"}, {"text": "昨天他通常打碎了一个杯子。", "explanation": "这里应该用〈不小心〉。通常表示一般情况下经常如此，“打碎一个杯子”是一次性的意外，不能用“通常”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通常", "is_correct": true, "explanation": "“通常”表示一般情况下的习惯，与“先做作业，再玩儿手机”的日常安排相符。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示在同一时间进行，与“先……再……”的先后顺序相矛盾。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示与别人共同做某事，而句中只有“我”一个人做这些事。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立刻发生，与“先做作业，再玩儿手机”这种按顺序安排的日常习惯不符。"}], "explanations": {"通常": "“通常”表示一般情况下的习惯，与“先做作业，再玩儿手机”的日常安排相符。", "同时": "语义：“同时”表示在同一时间进行，与“先……再……”的先后顺序相矛盾。", "一起": "语义：“一起”表示与别人共同做某事，而句中只有“我”一个人做这些事。", "马上": "语义：“马上”表示立刻发生，与“先做作业，再玩儿手机”这种按顺序安排的日常习惯不符。"}, "sentence_index": 6, "correct_answer": "通常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是我通常第一次来北京。", "explanation": "这里不能用〈通常〉。通常指经常如此，而这里表达的是一次性的意思，二者相矛盾，应去掉“通常”。"}, {"text": "他通常在这里住了三年。", "explanation": "这里应该用〈一直〉。通常强调经常如此的习惯，而“住了三年”是持续的状态，应该用“一直”。"}, {"text": "他通常一夜之间就长高了。", "explanation": "这里应该用〈突然〉。通常表示经常如此，而“长高”是一次性的突变，应该用“突然”，如“他突然长高了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很通常会早点睡。", "corrected_sentence": "她通常会早点睡。", "error_description": "“通常”是副词，前面不能再加程度副词“很”。“很通常”不成立，应去掉“很”，写成“她通常会早点睡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他通常去了公园散步。", "corrected_sentence": "他通常去公园散步。", "error_description": "错误：“通常去了”。正确：“通常去”。“通常”表示习惯，描述习惯性的动作时不用“了”来表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
