INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23278, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "车太多，路走不动了。", "primary_collocate": null, "pronunciation": "dǔ chē", "ipa": "tu˨˩˦ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "前面堵车了，我们走不了。", "target_word": "堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一堵车，出租车也开不快。", "target_word": "堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说市中心现在堵车，我们换条路吧。", "target_word": "堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雪后，城里到处都堵车。", "target_word": "堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堵车的时候，我在车里听音乐。", "target_word": "堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开会迟到了，因为路上堵车。", "target_word": "堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个路口常常堵车，要多等一会儿。", "target_word": "堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最不喜欢上班路上堵车。", "target_word": "堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天有比赛，体育场附近可能会堵车。", "target_word": "堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果不堵车，我们半小时就能到。", "target_word": "堵车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堵了车", "label": "体标"}, {"form": "堵过车", "label": "体标"}], "register": "口语", "sense_fingerprint": "路上车太多，车子几乎走不动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '676cb373-aaf1-42e3-9e2e-cfe3ab4580b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堵车", "is_correct": true, "explanation": "堵车：车太多、路走不动，与“前面……了，我们走不了”的语境相符。"}, {"text": "通车", "is_correct": false, "explanation": "语义：“通车”指道路开通、车辆可以通行，与“我们走不了”的结果矛盾。"}, {"text": "放行", "is_correct": false, "explanation": "语义：“放行”指允许通过，与“我们走不了”的结果矛盾。"}, {"text": "开车", "is_correct": false, "explanation": "搭配：“开车”说的是驾驶动作，不用来描述前方道路的通行状态。"}], "explanations": {"堵车": "堵车：车太多、路走不动，与“前面……了，我们走不了”的语境相符。", "通车": "语义：“通车”指道路开通、车辆可以通行，与“我们走不了”的结果矛盾。", "放行": "语义：“放行”指允许通过，与“我们走不了”的结果矛盾。", "开车": "搭配：“开车”说的是驾驶动作，不用来描述前方道路的通行状态。"}, "sentence_index": 0, "correct_answer": "堵车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下水道堵车了，水流不下去。", "explanation": "这里应该用〈堵塞〉。“堵车”只指车辆在路上行驶不畅，下水道被堵应说“堵塞”。"}, {"text": "他一紧张，说话就堵车了。", "explanation": "这里应该用〈卡壳〉。“堵车”指车辆在路上受阻，说话不顺应说“卡壳”。"}, {"text": "这种商品堵车了，仓库里堆满了。", "explanation": "这里应该用〈滞销〉。“堵车”只用于车辆，商品卖不出去应说“滞销”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堵车", "is_correct": true, "explanation": "堵车：路口车多、行驶不畅，与“要多等一会儿”的语境相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与路口的交通状况无关，“路口常常唱歌”句子意思不对。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与路口的交通状况无关，不能解释“要多等一会儿”。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”描述人的悠闲走动，不用来描写路口的交通状况。"}], "explanations": {"堵车": "堵车：路口车多、行驶不畅，与“要多等一会儿”的语境相符。", "唱歌": "语义：“唱歌”与路口的交通状况无关，“路口常常唱歌”句子意思不对。", "跳舞": "语义：“跳舞”与路口的交通状况无关，不能解释“要多等一会儿”。", "散步": "搭配：“散步”描述人的悠闲走动，不用来描写路口的交通状况。"}, "sentence_index": 6, "correct_answer": "堵车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人群堵车在入口，动不了。", "explanation": "这里应该用〈拥堵〉。“堵车”只指车辆在路上行驶不畅，人群聚集应说“拥堵”。"}, {"text": "我的鼻子堵车了，很难受。", "explanation": "这里应该用〈堵塞〉。“堵车”只用于车辆，鼻子不通应说“堵塞”。"}, {"text": "通讯突然堵车了，我们断了联系。", "explanation": "这里应该用〈中断〉。“堵车”只说车辆在路上受阻，通讯停止应说“中断”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面堵车着，我们走不了。", "corrected_sentence": "前面堵着车，我们走不了。", "error_description": "错误：体标“着”的位置不对。离合词“堵车”拆开后，“着”放在“堵”后面，说“堵着车”，不说“堵车着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下午两点以后，这条路很少堵车过。", "corrected_sentence": "下午两点以后，这条路很少堵过车。", "error_description": "错误：体标“过”的位置不对。离合词“堵车”拆开后，“过”应放在“堵”后面，说“堵过车”，不说“堵车过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
