INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23282, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23282, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们走的、车开的路。", "primary_collocate": null, "pronunciation": "dào lù", "ipa": "tɑʊ˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这条道路很宽，两边有很多树。", "target_word": "道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，道路变得很滑。", "target_word": "道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在修这条道路。", "target_word": "道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条道路上车很多，过马路要小心。", "target_word": "道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的道路又窄又长。", "target_word": "道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新道路让我们回家的时间少了一半。", "target_word": "道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪让这里的道路不好走。", "target_word": "道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的道路都很干净。", "target_word": "道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的道路在修，我们只能走别的路。", "target_word": "道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口的道路上有很多自行车。", "target_word": "道路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条道路", "label": "量词"}, {"form": "道路交通", "label": "复合"}], "register": "中性", "sense_fingerprint": "供人行走和车辆通行的路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f0846f6-3efb-40f5-acd6-084c548b4338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道路", "is_correct": true, "explanation": "指供人和车通行的路，与“两边有很多树”相配，符合句意。"}, {"text": "裙子", "is_correct": false, "explanation": "语义：“裙子”是衣物，不可能两边有很多树。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：“鱼”不是路，句中“两边有很多树”无法成立。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾是围在颈上的衣物，“两边有很多树”说不通。"}], "explanations": {"道路": "指供人和车通行的路，与“两边有很多树”相配，符合句意。", "裙子": "语义：“裙子”是衣物，不可能两边有很多树。", "鱼": "语义：“鱼”不是路，句中“两边有很多树”无法成立。", "围巾": "语义：围巾是围在颈上的衣物，“两边有很多树”说不通。"}, "sentence_index": 0, "correct_answer": "道路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条道路通往上游，船来船往很热闹。", "explanation": "这里应该用〈水路〉。道路指供人和车行走的陆上道路，船只航行的水上通道要用水路。"}, {"text": "他一口气做完了所有的道路。", "explanation": "这里应该用〈题目〉。道路指供人和车行走的路，要做完的试题应说“题目”。"}, {"text": "田里的道路熟了。", "explanation": "这里应该用〈稻子〉。道路不会成熟，“熟”只用于庄稼、果实等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道路", "is_correct": true, "explanation": "指供人和车通行的路，大雪会使它不好走，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以走的地方，不能说“不好走”。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是室内空间，不是可以行走的路，句中不成立。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“走”不用于声音，不能说“声音不好走”。"}], "explanations": {"道路": "指供人和车通行的路，大雪会使它不好走，符合句意。", "天空": "语义：天空不是可以走的地方，不能说“不好走”。", "房间": "语义：房间是室内空间，不是可以行走的路，句中不成立。", "声音": "搭配：“走”不用于声音，不能说“声音不好走”。"}, "sentence_index": 6, "correct_answer": "道路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机沿着一条道路起飞了。", "explanation": "这里应该用〈跑道〉。道路指供人和车行走的陆上道路，飞机起飞的通道要用跑道。"}, {"text": "他说的话很有道路。", "explanation": "这里应该用〈道理〉。“有道理”说的是话合理，道路是供通行的路，不能这样用。"}, {"text": "村里来了一个道路。", "explanation": "这里应该用〈道士〉。道路是物，不会“来”，人来村里应说道士等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条很长道路穿过森林。", "corrected_sentence": "这条很长的道路穿过森林。", "error_description": "修饰语错误：“很长”修饰“道路”时中间要用“的”，应说“很长的道路”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里新修了一座道路。", "corrected_sentence": "村里新修了一条道路。", "error_description": "量词错误：道路用“条”，“座”用于山、桥、楼房等大型物体，不能用于道路。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
