INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23284, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "事情一次次发生。", "primary_collocate": null, "pronunciation": "jīng cháng", "ipa": "tɕiŋ˥ tʂʰaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我经常早上跑步。", "target_word": "经常", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他经常去图书馆看书。", "target_word": "经常", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我们经常一起吃饭。", "target_word": "经常", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈经常给我打电话，问我吃什么。", "target_word": "经常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里冬天经常下雪，所以很冷。", "target_word": "经常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不经常看电视，因为工作太忙。", "target_word": "经常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，我经常在河边玩儿。", "target_word": "经常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她爱运动，经常去游泳。", "target_word": "经常", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生们经常问老师问题，课上很热闹。", "target_word": "经常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的朋友住在国外，我们经常上网聊天。", "target_word": "经常", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "經常", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词：表示动作或事情多次重复发生，频率高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37088c36-b988-4c59-bd87-98a844545e6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23284, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经常", "is_correct": true, "explanation": "正确。经常（jīng cháng）表示事情一次次发生。"}, {"text": "进场", "is_correct": false, "explanation": "jìn chǎng 与 jīng cháng 韵母（in 与 ing）和声调都不同，意思是进入场地。"}, {"text": "经商", "is_correct": false, "explanation": "shāng（第一声）与 cháng（第二声）声母和声调都不同（sh 与 ch），意思是做生意。"}, {"text": "京城", "is_correct": false, "explanation": "chéng 与 cháng 韵母不同（eng 与 ang），声调相同（第二声），意思是首都。"}, {"text": "静场", "is_correct": false, "explanation": "jìng chǎng 与 jīng cháng 两个音节声调都不同（第四声、第三声），意思是场内安静下来。"}], "explanations": {"经常": "正确。经常（jīng cháng）表示事情一次次发生。", "进场": "jìn chǎng 与 jīng cháng 韵母（in 与 ing）和声调都不同，意思是进入场地。", "经商": "shāng（第一声）与 cháng（第二声）声母和声调都不同（sh 与 ch），意思是做生意。", "京城": "chéng 与 cháng 韵母不同（eng 与 ang），声调相同（第二声），意思是首都。", "静场": "jìng chǎng 与 jīng cháng 两个音节声调都不同（第四声、第三声），意思是场内安静下来。"}, "sentence_index": null, "correct_answer": "经常"}, "level_3": {"options": [{"text": "经常", "is_correct": true, "explanation": "正确。经常表示事情反复发生，与「早上跑步」这种习惯相符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：「马上」表示立刻要发生，与「早上」这种习惯性的时段不相容。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：「忽然」表示突然发生的一次事情，不能用来说每天早上跑步的习惯。"}, {"text": "当场", "is_correct": false, "explanation": "搭配：「当场」多修饰当时当地发生的一次性动作，与「早上跑步」这种习惯搭配不当。"}], "explanations": {"经常": "正确。经常表示事情反复发生，与「早上跑步」这种习惯相符。", "马上": "语义：「马上」表示立刻要发生，与「早上」这种习惯性的时段不相容。", "忽然": "语义：「忽然」表示突然发生的一次事情，不能用来说每天早上跑步的习惯。", "当场": "搭配：「当场」多修饰当时当地发生的一次性动作，与「早上跑步」这种习惯搭配不当。"}, "sentence_index": 0, "correct_answer": "经常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他经常考上了大学。", "explanation": "这里应该用〈终于〉。经常表示事情一次次发生，考上大学只发生一次，应该用终于表示经过努力后出现的结果。"}, {"text": "我经常喜欢这首歌。", "explanation": "这里应该用〈一直〉。「喜欢」是持续的状态，不会一次次重复发生，经常只用于反复出现的动作。"}, {"text": "他经常是我的老师。", "explanation": "这里应该用〈曾经〉。「是」表示身份，是一种状态，不能说经常；说过去担任过某种身份要用曾经。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经常", "is_correct": true, "explanation": "正确。经常表示事情反复发生，与「小时候」的经常性经历相符。"}, {"text": "将要", "is_correct": false, "explanation": "语义：「将要」表示未来，与句中的「小时候」指过去矛盾。"}, {"text": "即将", "is_correct": false, "explanation": "语义：「即将」表示马上要发生，与「小时候」所指的过去时间矛盾。"}, {"text": "立即", "is_correct": false, "explanation": "语义：「立即」表示马上做某事，不能描述「小时候」反复发生的习惯。"}], "explanations": {"经常": "正确。经常表示事情反复发生，与「小时候」的经常性经历相符。", "将要": "语义：「将要」表示未来，与句中的「小时候」指过去矛盾。", "即将": "语义：「即将」表示马上要发生，与「小时候」所指的过去时间矛盾。", "立即": "语义：「立即」表示马上做某事，不能描述「小时候」反复发生的习惯。"}, "sentence_index": 6, "correct_answer": "经常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经常一下子长高了二十厘米。", "explanation": "这里应该用〈突然〉。「一下子长高了二十厘米」是一次性的变化，「经常」表示反复发生，两者矛盾。"}, {"text": "他经常在去年结了婚。", "explanation": "这里不能用〈经常〉。“经常”表示反复发生，而“结婚”是一次性的事件，应去掉“经常”，说“他去年结了婚”。"}, {"text": "他经常毕业了。", "explanation": "这里应该用〈已经〉。毕业只发生一次，已经用来说明某件事已经完成，经常表示反复发生，不能用于毕业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他经常常跑步。", "corrected_sentence": "他经常跑步。", "error_description": "错在「经常」后多加了一个「常」。「经常」本身已表示反复发生，不能再加「常」重复，应说「他经常跑步」或「他常常跑步」，不能说「他经常常跑步」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他经常的迟到。", "corrected_sentence": "他经常迟到。", "error_description": "错在「经常」后多加了「的」。副词「经常」后不能直接加「的」，去掉「的」即为「他经常迟到」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
