INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23286, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23286, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情是什么样子的。", "primary_collocate": null, "pronunciation": "qíng kuàng", "ipa": "tɕʰiŋ³⁵ kʰuɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "请你说一说那里的情况。", "target_word": "情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生问了我家里的情况。", "target_word": "情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天路上的情况很好。", "target_word": "情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不太了解公司的情况。", "target_word": "情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个情况我们以前没有见过。", "target_word": "情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想知道学生的学习情况。", "target_word": "情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据现在的情况，我们明天再走。", "target_word": "情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把医院里的情况告诉了我们。", "target_word": "情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的天气情况怎么样？", "target_word": "情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们那里的交通情况好不好？", "target_word": "情况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "实际情况", "label": "复合"}, {"form": "情況", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情或事物所处的样子、状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172f7e52-d98b-43ac-869e-8829631459cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23286, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "情况", "is_correct": true, "explanation": "正确：“那里的情况”指那里事情的状况，与“说一说”搭配自然。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人的属性，不能说“那里的年龄”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体型，不能用来描述一个地方。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重只用于人或动物，“那里的体重”不成立。"}], "explanations": {"情况": "正确：“那里的情况”指那里事情的状况，与“说一说”搭配自然。", "年龄": "语义：年龄是人的属性，不能说“那里的年龄”。", "身材": "体貌：身材指人的体型，不能用来描述一个地方。", "体重": "搭配：体重只用于人或动物，“那里的体重”不成立。"}, "sentence_index": 0, "correct_answer": "情况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的情况非常美，画着一片金色的麦田。", "explanation": "这里应该用〈情景〉。情况指事情的状况，画面、景致要用情景。"}, {"text": "他在同学们心中的情况很好，大家都愿意和他做朋友。", "explanation": "这里应该用〈形象〉。情况指事情的状况，人在别人心中的印象要用形象。"}, {"text": "山上的情况很美，到处是红叶。", "explanation": "这里应该用〈景色〉。情况指事情的状况，自然风光要用景色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情况", "is_correct": true, "explanation": "正确：“根据现在的情况”表示依据当前的状况，符合句意。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别是人的属性，不能作为决定明天走不走的依据。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高描述人的外形，与出发时间无关。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是人的生理特征，不能作为出发的依据。"}], "explanations": {"情况": "正确：“根据现在的情况”表示依据当前的状况，符合句意。", "性别": "语义：性别是人的属性，不能作为决定明天走不走的依据。", "身高": "体貌：身高描述人的外形，与出发时间无关。", "血型": "语义：血型是人的生理特征，不能作为出发的依据。"}, "sentence_index": 6, "correct_answer": "情况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的情况很感人，很多人都哭了。", "explanation": "这里应该用〈情节〉。情况指事情的状况，故事的经过要用情节。"}, {"text": "这首歌的情况很好听，我每天都听。", "explanation": "这里应该用〈旋律〉。情况指事情的状况，歌曲的好听程度要用旋律。"}, {"text": "这道菜的情况很鲜，大家都夸好吃。", "explanation": "这里应该用〈味道〉。情况指事情的状况，菜肴的滋味要用味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想参观一下那里的情况。", "corrected_sentence": "我想了解一下那里的情况。", "error_description": "搭配错误：“参观”的对象是地方或展览，不能说“参观情况”；“情况”常与“了解”搭配，应说“了解一下那里的情况”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只情况在夏天很常见。", "corrected_sentence": "这种情况在夏天很常见。", "error_description": "量词错误：“情况”前应用“种”，不能用“只”。“只”多用于动物等，不用于抽象的情况。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
