INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花是长在植物上、有颜色和香味的东西。", "primary_collocate": null, "pronunciation": "huā", "ipa": "xwa˥", "syllable_count": 1, "sentences": [{"text": "这种花很香。", "target_word": "花", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窗外的花红红的，闻起来很香。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩手里拿着一朵花。", "target_word": "花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家阳台上有几盆花。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这朵花又大又香，颜色也漂亮。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过生日的时候，朋友送给我一束花。", "target_word": "花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花谢了以后，树上长出了果子。", "target_word": "花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天给花浇水。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蝴蝶停在那朵花上。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，山上的花都开了。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "朵", "label": "量词"}, {"form": "盆", "label": "量词"}, {"form": "花朵", "label": "复合"}, {"form": "花园", "label": "复合"}], "register": "中性", "sense_fingerprint": "长在植物上、有颜色和香味的花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: 3 words above tier T1 (max 2): 树上 (Zipf 3.82), 长出 (Zipf 3.18), 果子 (Zipf 3.45)']::text[], '676cb373-aaf1-42e3-9e2e-cfe3ab4580b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23290, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "花", "is_correct": true, "explanation": "花（huā）指长在植物上、有颜色和香味的东西，是本词的读音与词义。"}, {"text": "画", "is_correct": false, "explanation": "huà（第四声）与 huā（第一声）声调不同，意思是图画。"}, {"text": "瓜", "is_correct": false, "explanation": "guā 与 huā 只有声母不同（g 与 h），意思是瓜类。"}, {"text": "夸", "is_correct": false, "explanation": "kuā 与 huā 只有声母不同（k 与 h），意思是夸奖。"}, {"text": "滑", "is_correct": false, "explanation": "huá（第二声）与 huā（第一声）声调不同，意思是光滑。"}], "explanations": {"花": "花（huā）指长在植物上、有颜色和香味的东西，是本词的读音与词义。", "画": "huà（第四声）与 huā（第一声）声调不同，意思是图画。", "瓜": "guā 与 huā 只有声母不同（g 与 h），意思是瓜类。", "夸": "kuā 与 huā 只有声母不同（k 与 h），意思是夸奖。", "滑": "huá（第二声）与 huā（第一声）声调不同，意思是光滑。"}, "sentence_index": null, "correct_answer": "花"}, "level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "此处“花”指植物的花，有香味，与“很香”搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有香味，“这种石头很香”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会散发香味，不能用“很香”描述。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“很香”不与“玻璃”搭配，这样说不通。"}], "explanations": {"花": "此处“花”指植物的花，有香味，与“很香”搭配。", "石头": "语义：石头没有香味，“这种石头很香”说不通。", "桌子": "语义：桌子不会散发香味，不能用“很香”描述。", "玻璃": "搭配：“很香”不与“玻璃”搭配，这样说不通。"}, "sentence_index": 0, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家阳台上的花每天早上七点就跑去学校上课。", "explanation": "这里应该用〈孩子〉。“跑去学校上课”的主语是人，“花”指植物的花朵，不能去学校。"}, {"text": "那盆花又快又灵活，一下子就跑到了屋顶上。", "explanation": "这里应该用〈猫〉。“跑到屋顶上”是动物的动作，“花”指植物的花朵，不能用来指动物。"}, {"text": "窗台上的花昨天给我写了一封信，说它很想念我。", "explanation": "这里应该用〈朋友〉。“写信、想念”的主语是人，“花”指植物的花朵，不能作这类动作的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23290, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "花", "is_correct": true, "explanation": "花（huā）指长在植物上、有颜色和香味的东西，是本词的读音与词义。"}, {"text": "华", "is_correct": false, "explanation": "huá（第二声）与 huā（第一声）声调不同，意思是中华、华丽。"}, {"text": "化", "is_correct": false, "explanation": "huà（第四声）与 huā 声调不同，意思是变化。"}, {"text": "话", "is_correct": false, "explanation": "huà（第四声）与 huā 声调不同，意思是话语。"}], "explanations": {"花": "花（huā）指长在植物上、有颜色和香味的东西，是本词的读音与词义。", "华": "huá（第二声）与 huā（第一声）声调不同，意思是中华、华丽。", "化": "huà（第四声）与 huā 声调不同，意思是变化。", "话": "huà（第四声）与 huā 声调不同，意思是话语。"}, "sentence_index": null, "correct_answer": "花"}, "level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "此处“花”是主语，“花谢”指花朵凋落，与“谢”搭配。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“谢”用于花朵凋落，不能说“雨谢了”。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子不会“谢”，“孩子谢了以后”语义不通。"}, {"text": "火焰", "is_correct": false, "explanation": "语义：火焰熄灭，不说“谢”，这里说不通。"}], "explanations": {"花": "此处“花”是主语，“花谢”指花朵凋落，与“谢”搭配。", "雨": "搭配：“谢”用于花朵凋落，不能说“雨谢了”。", "孩子": "语义：孩子不会“谢”，“孩子谢了以后”语义不通。", "火焰": "语义：火焰熄灭，不说“谢”，这里说不通。"}, "sentence_index": 6, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天到了，桃树上结满了花。", "explanation": "这里应该用〈果子〉。“结”的对象是果实，花是开出来的，不能说“结花”。"}, {"text": "我家阳台上有一根花。", "explanation": "量词错误：“根”用于细长的东西，花应用“朵”“束”“盆”等，不能说“一根花”。"}, {"text": "妈妈买了一张花送给我。", "explanation": "量词错误：“张”用于平面的东西，花应用“朵”“束”等，不能说“一张花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家阳台上摆着一个花。", "corrected_sentence": "我家阳台上摆着一盆花。", "error_description": "量词错误：“花”前应用“盆”（一盆花）或“朵”（一朵花），不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈生日那天，我送给她一辆花。", "corrected_sentence": "妈妈生日那天，我送给她一束花。", "error_description": "量词错误：“辆”用于车，花应用“束”或“朵”，应说“一束花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23292, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变坏", "is_correct": true, "explanation": "“变坏”与“变好”互为反义，指情况向不好的方向变化。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“变好”无反义或近义关系，“唱歌”是一种文艺活动，与状况变化无关。"}, {"text": "迟到", "is_correct": false, "explanation": "与“变好”无反义或近义关系，“迟到”指到得晚，与情况的好坏无关。"}, {"text": "失败", "is_correct": false, "explanation": "与“变好”无反义或近义关系，“失败”与“成功”相对，不与“变好”构成反义。"}], "correct_answer": "变坏", "explanations": {"变坏": "“变坏”与“变好”互为反义，指情况向不好的方向变化。", "唱歌": "与“变好”无反义或近义关系，“唱歌”是一种文艺活动，与状况变化无关。", "迟到": "与“变好”无反义或近义关系，“迟到”指到得晚，与情况的好坏无关。", "失败": "与“变好”无反义或近义关系，“失败”与“成功”相对，不与“变好”构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23292, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变坏", "is_correct": true, "explanation": "“变坏”与“变好”互为反义，指情况向不好的方向变化。"}, {"text": "跑步", "is_correct": false, "explanation": "与“变好”无反义或近义关系，“跑步”是一种运动，与生活状况无关。"}, {"text": "开门", "is_correct": false, "explanation": "与“变好”无反义或近义关系，“开门”是一个动作，与状况变化无关。"}, {"text": "游泳", "is_correct": false, "explanation": "与“变好”无反义或近义关系，“游泳”是一种运动，不表示状况的变化。"}], "correct_answer": "变坏", "explanations": {"变坏": "“变坏”与“变好”互为反义，指情况向不好的方向变化。", "跑步": "与“变好”无反义或近义关系，“跑步”是一种运动，与生活状况无关。", "开门": "与“变好”无反义或近义关系，“开门”是一个动作，与状况变化无关。", "游泳": "与“变好”无反义或近义关系，“游泳”是一种运动，不表示状况的变化。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23292, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变得比以前更好。", "primary_collocate": null, "pronunciation": "biàn hǎo", "ipa": "pjɛn˥˩ xɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "天气慢慢变好了。", "target_word": "变好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过努力，他的成绩变好了。", "target_word": "变好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃药以后，我的身体变好了。", "target_word": "变好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "希望明天的天气会变好。", "target_word": "变好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的空气变好了很多。", "target_word": "变好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了音乐，他的心情变好了。", "target_word": "变好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的关系一直没有变好。", "target_word": "变好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要你努力，一切都会变好。", "target_word": "变好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，他的睡眠变好了。", "target_word": "变好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，村里的生活变好了。", "target_word": "变好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变好了", "label": "体标"}, {"form": "变好过", "label": "体标"}, {"form": "變好", "label": "繁体"}], "register": "中性", "sense_fingerprint": "情况、身体、心情等比以前更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23292, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变好", "is_correct": true, "explanation": "正确答案。“变好”表示情况向好的方向变化。"}, {"text": "办好", "is_correct": false, "explanation": "bàn 与 biàn 少了一个 i 音，“办好”意思是处理得好。"}, {"text": "编好", "is_correct": false, "explanation": "biān（第一声）与 biàn（第四声）声调不同，“编好”意思是编写完成。"}, {"text": "编号", "is_correct": false, "explanation": "biān hào 与 biàn hǎo 两个音节的声调都不同，“编号”意思是给东西编上号码。"}, {"text": "变老", "is_correct": false, "explanation": "lǎo 与 hǎo 声母不同（l 与 h），“变老”意思是变得年老。"}], "explanations": {"变好": "正确答案。“变好”表示情况向好的方向变化。", "办好": "bàn 与 biàn 少了一个 i 音，“办好”意思是处理得好。", "编好": "biān（第一声）与 biàn（第四声）声调不同，“编好”意思是编写完成。", "编号": "biān hào 与 biàn hǎo 两个音节的声调都不同，“编号”意思是给东西编上号码。", "变老": "lǎo 与 hǎo 声母不同（l 与 h），“变老”意思是变得年老。"}, "sentence_index": null, "correct_answer": "变好"}, "level_3": {"options": [{"text": "变好", "is_correct": true, "explanation": "“变好”表示情况向好的方向变化，与“天气慢慢……了”相符。"}, {"text": "长大", "is_correct": false, "explanation": "语义：“长大”指生物逐渐成长，天气不会长大，句子说不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”指人或动物身体不适，天气不会生病，句子不合理。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说的是数量的增多，不能说“天气慢慢增加了”。"}], "explanations": {"变好": "“变好”表示情况向好的方向变化，与“天气慢慢……了”相符。", "长大": "语义：“长大”指生物逐渐成长，天气不会长大，句子说不通。", "生病": "语义：“生病”指人或动物身体不适，天气不会生病，句子不合理。", "增加": "搭配：“增加”说的是数量的增多，不能说“天气慢慢增加了”。"}, "sentence_index": 0, "correct_answer": "变好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年的气温比去年变好了。", "explanation": "这里应该用〈变高〉。“变好”表示情况向好，气温的升降应说〈变高〉、〈升高〉等。"}, {"text": "我的体重变好了三公斤。", "explanation": "这里应该用〈增加〉。“变好”不用于数量的增减，体重增加要说〈增加〉。"}, {"text": "今年的人口变好了两成。", "explanation": "这里应该用〈增长〉。“变好”表示情况向好，人口的增长要说〈增长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变好", "is_correct": true, "explanation": "“变好”表示关系向好的方向发展，与“一直没有”相合。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能用来描述关系，句子说不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”指进食，与关系的变化无关，句意荒谬。"}, {"text": "变饱", "is_correct": false, "explanation": "搭配：“饱”描述吃的状态，不能用来描述关系，“变饱”与“关系”不搭配。"}], "explanations": {"变好": "“变好”表示关系向好的方向发展，与“一直没有”相合。", "下雨": "语义：“下雨”是天气现象，不能用来描述关系，句子说不通。", "吃饭": "语义：“吃饭”指进食，与关系的变化无关，句意荒谬。", "变饱": "搭配：“饱”描述吃的状态，不能用来描述关系，“变饱”与“关系”不搭配。"}, "sentence_index": 6, "correct_answer": "变好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些水变好了冰。", "explanation": "这里应该用〈变成〉。“变好”只表示情况向好，不表示事物变成另一种东西，水变成冰要说〈变成〉。"}, {"text": "这场事故变好了。", "explanation": "这里应该用〈发生〉。“变好”表示情况向好转变，事故只能说“发生”，不能说“变好”。"}, {"text": "这几年，村里的物价变好了三成。", "explanation": "这里应该用〈上涨〉。“变好”表示情况向好，物价的涨跌只能说〈上涨〉或〈下降〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家饭店的服务最近很变好了。", "corrected_sentence": "这家饭店的服务最近变好了。", "error_description": "“变好”是动词，前面不能直接加程度副词“很”，应说“变好了”或“变得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最近我的胃口变好着。", "corrected_sentence": "最近我的胃口变好了。", "error_description": "错误：“变好”表示变化已经发生，后面应该用“了”，不能用“着”，应说“变好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长", "is_correct": true, "explanation": "长：与“短”构成反义，指时间长久，与“这个假期太短”相对。"}, {"text": "宽", "is_correct": false, "explanation": "宽：与“窄”相对，不与“短”构成反义。"}, {"text": "高", "is_correct": false, "explanation": "高：与“低”相对，不与“短”构成反义。"}, {"text": "厚", "is_correct": false, "explanation": "厚：与“薄”相对，不与“短”构成反义。"}], "correct_answer": "长", "explanations": {"长": "长：与“短”构成反义，指时间长久，与“这个假期太短”相对。", "宽": "宽：与“窄”相对，不与“短”构成反义。", "高": "高：与“低”相对，不与“短”构成反义。", "厚": "厚：与“薄”相对，不与“短”构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长", "is_correct": true, "explanation": "长：与“短”构成反义，指长度大，与“很短的裙子”相对。"}, {"text": "快", "is_correct": false, "explanation": "快：与“慢”相对，不与“短”构成反义。"}, {"text": "重", "is_correct": false, "explanation": "重：与“轻”相对，不与“短”构成反义。"}, {"text": "深", "is_correct": false, "explanation": "深：与“浅”相对，不与“短”构成反义。"}], "correct_answer": "长", "explanations": {"长": "长：与“短”构成反义，指长度大，与“很短的裙子”相对。", "快": "快：与“慢”相对，不与“短”构成反义。", "重": "重：与“轻”相对，不与“短”构成反义。", "深": "深：与“浅”相对，不与“短”构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "长度小，不长久。", "primary_collocate": null, "pronunciation": "duǎn", "ipa": "twan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这条裤子太短了。", "target_word": "短", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头发很短。", "target_word": "短", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬天白天短，晚上长。", "target_word": "短", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个假期太短，我哪里也没去。", "target_word": "短", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根绳子太短，不够用。", "target_word": "短", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "人的一生很短，要做喜欢的事。", "target_word": "短", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路比那条短五百米。", "target_word": "短", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在这家公司工作的时间很短。", "target_word": "短", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次开会时间很短，十分钟就完了。", "target_word": "短", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她穿着一条很短的裙子。", "target_word": "短", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "短短", "label": "重叠"}, {"form": "短期", "label": "复合"}, {"form": "缩短", "label": "复合"}], "register": "中性", "sense_fingerprint": "短：长度小，时间不长久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '464d8e31-3b58-4903-948d-c22c693dcaf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "短", "is_correct": true, "explanation": "短（第三声）：长度小，时间不长久。"}, {"text": "断", "is_correct": false, "explanation": "duàn（第四声）与 duǎn（第三声）声调不同，意思是切断、断开。"}, {"text": "端", "is_correct": false, "explanation": "duān（第一声）与 duǎn（第三声）声调不同，意思是端正、物体的一头。"}, {"text": "管", "is_correct": false, "explanation": "guǎn 与 duǎn 声母不同（g 与 d），意思是管子、管理。"}, {"text": "暖", "is_correct": false, "explanation": "nuǎn 与 duǎn 声母不同（n 与 d），意思是温暖。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn 与 duǎn 韵母不同（少了 u 介音），意思是胆子。"}], "explanations": {"短": "短（第三声）：长度小，时间不长久。", "断": "duàn（第四声）与 duǎn（第三声）声调不同，意思是切断、断开。", "端": "duān（第一声）与 duǎn（第三声）声调不同，意思是端正、物体的一头。", "管": "guǎn 与 duǎn 声母不同（g 与 d），意思是管子、管理。", "暖": "nuǎn 与 duǎn 声母不同（n 与 d），意思是温暖。", "胆": "dǎn 与 duǎn 韵母不同（少了 u 介音），意思是胆子。"}, "sentence_index": null, "correct_answer": "短"}, "level_3": {"options": [{"text": "短", "is_correct": true, "explanation": "短：长度小，与“太……了”搭配，表示裤子不够长。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容人的心情，不能用来形容裤子。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容裤子。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能说裤子太甜。"}], "explanations": {"短": "短：长度小，与“太……了”搭配，表示裤子不够长。", "高兴": "语义：“高兴”形容人的心情，不能用来形容裤子。", "聪明": "语义：“聪明”形容人的智力，不能用来形容裤子。", "甜": "搭配：“甜”形容味道，不能说裤子太甜。"}, "sentence_index": 0, "correct_answer": "短"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小孩比同学短很多。", "explanation": "这里应该用〈矮〉。短指长度小，说人的身高低要用矮。"}, {"text": "学校离我家很短。", "explanation": "这里应该用〈近〉。短指长度或时间小，说距离远近要用近。"}, {"text": "这间房子很短。", "explanation": "这里应该用〈小〉。短指长度小，说房间的大小要用小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "短", "is_correct": true, "explanation": "短（第三声）：长度小，时间不长久。"}, {"text": "段", "is_correct": false, "explanation": "duàn（第四声）与 duǎn（第三声）声调不同，意思是段落、一段。"}, {"text": "软", "is_correct": false, "explanation": "ruǎn 与 duǎn 声母不同（r 与 d），意思是柔软。"}, {"text": "款", "is_correct": false, "explanation": "kuǎn 与 duǎn 声母不同（k 与 d），意思是款项、款式。"}], "explanations": {"短": "短（第三声）：长度小，时间不长久。", "段": "duàn（第四声）与 duǎn（第三声）声调不同，意思是段落、一段。", "软": "ruǎn 与 duǎn 声母不同（r 与 d），意思是柔软。", "款": "kuǎn 与 duǎn 声母不同（k 与 d），意思是款项、款式。"}, "sentence_index": null, "correct_answer": "短"}, "level_3": {"options": [{"text": "短", "is_correct": true, "explanation": "短：长度小，与“比那条……五百米”搭配，表示这条路更短。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”形容速度，不能用来表示五百米的长度差。"}, {"text": "重", "is_correct": false, "explanation": "搭配：“重”说重量，不用来比较路的长度，不能说重五百米。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”形容物体的厚度，不能用来比较两条路的长度。"}], "explanations": {"短": "短：长度小，与“比那条……五百米”搭配，表示这条路更短。", "快": "语义：“快”形容速度，不能用来表示五百米的长度差。", "重": "搭配：“重”说重量，不用来比较路的长度，不能说重五百米。", "厚": "语义：“厚”形容物体的厚度，不能用来比较两条路的长度。"}, "sentence_index": 6, "correct_answer": "短"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班的学生很短，只有十个人。", "explanation": "这里应该用〈少〉。短指长度小，说人数多少要用少。"}, {"text": "这口井很短，绳子放下去也摸不到水。", "explanation": "这里应该用〈深〉。短指长度，井的深度要用深。"}, {"text": "这栋楼很短，站在楼下看不到顶。", "explanation": "这里应该用〈高〉。短指长度，建筑物的高度要用高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衬衫的袖子短很。", "corrected_sentence": "这件衬衫的袖子很短。", "error_description": "错误：“短很”。程度副词“很”要放在形容词前面，应为“很短”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一根很短地带子。", "corrected_sentence": "我买了一根很短的带子。", "error_description": "错误：“很短地带子”。修饰名词“带子”要用“的”，“地”用于修饰动词，应为“很短的带子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶劣", "is_correct": true, "explanation": "反义：“恶劣”与“良好”意义相反，指条件或品质很差，用于“天气”时正好相对。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：“复杂”说构成繁多，与“良好”没有反义关系。"}, {"text": "巨大", "is_correct": false, "explanation": "无关：“巨大”说规模或程度大，与“良好”不是反义词。"}, {"text": "清晰", "is_correct": false, "explanation": "无关：“清晰”说清楚、分明，与“良好”没有反义关系。"}], "correct_answer": "恶劣", "explanations": {"恶劣": "反义：“恶劣”与“良好”意义相反，指条件或品质很差，用于“天气”时正好相对。", "复杂": "无关：“复杂”说构成繁多，与“良好”没有反义关系。", "巨大": "无关：“巨大”说规模或程度大，与“良好”不是反义词。", "清晰": "无关：“清晰”说清楚、分明，与“良好”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶劣", "is_correct": true, "explanation": "反义：“恶劣”与“良好”意义相反，用于“状态”时指状况很差，正好相对。"}, {"text": "柔和", "is_correct": false, "explanation": "无关：“柔和”说光线或语气温和，与“良好”没有反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "无关：“辽阔”说范围广大，与“良好”不是反义词。"}, {"text": "坚固", "is_correct": false, "explanation": "无关：“坚固”说结实、不易损坏，与“良好”没有反义关系。"}], "correct_answer": "恶劣", "explanations": {"恶劣": "反义：“恶劣”与“良好”意义相反，用于“状态”时指状况很差，正好相对。", "柔和": "无关：“柔和”说光线或语气温和，与“良好”没有反义关系。", "辽阔": "无关：“辽阔”说范围广大，与“良好”不是反义词。", "坚固": "无关：“坚固”说结实、不易损坏，与“良好”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示一个人或事物让人满意或觉得不错。", "primary_collocate": null, "pronunciation": "liáng hǎo", "ipa": "liɑŋ˧˥ xɑʊ˧˩˦", "syllable_count": 2, "sentences": [{"text": "他给大家留下了良好的印象。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器目前运行良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的身体情况良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "良好的天气让比赛顺利进行。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子在学校表现良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的秩序一直良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两家公司的合作非常良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有良好的工作习惯。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术后，爷爷恢复良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理希望大家保持良好的状态。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "良好：人或事物令人满意、不错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '676cb373-aaf1-42e3-9e2e-cfe3ab4580b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "良好", "is_correct": true, "explanation": "正确：“良好”形容给人的印象令人满意，与“留下了……的印象”搭配。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色，不能用来修饰“印象”。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”说空气或物体含水分多，不能用来修饰“印象”。"}, {"text": "漫长", "is_correct": false, "explanation": "语义：“漫长”说时间很长，不能用来修饰印象。"}], "explanations": {"良好": "正确：“良好”形容给人的印象令人满意，与“留下了……的印象”搭配。", "鲜艳": "搭配：“鲜艳”形容颜色，不能用来修饰“印象”。", "潮湿": "语义：“潮湿”说空气或物体含水分多，不能用来修饰“印象”。", "漫长": "语义：“漫长”说时间很长，不能用来修饰印象。"}, "sentence_index": 0, "correct_answer": "良好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她长得很良好，穿上这件裙子非常显眼。", "explanation": "这里应该用〈漂亮〉。良好不用来形容人的外貌。"}, {"text": "听到这个消息，他非常良好。", "explanation": "这里应该用〈激动〉。良好说事物或状况，不用来表示人的情绪。"}, {"text": "那是一段非常良好的时光。", "explanation": "这里应该用〈美好〉。良好说状况达到标准，形容时光和回忆的感受要用美好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "良好", "is_correct": true, "explanation": "正确：“良好”形容合作的状况令人满意，与“非常”搭配自然。"}, {"text": "漆黑", "is_correct": false, "explanation": "搭配：“漆黑”说光线或颜色，不能用来形容合作。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”说人的性格，不能用来形容两家公司的合作。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”说物体沉重、不灵活，不能用来形容合作。"}], "explanations": {"良好": "正确：“良好”形容合作的状况令人满意，与“非常”搭配自然。", "漆黑": "搭配：“漆黑”说光线或颜色，不能用来形容合作。", "懒惰": "语义：“懒惰”说人的性格，不能用来形容两家公司的合作。", "笨重": "语义：“笨重”说物体沉重、不灵活，不能用来形容合作。"}, "sentence_index": 6, "correct_answer": "良好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家得知比赛获胜后都很良好。", "explanation": "这里应该用〈快乐〉。良好不用来描述人的心情。"}, {"text": "他是一位良好的画家，作品很有名。", "explanation": "这里应该用〈伟大〉。良好不用来评价人的卓越成就。"}, {"text": "雨下得很良好，路面全湿了。", "explanation": "这里应该用〈大〉。“良好”说状况达到标准，不用来形容降雨的强弱，应说“下得很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的身体情况非常良好极了。", "corrected_sentence": "她的身体情况非常良好。", "error_description": "程度重复：“非常”已经修饰“良好”，后面不能再加“极了”，应去掉“极了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅的服务态度很良好地。", "corrected_sentence": "这家餐厅的服务态度很良好。", "error_description": "结构错误：“良好”作谓语形容词时后面不加“地”，“地”只用于修饰动词，应说“很良好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
