INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23302, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人住在一起的地方。", "primary_collocate": null, "pronunciation": "zhù zhái qū", "ipa": "tʂu˥˩ tʂaɪ˧˥ tɕʰy˥˥", "syllable_count": 3, "sentences": [{"text": "这个住宅区住着几千个人。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个住宅区的门口夜里有保安。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住宅区里的孩子常在一起玩儿。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天走路穿过住宅区去上班。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新住宅区的房子卖得很快。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住宅区中间有一个大花园。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个住宅区的邻居都很热情。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员把包裹送到了住宅区。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城东有一个很大的住宅区。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住宅区里不能大声放音乐。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "住宅區", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "住宅区：很多人聚居的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '676cb373-aaf1-42e3-9e2e-cfe3ab4580b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住宅区", "is_correct": true, "explanation": "正确：“住宅区”是很多人聚居的地方，与“住着几千个人”搭配。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店是卖书的场所，不是供几千人居住的地方。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是供人游览的地方，不能用来居住。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“花瓶”是器物，不能与“住着几千个人”搭配。"}], "explanations": {"住宅区": "正确：“住宅区”是很多人聚居的地方，与“住着几千个人”搭配。", "书店": "语义：书店是卖书的场所，不是供几千人居住的地方。", "公园": "语义：公园是供人游览的地方，不能用来居住。", "花瓶": "搭配：“花瓶”是器物，不能与“住着几千个人”搭配。"}, "sentence_index": 0, "correct_answer": "住宅区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个住宅区的病床都住满了病人。", "explanation": "这里应该用〈医院〉。住宅区是供人居住的地方，住满病人、摆着病床的要说医院。"}, {"text": "我住的住宅区只有一间卧室。", "explanation": "这里应该用〈住宅〉。住宅区指很多人聚居的地方；只有一间卧室的要说住宅。"}, {"text": "这个住宅区的跑道很长，飞机起降不断。", "explanation": "这里应该用〈机场〉。住宅区是供人居住的地方，跑道、飞机起降的要说机场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住宅区", "is_correct": true, "explanation": "正确：“住宅区”里住着很多人，邻居之间有往来，与“邻居都很热情”搭配。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，没有邻居，不能说“邻居都很热情”。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：衣柜是家具，没有邻居，不能这样说。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“的邻居”需要有人群居住的地方，汽车不能与之搭配。"}], "explanations": {"住宅区": "正确：“住宅区”里住着很多人，邻居之间有往来，与“邻居都很热情”搭配。", "钢琴": "语义：钢琴是乐器，没有邻居，不能说“邻居都很热情”。", "衣柜": "语义：衣柜是家具，没有邻居，不能这样说。", "汽车": "搭配：“的邻居”需要有人群居住的地方，汽车不能与之搭配。"}, "sentence_index": 6, "correct_answer": "住宅区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "住宅区的站台上挤满了旅客，列车正在进站。", "explanation": "这里应该用〈车站〉。住宅区是供人居住的地方，站台、列车进站的要说车站。"}, {"text": "住宅区的教室里坐满了学生，老师在讲课。", "explanation": "这里应该用〈学校〉。住宅区是供人居住的地方，有教室、老师讲课的要说学校。"}, {"text": "住宅区的跑道上有很多选手在比赛，观众席坐满了人。", "explanation": "这里应该用〈体育场〉。住宅区是居住场所，选手比赛、观众席的要说体育场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城西新建了一只大型住宅区。", "corrected_sentence": "城西新建了一片大型住宅区。", "error_description": "量词错误：“住宅区”应用“片”或“个”，“只”用于动物或成对的物品，应说“一片大型住宅区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅住在一个很大住宅区里。", "corrected_sentence": "我舅舅住在一个很大的住宅区里。", "error_description": "结构错误：“很大”修饰名词“住宅区”时要加“的”，应说“一个很大的住宅区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fddabd29-f21c-4fbb-a76b-82532fb55e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "打击", "is_correct": true, "explanation": "打击与“鼓励”意思相反，指使人失去信心，是这一义项的反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步是日常活动，与“鼓励”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉是作息行为，与“鼓励”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字是书写动作，与“鼓励”没有反义关系。"}], "correct_answer": "打击", "explanations": {"打击": "打击与“鼓励”意思相反，指使人失去信心，是这一义项的反义关系。", "散步": "散步是日常活动，与“鼓励”没有反义关系。", "睡觉": "睡觉是作息行为，与“鼓励”没有反义关系。", "写字": "写字是书写动作，与“鼓励”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
