INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人觉得有信心、想去做一件事。", "primary_collocate": null, "pronunciation": "gǔ lì", "ipa": "ku˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "老师鼓励我多说汉语。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的话鼓励了我。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈总是鼓励孩子自己做事。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考得不好，我们应该鼓励他。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司鼓励大家骑车上班。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷大声鼓励着运动员。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸鼓励弟弟参加比赛。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别批评他，多鼓励他吧。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校鼓励学生每天读书。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着鼓励我别怕，试试看。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鼓励了", "label": "完成体"}, {"form": "鼓励着", "label": "持续体"}, {"form": "鼓励过", "label": "经历体"}, {"form": "鼓励鼓励", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用话或行动给人信心，让人愿意去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55f2e96c-13a5-42cd-ab9f-f21f3b3466c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鼓励", "is_correct": true, "explanation": "正确答案。鼓励 gǔlì 指用话或行动给人信心，让人愿意去做事。"}, {"text": "努力", "is_correct": false, "explanation": "努力 nǔlì 与 gǔlì 声母不同（n 与 g），意思是尽力做事，不是给人信心。"}, {"text": "武力", "is_correct": false, "explanation": "武力 wǔlì 与 gǔlì 首音不同（w 与 g），意思是武装力量。"}, {"text": "苦力", "is_correct": false, "explanation": "苦力 kǔlì 与 gǔlì 声母不同（k 与 g），意思是出卖体力的劳动者。"}], "explanations": {"鼓励": "正确答案。鼓励 gǔlì 指用话或行动给人信心，让人愿意去做事。", "努力": "努力 nǔlì 与 gǔlì 声母不同（n 与 g），意思是尽力做事，不是给人信心。", "武力": "武力 wǔlì 与 gǔlì 首音不同（w 与 g），意思是武装力量。", "苦力": "苦力 kǔlì 与 gǔlì 声母不同（k 与 g），意思是出卖体力的劳动者。"}, "sentence_index": null, "correct_answer": "鼓励"}, "level_3": {"options": [{"text": "鼓励", "is_correct": true, "explanation": "鼓励指让学生有信心多说汉语，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“我多说汉语”不能搭配，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能带“我多说汉语”这样的宾语，句子不成立。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”的宾语应是文字或文章，不能直接接“我”作宾语。"}], "explanations": {"鼓励": "鼓励指让学生有信心多说汉语，符合语境。", "吃": "语义：“吃”与“我多说汉语”不能搭配，句子不通。", "唱": "语义：“唱”不能带“我多说汉语”这样的宾语，句子不成立。", "写": "配价：“写”的宾语应是文字或文章，不能直接接“我”作宾语。"}, "sentence_index": 0, "correct_answer": "鼓励"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题很难，我们应该鼓励这个问题。", "explanation": "这里应该用〈解决〉。“鼓励”的对象是人，让人有信心去做事，不能“鼓励问题”。"}, {"text": "这个周末天气很好，我们应该鼓励这个天气。", "explanation": "这里应该用〈享受〉。“鼓励”是让人有信心去做事，不能用于天气，应说“享受这个天气”。"}, {"text": "我很同情他的遭遇，也很鼓励他的遭遇。", "explanation": "这里“鼓励”被当作“对遭遇表示关切、怜悯”的意思使用。“鼓励”指让人有信心去做事，不能用于遭遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鼓励", "is_correct": true, "explanation": "正确答案。鼓励 gǔlì 指用话或行动给人信心，让人愿意去做事。"}, {"text": "孤立", "is_correct": false, "explanation": "孤立 gūlì 与 gǔlì 第一个音节声调不同（第一声与第三声），意思是脱离群体、单独存在。"}, {"text": "主力", "is_correct": false, "explanation": "主力 zhǔlì 与 gǔlì 声母不同（zh 与 g），意思是主要的力量。"}, {"text": "古礼", "is_correct": false, "explanation": "古礼 gǔlǐ 与 gǔlì 第二个音节声调不同（第三声与第四声），意思是古代的礼仪。"}], "explanations": {"鼓励": "正确答案。鼓励 gǔlì 指用话或行动给人信心，让人愿意去做事。", "孤立": "孤立 gūlì 与 gǔlì 第一个音节声调不同（第一声与第三声），意思是脱离群体、单独存在。", "主力": "主力 zhǔlì 与 gǔlì 声母不同（zh 与 g），意思是主要的力量。", "古礼": "古礼 gǔlǐ 与 gǔlì 第二个音节声调不同（第三声与第四声），意思是古代的礼仪。"}, "sentence_index": null, "correct_answer": "鼓励"}, "level_3": {"options": [{"text": "鼓励", "is_correct": true, "explanation": "鼓励指让弟弟有信心去参加比赛，符合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清洁房间，不能用来指让弟弟参加比赛。"}, {"text": "熨", "is_correct": false, "explanation": "配价：熨的对象是衣物，不能接“弟弟”作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗弟弟参加比赛”搭配不通，句子不成立。"}], "explanations": {"鼓励": "鼓励指让弟弟有信心去参加比赛，符合语境。", "打扫": "语义：打扫是清洁房间，不能用来指让弟弟参加比赛。", "熨": "配价：熨的对象是衣物，不能接“弟弟”作宾语。", "洗": "语义：“洗弟弟参加比赛”搭配不通，句子不成立。"}, "sentence_index": 6, "correct_answer": "鼓励"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她笑着鼓励了我的头发。", "explanation": "这里应该用〈摸〉。“鼓励”的对象是人，给人信心，不能用于头发。"}, {"text": "这句话鼓励了他的感情。", "explanation": "这里应该用〈伤害〉。“鼓励”让人有信心，不能用于感情；这句话伤了他的感情，应说“伤害”。"}, {"text": "我鼓励这杯咖啡很好喝。", "explanation": "这里应该用〈觉得〉。表达自己的看法用“觉得”，“鼓励”是给人信心去做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们大声鼓励了着运动员。", "corrected_sentence": "同学们大声鼓励着运动员。", "error_description": "“鼓励”后面的“了”和“着”不能同时使用。表示持续状态只用“着”，错误形式是“鼓励了着”，正确形式是“鼓励着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师鼓励让我参加比赛。", "corrected_sentence": "老师鼓励我参加比赛。", "error_description": "错误：「鼓励」本身已含有“使人去做”的意思，后面不能再加「让」。错误形式是「鼓励让我」，正确形式是「鼓励我」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
