INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23310, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "节约能源，不浪费电、燃气等。", "primary_collocate": null, "pronunciation": "jié néng", "ipa": "tɕjɛ˧˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "离开房间时关灯，这样做很节能。", "target_word": "节能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要从小事做起，在家里节能。", "target_word": "节能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调调到二十六度，比较节能。", "target_word": "节能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么在家节能。", "target_word": "节能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用完电脑要关机，这样才节能。", "target_word": "节能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会节能，出门总是关灯。", "target_word": "节能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上电视没人看，关了才节能。", "target_word": "节能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种洗衣机又节能又省水。", "target_word": "节能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气不热的时候，别开空调，节能一点。", "target_word": "节能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，节能就是不浪费电。", "target_word": "节能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "节能灯", "label": "复合"}, {"form": "节能减排", "label": "复合"}, {"form": "節能", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常生活中节约用电等能源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ac478c-d2a4-4826-b52d-f8c1c150350f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "节能", "is_correct": true, "explanation": "正确：离开房间时关灯，不浪费用电，句意通顺。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”与“离开房间时关灯”的做法相矛盾，不符合句意。"}, {"text": "耗电", "is_correct": false, "explanation": "语义：“耗电”与“关灯”的目的相反，不符合句意。"}, {"text": "通风", "is_correct": false, "explanation": "搭配：“很通风”修饰空间或空气，不能修饰“这样做”。"}], "explanations": {"节能": "正确：离开房间时关灯，不浪费用电，句意通顺。", "浪费": "语义：“浪费”与“离开房间时关灯”的做法相矛盾，不符合句意。", "耗电": "语义：“耗电”与“关灯”的目的相反，不符合句意。", "通风": "搭配：“很通风”修饰空间或空气，不能修饰“这样做”。"}, "sentence_index": 0, "correct_answer": "节能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校号召大家节能纸张。", "explanation": "这里应该用〈节约〉。“节能”只指节约能源（如电），纸张要说“节约”。"}, {"text": "这次改造节能了开支。", "explanation": "这里应该用〈节省〉。“节省”可以搭配开支、费用，“节能”不能搭配开支。"}, {"text": "我们要节能成本。", "explanation": "这里应该用〈降低〉。“降低”可以搭配成本，“节能”只指节约能源，不带宾语“成本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05cbb5c7-136f-4bad-b749-a1d635bfd01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节能", "is_correct": true, "explanation": "正确：关掉没人看的电视才能省电，与句意相符。"}, {"text": "开机", "is_correct": false, "explanation": "语义：电视没人看时关掉，不能说“关了才开机”，与句意矛盾。"}, {"text": "充电", "is_correct": false, "explanation": "搭配：“关了才”后接的动作应与“关”相配，“充电”与关电视的语境不搭。"}, {"text": "看电视", "is_correct": false, "explanation": "语义：电视没人看时关掉，不能说“关了才看电视”，与句意相矛盾。"}], "explanations": {"节能": "正确：关掉没人看的电视才能省电，与句意相符。", "开机": "语义：电视没人看时关掉，不能说“关了才开机”，与句意矛盾。", "充电": "搭配：“关了才”后接的动作应与“关”相配，“充电”与关电视的语境不搭。", "看电视": "语义：电视没人看时关掉，不能说“关了才看电视”，与句意相矛盾。"}, "sentence_index": 6, "correct_answer": "节能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种新书架节能了很多空间。", "explanation": "这里应该用〈节省〉。“节省”可以用于空间、时间、金钱；“节能”只指节约能源，不能用于空间。"}, {"text": "工厂要节能废气。", "explanation": "这里应该用〈减排〉。“减排”指减少排放的废气；“节能”只指节约能源。"}, {"text": "我们节能了很多时间。", "explanation": "这里应该用〈节省〉。“节省”可以用于时间，“节能”只指节约能源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05cbb5c7-136f-4bad-b749-a1d635bfd01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "少开空调，节能一个吧。", "corrected_sentence": "少开空调，节能一点吧。", "error_description": "数量补语错误：动词“节能”后表示程度的数量补语应用“一点”，说“节能一点”，不能说“节能一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05cbb5c7-136f-4bad-b749-a1d635bfd01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一台节能得洗衣机。", "corrected_sentence": "我买了一台节能的洗衣机。", "error_description": "结构助词错误：“节能”修饰名词“洗衣机”时应用“的”，不能用“得”，应说“节能的洗衣机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05cbb5c7-136f-4bad-b749-a1d635bfd01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23312, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "改变", "is_correct": true, "explanation": "反义词：「保持」指状态不变，「改变」指使状态发生变化，两者相反。"}, {"text": "出发", "is_correct": false, "explanation": "无关：「出发」指动身离开，与「保持」的不变含义没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "无关：「研究」指探究事理，与「保持」没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "无关：「参加」指加入某项活动，与「保持」没有反义关系。"}], "correct_answer": "改变", "explanations": {"改变": "反义词：「保持」指状态不变，「改变」指使状态发生变化，两者相反。", "出发": "无关：「出发」指动身离开，与「保持」的不变含义没有反义关系。", "研究": "无关：「研究」指探究事理，与「保持」没有反义关系。", "参加": "无关：「参加」指加入某项活动，与「保持」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
