INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23312, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一直这样，不改变。", "primary_collocate": null, "pronunciation": "bǎo chí", "ipa": "pau̯˨˩˦ tʂʰʅ˧˥", "syllable_count": 2, "sentences": [{"text": "请保持安静，孩子在睡觉。", "target_word": "保持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天运动，所以一直保持健康。", "target_word": "保持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间要经常打扫，保持干净。", "target_word": "保持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱可以让牛奶保持新鲜。", "target_word": "保持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们离开北京以后，一直保持着联系。", "target_word": "保持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的时候，要和前面的车保持一定的距离。", "target_word": "保持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天笑呵呵的，一直保持好心情。", "target_word": "保持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛中，他一直保持第一名。", "target_word": "保持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子能让水一整天保持温热。", "target_word": "保持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分开多年了，但还是保持着好朋友的关系。", "target_word": "保持", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保持了", "label": "体标"}, {"form": "保持着", "label": "体标"}, {"form": "保持过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：让某种状态或情况一直不变地继续下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37088c36-b988-4c59-bd87-98a844545e6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23312, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "保持", "is_correct": true, "explanation": "正确。保持（bǎo chí）表示一直这样，不改变。"}, {"text": "宝石", "is_correct": false, "explanation": "bǎoshí（宝石）与 bǎochí 只有第二音节声母不同（sh 与 ch），意思是一种珍贵的矿物。"}, {"text": "包吃", "is_correct": false, "explanation": "bāochī（包吃）与 bǎochí 两个音节的声调都不同，意思是包伙食。"}, {"text": "报时", "is_correct": false, "explanation": "bàoshí（报时）第一音节声调不同（bào 第四声），第二音节声母不同（sh 与 ch），意思是报告时间。"}], "explanations": {"保持": "正确。保持（bǎo chí）表示一直这样，不改变。", "宝石": "bǎoshí（宝石）与 bǎochí 只有第二音节声母不同（sh 与 ch），意思是一种珍贵的矿物。", "包吃": "bāochī（包吃）与 bǎochí 两个音节的声调都不同，意思是包伙食。", "报时": "bàoshí（报时）第一音节声调不同（bào 第四声），第二音节声母不同（sh 与 ch），意思是报告时间。"}, "sentence_index": null, "correct_answer": "保持"}, "level_3": {"options": [{"text": "保持", "is_correct": true, "explanation": "正确。「请保持安静」表示要求一直安静，与「孩子在睡觉」的语境吻合。"}, {"text": "打破", "is_correct": false, "explanation": "语义：「打破」表示破坏已有的状态，与「请…安静，孩子在睡觉」的要求相反。"}, {"text": "失去", "is_correct": false, "explanation": "搭配：「失去」一般接具体事物或机会，不能用来对别人提出「失去安静」的要求。"}, {"text": "改变", "is_correct": false, "explanation": "语义：「改变」表示使状态变化，与句中要求维持安静的意思相反。"}], "explanations": {"保持": "正确。「请保持安静」表示要求一直安静，与「孩子在睡觉」的语境吻合。", "打破": "语义：「打破」表示破坏已有的状态，与「请…安静，孩子在睡觉」的要求相反。", "失去": "搭配：「失去」一般接具体事物或机会，不能用来对别人提出「失去安静」的要求。", "改变": "语义：「改变」表示使状态变化，与句中要求维持安静的意思相反。"}, "sentence_index": 0, "correct_answer": "保持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一脚保持了那扇门。", "explanation": "这里应该用〈踢开〉。“保持”是使已有状态不变，不能表示用脚使门被推开。"}, {"text": "他不小心保持了牛奶。", "explanation": "这里应该用〈打翻〉。「保持」的对象是状态或关系，不能用来表示牛奶被碰翻了。"}, {"text": "大风保持了房顶。", "explanation": "这里应该用〈损坏〉。「保持」是使已有状态不变，不能用来表示房顶受到破坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保持", "is_correct": true, "explanation": "正确。「一直保持好心情」表示好心情持续不变，与「笑呵呵」的描写吻合。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：「丢失」表示失去或找不到，与「一直」所强调的持续状态相反。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：「放弃」表示不再坚持，与句中「笑呵呵」的持续好心情矛盾。"}, {"text": "损害", "is_correct": false, "explanation": "搭配：「损害」一般接健康、利益等对象，不能说「损害好心情」。"}], "explanations": {"保持": "正确。「一直保持好心情」表示好心情持续不变，与「笑呵呵」的描写吻合。", "丢失": "语义：「丢失」表示失去或找不到，与「一直」所强调的持续状态相反。", "放弃": "语义：「放弃」表示不再坚持，与句中「笑呵呵」的持续好心情矛盾。", "损害": "搭配：「损害」一般接健康、利益等对象，不能说「损害好心情」。"}, "sentence_index": 6, "correct_answer": "保持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爱迪生保持了电灯。", "explanation": "这里应该用〈发明〉。「发明」指创造出从前没有的东西，「保持」是使已有状态不变，不能用于电灯。"}, {"text": "他保持了那片药。", "explanation": "这里应该用〈吞下〉。「保持」用于状态或关系，不能用来表示把药片吃进肚子里。"}, {"text": "他保持了我的邀请。", "explanation": "这里应该用〈拒绝〉。「保持」不能用来表示不接受别人的邀请，表示不接受要用〈拒绝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们一直保持得好关系。", "corrected_sentence": "他们一直保持着好关系。", "error_description": "错在「得」。「着」表示持续状态，要紧跟动词「保持」，应说「他们一直保持着好关系」；「得」用于动词后接补语，不能说「他们一直保持得好关系」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直保持一直健康。", "corrected_sentence": "他一直保持健康。", "error_description": "错在多出的「一直」。「一直」在「保持」前面已经用过一次，句中不能再在动词和形容词之间重复，应说「他一直保持健康」，不能说「他一直保持一直健康」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
