INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23314, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "是列车停靠的地方，人们可以在这里上车或下车。", "primary_collocate": null, "pronunciation": "dì tiě zhàn", "ipa": "ti˥˩ tʰjɛ˨˩˦ ʈʂan˥˩", "syllable_count": 3, "sentences": [{"text": "车到了地铁站，门一开，人们就下车了。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好八点在地铁站见面。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站的牌子上写着站名。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早上走到地铁站坐车上班。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在地铁站等车，手里拿着一杯咖啡。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地铁站很干净，也很安全。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站里有地铁线路图，你可以先看看。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下车以后，我在地铁站里找到了出口。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末地铁站里有很多去玩的人。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的地铁站离公园很近，去玩很方便。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地铁站台", "label": "复合"}, {"form": "地鐵站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "列车停靠、人们上下车的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ac478c-d2a4-4826-b52d-f8c1c150350f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地铁站", "is_correct": true, "explanation": "正确：列车停靠、乘客上下车的地方，与“车到了……门一开”的语境一致。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：车不会开到厨房，“车到了”后接的应是停靠点。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：车不能开进卧室，与句意相矛盾。"}, {"text": "旅客", "is_correct": false, "explanation": "配价：“车到了”要求处所作宾语，“旅客”是人，不能作为停靠的地点。"}], "explanations": {"地铁站": "正确：列车停靠、乘客上下车的地方，与“车到了……门一开”的语境一致。", "厨房": "语义：车不会开到厨房，“车到了”后接的应是停靠点。", "卧室": "语义：车不能开进卧室，与句意相矛盾。", "旅客": "配价：“车到了”要求处所作宾语，“旅客”是人，不能作为停靠的地点。"}, "sentence_index": 0, "correct_answer": "地铁站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地铁站从市中心一直修到了郊区。", "explanation": "这里应该用〈地铁线〉。“修到郊区”说的是线路，地铁站只是一个站点，不能这样说。"}, {"text": "我每天早上坐地铁站上班。", "explanation": "这里应该用〈列车〉。“坐”的对象是列车等交通工具，地铁站是停靠点，不能坐。"}, {"text": "他骑着地铁站去上班。", "explanation": "这里应该用〈自行车〉。“骑”的对象是自行车、摩托车等可以骑的车，地铁站是站点，不能骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05cbb5c7-136f-4bad-b749-a1d635bfd01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地铁站", "is_correct": true, "explanation": "正确：地铁站内张贴线路图，与句意相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里不会有地铁线路图，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头里放不下线路图，与句意相矛盾。"}, {"text": "老师", "is_correct": false, "explanation": "配价：“里”要求处所，“老师”是人，不能作为存放线路图的地方。"}], "explanations": {"地铁站": "正确：地铁站内张贴线路图，与句意相符。", "冰箱": "语义：冰箱里不会有地铁线路图，句意不通。", "石头": "语义：石头里放不下线路图，与句意相矛盾。", "老师": "配价：“里”要求处所，“老师”是人，不能作为存放线路图的地方。"}, "sentence_index": 6, "correct_answer": "地铁站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他沿着地铁站走了三公里。", "explanation": "这里应该用〈地铁线〉。“沿着……走”指沿路线行走，地铁站是一个点，不是路线。"}, {"text": "这个地铁站停在了三楼。", "explanation": "这里应该用〈电梯〉。“停”可用于电梯，地铁站是车站，不能停在某一楼层。"}, {"text": "他开着地铁站去上班。", "explanation": "这里应该用〈汽车〉。“开”的对象是车辆，地铁站是车站，不能开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05cbb5c7-136f-4bad-b749-a1d635bfd01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们坐的车到了一辆地铁站，门一开大家就下车了。", "corrected_sentence": "我们坐的车到了一个地铁站，门一开大家就下车了。", "error_description": "量词错误：“地铁站”应使用量词“个”，不能用“辆”（“辆”用于车辆）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05cbb5c7-136f-4bad-b749-a1d635bfd01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在一条地铁站门口等我。", "corrected_sentence": "他在一个地铁站门口等我。", "error_description": "量词错误：“地铁站”应使用量词“个”，不能用“条”（“条”用于狭长的事物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05cbb5c7-136f-4bad-b749-a1d635bfd01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23316, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破坏", "is_correct": true, "explanation": "正确。「破坏」与「建设」构成反义关系，指使事物损坏。"}, {"text": "旅行", "is_correct": false, "explanation": "与「建设」无反义关系，「旅行」指出行游览。"}, {"text": "思考", "is_correct": false, "explanation": "与「建设」无反义关系，「思考」指用脑想问题。"}, {"text": "散步", "is_correct": false, "explanation": "与「建设」无反义关系，「散步」指慢慢走路。"}], "correct_answer": "破坏", "explanations": {"破坏": "正确。「破坏」与「建设」构成反义关系，指使事物损坏。", "旅行": "与「建设」无反义关系，「旅行」指出行游览。", "思考": "与「建设」无反义关系，「思考」指用脑想问题。", "散步": "与「建设」无反义关系，「散步」指慢慢走路。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23316, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破坏", "is_correct": true, "explanation": "正确。「破坏」与「建设」构成反义关系，指使事物损坏。"}, {"text": "学习", "is_correct": false, "explanation": "与「建设」无反义关系，「学习」指获得知识或技能。"}, {"text": "唱歌", "is_correct": false, "explanation": "与「建设」无反义关系，「唱歌」指发声演唱。"}, {"text": "游泳", "is_correct": false, "explanation": "与「建设」无反义关系，「游泳」指在水中活动。"}], "correct_answer": "破坏", "explanations": {"破坏": "正确。「破坏」与「建设」构成反义关系，指使事物损坏。", "学习": "与「建设」无反义关系，「学习」指获得知识或技能。", "唱歌": "与「建设」无反义关系，「唱歌」指发声演唱。", "游泳": "与「建设」无反义关系，「游泳」指在水中活动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23316, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "建设就是修建房子、道路、桥等设施。", "primary_collocate": null, "pronunciation": "jiàn shè", "ipa": "tɕjɛn˥˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "政府正在建设一座新桥。", "target_word": "建设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市需要建设更多公园。", "target_word": "建设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在山里建设新路。", "target_word": "建设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的学校在建设新楼。", "target_word": "建设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，国家建设了很多高铁。", "target_word": "建设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们在河上建设了一座新桥。", "target_word": "建设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去西部帮忙建设新学校。", "target_word": "建设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司打算在海边建设一个大酒店。", "target_word": "建设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府在这个小村子里建设了一排新房子。", "target_word": "建设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了方便老人，社区建设了一个新公园。", "target_word": "建设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "建设了", "label": "体标"}, {"form": "建设过", "label": "体标"}, {"form": "建设者", "label": "复合"}], "register": "中性", "sense_fingerprint": "建设：修建、建造房屋、道路等设施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 村子 (Zipf 3.93), 一排 (Zipf 3.62), 新房子 (Zipf 3.08)']::text[], 'ce010c66-d877-4df7-8147-8f6d54c7cf13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建设", "is_correct": true, "explanation": "正确。句中“政府正在……一座新桥”指修建桥梁，应填「建设」。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」的对象不能是桥，“吃一座新桥”说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」的对象是歌曲，不能是一座桥。"}, {"text": "生病", "is_correct": false, "explanation": "配价：「生病」是不及物动词，不能带“一座新桥”作宾语。"}], "explanations": {"建设": "正确。句中“政府正在……一座新桥”指修建桥梁，应填「建设」。", "吃": "语义：「吃」的对象不能是桥，“吃一座新桥”说不通。", "唱": "语义：「唱」的对象是歌曲，不能是一座桥。", "生病": "配价：「生病」是不及物动词，不能带“一座新桥”作宾语。"}, "sentence_index": 0, "correct_answer": "建设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位作家建设了一部新小说。", "explanation": "这里应该用〈写〉。「建设」指修建房屋、道路等具体工程，小说是创作，要用「写」。"}, {"text": "公司决定建设一个新的基金。", "explanation": "这里应该用〈设立〉。「基金」这类机构要用「设立」，「建设」指修建工程。"}, {"text": "警察在路口建设了路障。", "explanation": "这里应该用〈设置〉。「路障」是临时摆放的东西，要用「设置」，「建设」指长期工程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建设", "is_correct": true, "explanation": "正确。句中“去西部帮忙……新学校”指修建学校，应填「建设」。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」的对象不能是学校，“咬新学校”说不通。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：「微笑」是不及物动词，不能带“新学校”作宾语。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：「咳嗽」是不及物动词，不能带宾语。"}], "explanations": {"建设": "正确。句中“去西部帮忙……新学校”指修建学校，应填「建设」。", "咬": "语义：「咬」的对象不能是学校，“咬新学校”说不通。", "微笑": "配价：「微笑」是不及物动词，不能带“新学校”作宾语。", "咳嗽": "配价：「咳嗽」是不及物动词，不能带宾语。"}, "sentence_index": 6, "correct_answer": "建设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们建设了一个环保小组。", "explanation": "这里应该用〈成立〉。「小组」这类组织要用「成立」，「建设」指修建工程。"}, {"text": "学校建设了一场比赛。", "explanation": "这里应该用〈举办〉。「比赛」是活动，要用「举办」，不能用「建设」。"}, {"text": "父母要建设孩子的兴趣。", "explanation": "这里应该用〈培养〉。「兴趣」是抽象的东西，要用「培养」，「建设」指修建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们正在建设了一条新路。", "corrected_sentence": "工人们正在建设一条新路。", "error_description": "体标错误：「正在」表示动作进行中，不能和表示完成的「了」一起用在「建设」上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们建设了过一座小桥。", "corrected_sentence": "我们建设过一座小桥。", "error_description": "体标错误：应为「建设过」。「了」与「过」不能同时用在同一动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
