INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23322, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "管理国家或地方公共事务的机构和人员。", "primary_collocate": null, "pronunciation": "zhèng fǔ", "ipa": "ʈʂɤŋ˥˩ fu˨˩˦", "syllable_count": 2, "sentences": [{"text": "政府在城里建了一座新医院。", "target_word": "政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府帮助很多农村的学生。", "target_word": "政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要求大家不要在公园里抽烟。", "target_word": "政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的政府每年都会花钱修路。", "target_word": "政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在政府工作，帮助别人。", "target_word": "政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给老人发了生活费。", "target_word": "政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨太多，政府让学校放假了。", "target_word": "政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人给政府写信，说公共汽车太少。", "target_word": "政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府的新办法让大家的生活更方便。", "target_word": "政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新政府上个月开始工作了。", "target_word": "政府", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "管理国家或地方公共事务的机构和人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe847b-453c-49ae-ad59-f1b51c9b852b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23322, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "政府", "is_correct": true, "explanation": "正确。政府（zhèng fǔ），管理国家或地方公共事务的机构和人员。"}, {"text": "正负", "is_correct": false, "explanation": "政府（zhèng fǔ）与正负（zhèng fù）第二个音节声调不同，“正负”意思是正数和负数。"}, {"text": "征服", "is_correct": false, "explanation": "政府（zhèng fǔ）与征服（zhēng fú）两个音节的声调都不同，“征服”意思是用力量使人屈服。"}, {"text": "政法", "is_correct": false, "explanation": "政府（zhèng fǔ）与政法（zhèng fǎ）第二个音节声调不同，“政法”指政治和法律。"}], "explanations": {"政府": "正确。政府（zhèng fǔ），管理国家或地方公共事务的机构和人员。", "正负": "政府（zhèng fǔ）与正负（zhèng fù）第二个音节声调不同，“正负”意思是正数和负数。", "征服": "政府（zhèng fǔ）与征服（zhēng fú）两个音节的声调都不同，“征服”意思是用力量使人屈服。", "政法": "政府（zhèng fǔ）与政法（zhèng fǎ）第二个音节声调不同，“政法”指政治和法律。"}, "sentence_index": null, "correct_answer": "政府"}, "level_3": {"options": [{"text": "政府", "is_correct": true, "explanation": "正确。“政府”是管理公共事务的机构，可以作“建”的主语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」既不是人也不是机构，不能作“建”的主语。"}, {"text": "学生", "is_correct": false, "explanation": "配价：“建”的主语应是有能力组织建造的机构或人，“学生”不能作为建设医院的主体。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”是动物，不能建造医院。"}], "explanations": {"政府": "正确。“政府”是管理公共事务的机构，可以作“建”的主语。", "天气": "语义：「天气」既不是人也不是机构，不能作“建”的主语。", "学生": "配价：“建”的主语应是有能力组织建造的机构或人，“学生”不能作为建设医院的主体。", "小猫": "语义：“小猫”是动物，不能建造医院。"}, "sentence_index": 0, "correct_answer": "政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个政府每年有九百万人口。", "explanation": "这里应该用〈国家〉。“政府”指管理机构，不指人口或领土，不能说有多少人口。"}, {"text": "这位政府是我的老同学。", "explanation": "这里应该用〈他〉或〈她〉。“政府”是机构，不能作为一个人出现。"}, {"text": "我昨天在政府吃了两个包子。", "explanation": "这里应该用〈食堂〉或〈饭馆〉。“政府”是机构，不是吃饭的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政府", "is_correct": true, "explanation": "正确。“政府”能决定让学校放假，符合句中的语境。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：“香蕉”是水果，不能决定让学校放假。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：“让”的主语应是能做决定的人或机构，“椅子”不能作为主语。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不能让学校放假。"}], "explanations": {"政府": "正确。“政府”能决定让学校放假，符合句中的语境。", "香蕉": "语义：“香蕉”是水果，不能决定让学校放假。", "椅子": "配价：“让”的主语应是能做决定的人或机构，“椅子”不能作为主语。", "书包": "语义：“书包”是物品，不能让学校放假。"}, "sentence_index": 6, "correct_answer": "政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新政府上个月开始接诊病人了。", "explanation": "这里应该用〈医院〉。“政府”是管理机构，不接诊病人。"}, {"text": "新政府上个月开始营业了。", "explanation": "这里应该用〈商店〉。“政府”不做买卖，不说“营业”。"}, {"text": "这位新政府是我的邻居。", "explanation": "这里应该用〈他〉或〈她〉。“政府”是机构，不能作为一个人出现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府们决定修一条新路。", "corrected_sentence": "政府决定修一条新路。", "error_description": "“政府”是集体名词，后面不加“们”，应说“政府决定修一条新路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位政府很重视教育。", "corrected_sentence": "这个政府很重视教育。", "error_description": "“政府”是机构，不指人，不能用量词“位”来数，应说“这个政府很重视教育”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
