INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23326, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "车厢是火车或汽车里坐人或放东西的地方。", "primary_collocate": null, "pronunciation": "chē xiāng", "ipa": "ʈʂʰɤ˥ ɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "车厢里很安静，大家都在看书。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的座位在最后一节车厢。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆大卡车的车厢很长。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐在车厢里聊天。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车厢太热了，请打开窗户。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客们陆续走进车厢。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把大箱子搬进了车厢。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车厢的门突然关上了。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车车厢里装着很多苹果。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车厢里有人大声打电话，让我很不舒服。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "节", "label": "量词"}, {"form": "货车车厢", "label": "复合"}, {"form": "车厢里", "label": "复合"}, {"form": "車廂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "火车或卡车上供人乘坐或堆放东西的车体部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abb8f175-d215-4d05-b870-efdc6b6faf90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "车厢", "is_correct": true, "explanation": "正确。“车厢里很安静，大家都在看书”描述的是车厢内的情况，符合句意。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场通常很吵，与“很安静”矛盾。"}, {"text": "工地", "is_correct": false, "explanation": "语义：工地机器声很大，不可能“很安静”。"}, {"text": "舞厅", "is_correct": false, "explanation": "搭配：舞厅是跳舞的地方，不适合“大家都在看书”。"}], "explanations": {"车厢": "正确。“车厢里很安静，大家都在看书”描述的是车厢内的情况，符合句意。", "菜市场": "语义：菜市场通常很吵，与“很安静”矛盾。", "工地": "语义：工地机器声很大，不可能“很安静”。", "舞厅": "搭配：舞厅是跳舞的地方，不适合“大家都在看书”。"}, "sentence_index": 0, "correct_answer": "车厢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把衣服都放进了衣柜的车厢里。", "explanation": "这里应该用〈衣柜里〉。车厢是火车、汽车上坐人或放东西的部分，衣柜不是车，不能说“车厢”。"}, {"text": "他们坐在飞机的车厢里聊天。", "explanation": "这里应该用〈机舱〉。飞机上的客舱叫机舱，车厢只用于火车、汽车等。"}, {"text": "学生们在教学楼的车厢里上课。", "explanation": "这里应该用〈教室〉。车厢只指车上的部分，楼里上课的地方叫教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车厢", "is_correct": true, "explanation": "正确。“他把大箱子搬进了车厢”指把箱子搬进车里的空间，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是能装东西的空间，不能“搬进”。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“搬进”后面要接能装东西的地方，眼睛不能搭配。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听觉感受，不能被搬进任何地方。"}], "explanations": {"车厢": "正确。“他把大箱子搬进了车厢”指把箱子搬进车里的空间，符合句意。", "天空": "语义：天空不是能装东西的空间，不能“搬进”。", "眼睛": "搭配：“搬进”后面要接能装东西的地方，眼睛不能搭配。", "声音": "语义：声音是听觉感受，不能被搬进任何地方。"}, "sentence_index": 6, "correct_answer": "车厢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这艘船的车厢里住着三个人。", "explanation": "这里应该用〈船舱〉。船上的住处叫船舱，车厢只用于火车、汽车等。"}, {"text": "我把书放进了书包的车厢里。", "explanation": "这里应该用〈书包里〉。车厢只指火车、汽车上的部分，书包里面不能叫车厢。"}, {"text": "医生在医院的车厢里给病人看病。", "explanation": "这里应该用〈诊室〉。车厢只指车上的部分，医院里看病的房间叫诊室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只车厢里坐满了人。", "corrected_sentence": "这节车厢里坐满了人。", "error_description": "车厢的量词错用了“只”。车厢应该用“节”，“只”用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最后一扇车厢坏了。", "corrected_sentence": "最后一节车厢坏了。", "error_description": "车厢的量词错用了“扇”。车厢应该用“节”，“扇”用于门窗。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
