INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23330, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情正在向前发展、变化的过程。", "primary_collocate": null, "pronunciation": "jìn chéng", "ipa": "tɕin˥˩ tʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "战争拖慢了这个国家的发展进程。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改革的进程比我们想的要快。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国谈判的进程一直很顺利。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术加快了城市化进程。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨打乱了事情的进程。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议加快了改革的进程。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次见面推动了和平进程。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展的进程中，会遇到很多问题。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他详细讲了公司合作的进程。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类历史的进程不会因为一个人而停下。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "历史进程", "label": "复合"}, {"form": "城市化进程", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情向前发展、变化所经历的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48420b25-8f0d-4c8e-9a02-21c20436390e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进程", "is_correct": true, "explanation": "正确：“拖慢”可以用于事情向前发展的过程，与“发展进程”相符。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“拖慢”说的是速度或过程，不能用来说方向。"}, {"text": "成果", "is_correct": false, "explanation": "语义：“成果”是已经取得的结果，不能被“拖慢”。"}, {"text": "规则", "is_correct": false, "explanation": "语义：“规则”是制度或约定，不指发展的过程，不能被“拖慢”。"}], "explanations": {"进程": "正确：“拖慢”可以用于事情向前发展的过程，与“发展进程”相符。", "方向": "搭配：“拖慢”说的是速度或过程，不能用来说方向。", "成果": "语义：“成果”是已经取得的结果，不能被“拖慢”。", "规则": "语义：“规则”是制度或约定，不指发展的过程，不能被“拖慢”。"}, "sentence_index": 0, "correct_answer": "进程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车的进程很快。", "explanation": "这里应该用〈速度〉。进程指事情向前发展的过程，不能用来形容车辆的快慢。"}, {"text": "这次事故的进程很严重。", "explanation": "这里应该用〈程度〉。进程指事情向前发展的过程，表示事故严重的程度要用“程度”。"}, {"text": "这支队伍的进程很整齐。", "explanation": "这里应该用〈队形〉。进程指事情的发展过程，形容队伍排列整齐要用“队形”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进程", "is_correct": true, "explanation": "正确：“推动”可以用于事情向前发展的过程，“和平进程”搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能被“推动”，“和平颜色”也不成立。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指食物的滋味，不能被“推动”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”是冷热程度，“推动和平温度”不成立。"}], "explanations": {"进程": "正确：“推动”可以用于事情向前发展的过程，“和平进程”搭配自然。", "颜色": "语义：“颜色”不能被“推动”，“和平颜色”也不成立。", "味道": "语义：“味道”指食物的滋味，不能被“推动”。", "温度": "语义：“温度”是冷热程度，“推动和平温度”不成立。"}, "sentence_index": 6, "correct_answer": "进程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行是我最难忘的进程。", "explanation": "这里应该用〈经历〉。进程指事情向前发展的过程，人的亲身遭遇要用“经历”。"}, {"text": "他对朋友的进程很深。", "explanation": "这里应该用〈感情〉。进程指事情的发展过程，不能用来形容对人的情感深浅。"}, {"text": "从这里到学校的进程很远。", "explanation": "这里应该用〈路程〉。进程指事情的发展过程，不指距离的远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条进程比预期的慢得多。", "corrected_sentence": "这个进程比预期的慢得多。", "error_description": "错误：量词“条”用于细长的物体，不能用来修饰“进程”。正确：“这个进程”，“进程”是抽象的过程，应使用通用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把进程比我想象的复杂。", "corrected_sentence": "这个进程比我想象的复杂。", "error_description": "错误形式：“这把进程”。正确形式：“这个进程”。“把”是用于有柄器具的量词，进程应使用通用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23332, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "伤害", "is_correct": true, "explanation": "反义词：「保护」指使人或物免受伤害，「伤害」正是使其受到伤害，两者相反。"}, {"text": "研究", "is_correct": false, "explanation": "无关：「研究」指探究事理，与「保护」没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "无关：「参加」指加入某项活动，与「保护」没有反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "无关：「出发」指动身离开，与「保护」没有反义关系。"}], "correct_answer": "伤害", "explanations": {"伤害": "反义词：「保护」指使人或物免受伤害，「伤害」正是使其受到伤害，两者相反。", "研究": "无关：「研究」指探究事理，与「保护」没有反义关系。", "参加": "无关：「参加」指加入某项活动，与「保护」没有反义关系。", "出发": "无关：「出发」指动身离开，与「保护」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23332, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "伤害", "is_correct": true, "explanation": "反义词：「保护」指使人或物免受伤害，「伤害」正是使其受到伤害，两者相反。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：「旅行」指到外地去游览，与「保护」没有反义关系。"}, {"text": "寄", "is_correct": false, "explanation": "无关：「寄」指通过邮递送出物品，与「保护」没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "无关：「思考」指用脑子分析问题，与「保护」没有反义关系。"}], "correct_answer": "伤害", "explanations": {"伤害": "反义词：「保护」指使人或物免受伤害，「伤害」正是使其受到伤害，两者相反。", "旅行": "无关：「旅行」指到外地去游览，与「保护」没有反义关系。", "寄": "无关：「寄」指通过邮递送出物品，与「保护」没有反义关系。", "思考": "无关：「思考」指用脑子分析问题，与「保护」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23332, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "采取办法使人或事物不受伤害或损失。", "primary_collocate": null, "pronunciation": "bǎo hù", "ipa": "pau̯˨˩˦ xu˥˩", "syllable_count": 2, "sentences": [{"text": "我们要保护环境。", "target_word": "保护", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈保护着孩子，不让雨淋到他。", "target_word": "保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车时戴头盔可以保护头部。", "target_word": "保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大熊猫很少，人们都在保护它们。", "target_word": "保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前，我用防晒霜保护皮肤。", "target_word": "保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机上贴一层膜，可以保护屏幕。", "target_word": "保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察保护好小孩，把他送回了家。", "target_word": "保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些老房子很旧，政府决定保护它们。", "target_word": "保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护眼睛很重要，不要一直看手机。", "target_word": "保护", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下大雨时，他用外衣保护着怀里的书。", "target_word": "保护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保护了", "label": "体标"}, {"form": "保护着", "label": "体标"}, {"form": "保护过", "label": "体标"}, {"form": "保護", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：采取办法让人或事物不受伤害、不受损失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37088c36-b988-4c59-bd87-98a844545e6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23332, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "保护", "is_correct": true, "explanation": "正确。保护（bǎo hù）表示采取办法让人或事物不受伤害。"}, {"text": "报复", "is_correct": false, "explanation": "bàofù（报复）第一音节声调不同（bào 第四声），第二音节声母不同（f 与 h），意思是报仇。"}, {"text": "宝库", "is_correct": false, "explanation": "bǎokù（宝库）第二音节声母不同（k 与 h），声调相同（第四声），意思是储存珍宝的地方。"}, {"text": "饱和", "is_correct": false, "explanation": "bǎohé（饱和）第二音节韵母和声调不同（hé 第二声 与 hù 第四声），意思是达到最大限度。"}], "explanations": {"保护": "正确。保护（bǎo hù）表示采取办法让人或事物不受伤害。", "报复": "bàofù（报复）第一音节声调不同（bào 第四声），第二音节声母不同（f 与 h），意思是报仇。", "宝库": "bǎokù（宝库）第二音节声母不同（k 与 h），声调相同（第四声），意思是储存珍宝的地方。", "饱和": "bǎohé（饱和）第二音节韵母和声调不同（hé 第二声 与 hù 第四声），意思是达到最大限度。"}, "sentence_index": null, "correct_answer": "保护"}, "level_3": {"options": [{"text": "保护", "is_correct": true, "explanation": "正确。「保护环境」表示使环境不受损害，与句意吻合。"}, {"text": "污染", "is_correct": false, "explanation": "语义：「污染」表示使环境变脏变坏，与「我们要…环境」的意图相反。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：「破坏」表示使事物受损，与「我们要…环境」的目标相反。"}, {"text": "忘记", "is_correct": false, "explanation": "搭配：「忘记」一般接具体的人、事或信息，「忘记环境」不符合句中的要求。"}], "explanations": {"保护": "正确。「保护环境」表示使环境不受损害，与句意吻合。", "污染": "语义：「污染」表示使环境变脏变坏，与「我们要…环境」的意图相反。", "破坏": "语义：「破坏」表示使事物受损，与「我们要…环境」的目标相反。", "忘记": "搭配：「忘记」一般接具体的人、事或信息，「忘记环境」不符合句中的要求。"}, "sentence_index": 0, "correct_answer": "保护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "戴口罩可以保护感染。", "explanation": "这里应该用〈防止〉。「保护」的对象是人或物，是使它们不受伤害；要避免感染这类坏事，应说〈防止〉。"}, {"text": "人体要保护病毒。", "explanation": "这里应该用〈抵抗〉。「保护」是照顾使对象不受伤害，不能用来表示护住有害的东西；对抗病毒要用〈抵抗〉。"}, {"text": "医生保护他的病。", "explanation": "这里应该用〈治疗〉。「保护」指使人或物不受伤害，不表示治好疾病，治病要用〈治疗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护", "is_correct": true, "explanation": "正确。「保护好小孩」表示让孩子安全无恙，与「送回了家」的结果吻合。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：「抛弃」表示不再照顾，与「把他送回了家」的结果相反。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：「欺负」表示伤害、压迫别人，与「把他送回了家」的照顾行为相反。"}, {"text": "丢下", "is_correct": false, "explanation": "语义：「丢下」表示把人留在原地不管，与「把他送回了家」的结果矛盾。"}], "explanations": {"保护": "正确。「保护好小孩」表示让孩子安全无恙，与「送回了家」的结果吻合。", "抛弃": "语义：「抛弃」表示不再照顾，与「把他送回了家」的结果相反。", "欺负": "语义：「欺负」表示伤害、压迫别人，与「把他送回了家」的照顾行为相反。", "丢下": "语义：「丢下」表示把人留在原地不管，与「把他送回了家」的结果矛盾。"}, "sentence_index": 6, "correct_answer": "保护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他保护了我的邀请。", "explanation": "这里应该用〈拒绝〉。「保护」指使人或事物免受伤害，邀请不能被保护；表示不接受应说〈拒绝〉。"}, {"text": "我们在车站保护了一班车。", "explanation": "这里应该用〈等〉。「保护」指使东西不受伤害，不能用来表示在车站候车；等车要用〈等〉。"}, {"text": "大家保护新同学的到来。", "explanation": "这里应该用〈欢迎〉。「保护」指防止伤害，不能用来表达对到来者的态度，表示欢迎要用〈欢迎〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他保护的很好。", "corrected_sentence": "他保护得很好。", "error_description": "错在「得」和「的」。「保护」后面带程度补语，要用「得」，应说「他保护得很好」，不能用「的」说「他保护的很好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他保护我过一次。", "corrected_sentence": "他保护过我一次。", "error_description": "错在「过」的位置。「过」表示经历，要紧跟动词「保护」，应说「他保护过我一次」，不能放在宾语后面说「他保护我过一次」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
