INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23338, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想一个办法做出新的东西。", "primary_collocate": null, "pronunciation": "shè jì", "ipa": "ʂɤ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "他想自己设计一件新衣服。", "target_word": "设计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥是一位老工程师设计的。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我设计一张生日卡片。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在设计学校的新标志。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢设计各种好看的鞋子。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王为小孩设计了一个很安全的玩具。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机是怎么设计出来的？", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来设计，房子会是什么样？", "target_word": "设计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他花了三个月设计这辆自行车。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请他设计一个新的网站。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "设计了", "label": "体标"}, {"form": "设计过", "label": "体标"}, {"form": "设计师", "label": "复合"}, {"form": "设计图", "label": "复合"}], "register": "中性", "sense_fingerprint": "设计：动脑筋想办法，做出新的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc7d612e-20ca-4dd1-8228-5889a24a7062') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23338, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "设计", "is_correct": true, "explanation": "正确选项：设计（shè jì），指想办法做出新的东西。"}, {"text": "射击", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是用枪或弓对准目标发射。"}, {"text": "涉及", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是牵涉到某个方面。"}, {"text": "舍己", "is_correct": false, "explanation": "shě（第三声）与 shè（第四声）、jǐ（第三声）与 jì（第四声）声调不同，意思是舍弃自己的利益。"}], "explanations": {"设计": "正确选项：设计（shè jì），指想办法做出新的东西。", "射击": "jī（第一声）与 jì（第四声）声调不同，意思是用枪或弓对准目标发射。", "涉及": "jí（第二声）与 jì（第四声）声调不同，意思是牵涉到某个方面。", "舍己": "shě（第三声）与 shè（第四声）、jǐ（第三声）与 jì（第四声）声调不同，意思是舍弃自己的利益。"}, "sentence_index": null, "correct_answer": "设计"}, "level_3": {"options": [{"text": "拜访", "is_correct": false, "explanation": "搭配：“拜访”的对象应该是人，不能拜访衣服。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，后面不能直接带“一件新衣服”这样的宾语。"}, {"text": "设计", "is_correct": true, "explanation": "正确：设计指想办法做出新东西，“想自己”做的正是衣服。"}, {"text": "咨询", "is_correct": false, "explanation": "语义：“咨询”是向别人请教，与“自己”做衣服的语境不合。"}], "explanations": {"拜访": "搭配：“拜访”的对象应该是人，不能拜访衣服。", "散步": "配价：“散步”是不及物动词，后面不能直接带“一件新衣服”这样的宾语。", "设计": "正确：设计指想办法做出新东西，“想自己”做的正是衣服。", "咨询": "语义：“咨询”是向别人请教，与“自己”做衣服的语境不合。"}, "sentence_index": 0, "correct_answer": "设计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈设计了一锅粥，全家人都喝了。", "explanation": "这里应该用〈煮〉。做饭煮粥要说“煮”，“设计”指想办法做出新的样式或方案。"}, {"text": "他用抹布设计桌子，很快就干净了。", "explanation": "这里应该用〈擦〉。用抹布清洁桌子要说“擦”，“设计”不能用于清洁。"}, {"text": "他设计了一件脏衣服，晾在了阳台上。", "explanation": "这里应该用〈洗〉。把脏衣服弄干净要说“洗”，“设计”不能用来处理脏衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，手机不能被唱出来。"}, {"text": "熬", "is_correct": false, "explanation": "语义：“熬”多用于煮药、熬粥，手机不是熬出来的。"}, {"text": "设计", "is_correct": true, "explanation": "正确：设计是想办法做出新东西，“怎么……出来的”问的正是设计过程。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”是不及物动词，不能说“睡出来”一个东西，手机不是睡出来的。"}], "explanations": {"唱": "语义：“唱”的对象是歌曲，手机不能被唱出来。", "熬": "语义：“熬”多用于煮药、熬粥，手机不是熬出来的。", "设计": "正确：设计是想办法做出新东西，“怎么……出来的”问的正是设计过程。", "睡": "语义：“睡”是不及物动词，不能说“睡出来”一个东西，手机不是睡出来的。"}, "sentence_index": 6, "correct_answer": "设计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手机设计了一张照片。", "explanation": "这里应该用〈拍〉。用手机拍摄照片要说“拍”，“设计”不能用于拍照。"}, {"text": "她把课文设计完了，就去睡觉。", "explanation": "这里应该用〈背〉。把课文记在脑子里要说“背”，“设计”指想办法做出新东西。"}, {"text": "他把这篇文章设计成了英文。", "explanation": "这里应该用〈翻译〉。把文章转成另一种语言要用〈翻译〉，“设计”指想办法做出新的东西，不用于语言转换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套房子是他设计来的。", "corrected_sentence": "这套房子是他设计出来的。", "error_description": "结果补语错误：“设计”后要接“出来”，表示设计并做成，应说“设计出来”，不能只说“设计来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天我设计一张新的生日卡片。", "corrected_sentence": "昨天我设计了一张新的生日卡片。", "error_description": "“了”缺失：句中有表示过去的时间词“昨天”，表示已完成的动作时动词后要加“了”，应说“昨天我设计了一张新的生日卡片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大自然中的动物和植物数量刚刚好，不会太多也不会太少。", "primary_collocate": null, "pronunciation": "shēng tài píng héng", "ipa": "ʂɤŋ˥ tʰaɪ˥˩ pʰiŋ˧˥ xɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "草、兔子和狼的数量刚刚好，这就是生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池塘里的鱼不多不少，生态平衡很好。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昆虫太少，鸟没有吃的，生态平衡也会受影响。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，大自然需要生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们过度打猎，生态平衡就变坏了。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛上的生态平衡一直很好。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保持生态平衡，动植物就都能活下去。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原上羊太多，会影响生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要爱护动物，保护生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里放了太多鱼，生态平衡出了问题。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生態平衡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大自然中动植物数量刚刚好、不多不少的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '496a1d38-b3d1-4f3e-a711-3178efd8b036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动物园", "is_correct": false, "explanation": "语义：前句讲的是动植物数量刚刚好，“这就是动物园”与句意不符。"}, {"text": "生态平衡", "is_correct": true, "explanation": "正确：“这就是生态平衡”概括前句中草、兔、狼数量刚好的状态，合乎语境。"}, {"text": "考试成绩", "is_correct": false, "explanation": "语义：前句说的是动植物的数量关系，考试成绩与之无关。"}, {"text": "大锅饭", "is_correct": false, "explanation": "语义：“大锅饭”指平均分配、不论差别的制度，与动植物的数量关系无关，“这就是大锅饭”句意不通。"}], "explanations": {"动物园": "语义：前句讲的是动植物数量刚刚好，“这就是动物园”与句意不符。", "生态平衡": "正确：“这就是生态平衡”概括前句中草、兔、狼数量刚好的状态，合乎语境。", "考试成绩": "语义：前句说的是动植物的数量关系，考试成绩与之无关。", "大锅饭": "语义：“大锅饭”指平均分配、不论差别的制度，与动植物的数量关系无关，“这就是大锅饭”句意不通。"}, "sentence_index": 0, "correct_answer": "生态平衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "草原上的羊很多，生态平衡也很多。", "explanation": "这个词不这么用：“很多”修饰可以计数的数量，“生态平衡”是状态，不能说“多”。"}, {"text": "我在商店买了一些生态平衡。", "explanation": "这个词不这么用：“买”的对象应是商品，生态平衡是抽象状态，买不到。"}, {"text": "湖边有一只生态平衡，很美。", "explanation": "量词：〈只〉用于动物等个体，“生态平衡”是抽象名词，不能用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "搭配：“保持”多接状态、秩序，不接“作业”，“保持作业”不成立。"}, {"text": "生态平衡", "is_correct": true, "explanation": "正确：“保持生态平衡”是常用搭配，与后句“动植物就都能活下去”前后相承。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不能被保持，句子讲的是自然环境，与动植物生存相关。"}, {"text": "身高", "is_correct": false, "explanation": "语义：动植物能否活下去与身高无关，“保持身高”与句意不符。"}], "explanations": {"作业": "搭配：“保持”多接状态、秩序，不接“作业”，“保持作业”不成立。", "生态平衡": "正确：“保持生态平衡”是常用搭配，与后句“动植物就都能活下去”前后相承。", "鸡蛋": "语义：鸡蛋不能被保持，句子讲的是自然环境，与动植物生存相关。", "身高": "语义：动植物能否活下去与身高无关，“保持身高”与句意不符。"}, "sentence_index": 6, "correct_answer": "生态平衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个湖的生态平衡有三层楼高。", "explanation": "这个词不这么用：“高”用于可以测量高度的事物，生态平衡是状态，不能用“楼”来计量高度。"}, {"text": "他的生态平衡跑得很快。", "explanation": "搭配：“跑”的主语应是人或车辆，“生态平衡”是状态，不会跑。"}, {"text": "这些草的生态平衡有五十块钱。", "explanation": "这个词不这么用：“块钱”只能计量有价格的物品，生态平衡是状态，没有价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片林子的生态平衡慢慢吃了。", "corrected_sentence": "这片林子的生态平衡慢慢恢复了。", "error_description": "搭配：“吃”不能与“生态平衡”搭配，应改为“恢复”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家一起努力，保护小河边的一块生态平衡。", "corrected_sentence": "大家一起努力，保护小河边的生态平衡。", "error_description": "量词错误：“生态平衡”是抽象状态，不能用“块”计量，应直接说“保护生态平衡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23342, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂", "is_correct": true, "explanation": "反义词：「单纯」指简单、不复杂，「复杂」与之相反。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：「明亮」形容光线或颜色，与「单纯」没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：「柔软」形容质地，与「单纯」没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：「寒冷」形容温度，与「单纯」没有反义关系。"}], "correct_answer": "复杂", "explanations": {"复杂": "反义词：「单纯」指简单、不复杂，「复杂」与之相反。", "明亮": "无关：「明亮」形容光线或颜色，与「单纯」没有反义关系。", "柔软": "无关：「柔软」形容质地，与「单纯」没有反义关系。", "寒冷": "无关：「寒冷」形容温度，与「单纯」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23342, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂", "is_correct": true, "explanation": "反义词：「单纯」指简单、不复杂，「复杂」与之相反。"}, {"text": "沉重", "is_correct": false, "explanation": "无关：「沉重」形容重量或心情的压抑，与「单纯」没有反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "无关：「干燥」形容缺少水分，与「单纯」没有反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "无关：「辽阔」形容范围大，与「单纯」没有反义关系。"}], "correct_answer": "复杂", "explanations": {"复杂": "反义词：「单纯」指简单、不复杂，「复杂」与之相反。", "沉重": "无关：「沉重」形容重量或心情的压抑，与「单纯」没有反义关系。", "干燥": "无关：「干燥」形容缺少水分，与「单纯」没有反义关系。", "辽阔": "无关：「辽阔」形容范围大，与「单纯」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23342, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "只有一种东西，不复杂。", "primary_collocate": null, "pronunciation": "dān chún", "ipa": "tan˥ tʂʰuən˧˥", "syllable_count": 2, "sentences": [{"text": "孩子的想法很单纯。", "target_word": "单纯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事很单纯，只要把钱还上就行。", "target_word": "单纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们只是同学，关系很单纯。", "target_word": "单纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的生活很单纯，每天只是工作和回家。", "target_word": "单纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候的快乐很单纯，一块糖就够了。", "target_word": "单纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事很单纯，没有什么复杂的情节。", "target_word": "单纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的设计很单纯，没有多余的装饰。", "target_word": "单纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店的做法很单纯，就是现做现卖。", "target_word": "单纯", "complexity_tier": "T3", "furigana": "zhè jiā xiǎo diàn de zuò fǎ hěn dān chún, jiù shì xiàn zuò xiàn mài。", "sentence_source": "generated"}, {"text": "刚开始的时候，这个游戏的规则比较单纯，容易上手。", "target_word": "单纯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的愿望很单纯，只想家人都健康。", "target_word": "单纯", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "單純", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容词：事物、想法或关系简单，没有别的复杂成分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37088c36-b988-4c59-bd87-98a844545e6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单纯", "is_correct": true, "explanation": "正确。「孩子的想法很单纯」表示想法简单，没有复杂的成分。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：「冷漠」指对人或事不热情，与句中描写的单纯想法不符。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：「高兴」描写人的心情，不能用来修饰「想法」。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：「响亮」描写声音，不能用来形容「想法」。"}], "explanations": {"单纯": "正确。「孩子的想法很单纯」表示想法简单，没有复杂的成分。", "冷漠": "语义：「冷漠」指对人或事不热情，与句中描写的单纯想法不符。", "高兴": "搭配：「高兴」描写人的心情，不能用来修饰「想法」。", "响亮": "搭配：「响亮」描写声音，不能用来形容「想法」。"}, "sentence_index": 0, "correct_answer": "单纯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的价格很单纯。", "explanation": "这里应该用〈便宜〉。「单纯」指不复杂，不能用来形容价格高低；价格低要用〈便宜〉。"}, {"text": "这次考试的分数很单纯。", "explanation": "这里应该用〈高〉。「单纯」指不复杂，不能用来形容分数高低；分数高要用〈高〉。"}, {"text": "他的身体很单纯。", "explanation": "这里应该用〈单薄〉。「单纯」形容性格或关系，不能形容身体；身体瘦弱要用〈单薄〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单纯", "is_correct": true, "explanation": "正确。「他的设计很单纯，没有多余的装饰」指设计简洁，没有复杂的成分。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：「凶狠」形容人的态度狠毒，不能用来形容设计。"}, {"text": "暴躁", "is_correct": false, "explanation": "语义：「暴躁」形容人的脾气急，不能用来形容设计。"}, {"text": "健壮", "is_correct": false, "explanation": "搭配：「健壮」形容人的体格，不能用来形容设计。"}], "explanations": {"单纯": "正确。「他的设计很单纯，没有多余的装饰」指设计简洁，没有复杂的成分。", "凶狠": "语义：「凶狠」形容人的态度狠毒，不能用来形容设计。", "暴躁": "语义：「暴躁」形容人的脾气急，不能用来形容设计。", "健壮": "搭配：「健壮」形容人的体格，不能用来形容设计。"}, "sentence_index": 6, "correct_answer": "单纯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房间里很单纯。", "explanation": "这里应该用〈干净〉。「单纯」不用来形容房间，形容环境整洁要用〈干净〉。"}, {"text": "这个城市对我很单纯。", "explanation": "这里应该用〈陌生〉。「单纯」不用来描述人对地方的感受，地方不熟悉要用〈陌生〉。"}, {"text": "那个地方的温度很单纯。", "explanation": "这里应该用〈暖和〉。「单纯」指不复杂，不能用来形容温度；温度适宜、让人感觉温暖要用〈暖和〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他单纯的相信别人。", "corrected_sentence": "他单纯地相信别人。", "error_description": "错在「的」。「单纯」在动词前作状语，要用「地」，应说「他单纯地相信别人」，不能用「的」说「他单纯的相信别人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一个很单纯人。", "corrected_sentence": "她是一个很单纯的人。", "error_description": "错在少了「的」。「很单纯」修饰名词「人」时，中间要加「的」，应说「很单纯的人」，不能说「很单纯人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
