INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指距离很长，从前面到后面很深。", "primary_collocate": null, "pronunciation": "zòng shēn", "ipa": "tsʊŋ˥˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "这个院子纵深很长，有三个门。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的纵深很大，里面像个仓库。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞的纵深有一百多米。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条胡同很窄，纵深却有几百米。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台纵深太短，演员不能跑。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子宽度小，但是纵深很长。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走进森林的纵深，天都黑了。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室的纵深不够，后面的同学看不清。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座庙的纵深很大，一进一进的。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子纵深很长，光线进不来。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纵深处", "label": "复合"}, {"form": "縱深", "label": "繁体"}], "register": "书面", "sense_fingerprint": "空间从前到后的长度很深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52a47307-49a6-4e93-9fed-15de8bc7b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纵深", "is_correct": true, "explanation": "正确：「纵深」zòng shēn，指距离很长，从前面到后面很深。"}, {"text": "终身", "is_correct": false, "explanation": "zhōng（第一声）与 zòng（第四声）声母与声调都不同，「终身」意思是一辈子，与「纵深」不同。"}, {"text": "重申", "is_correct": false, "explanation": "chóng（第二声）与 zòng（第四声）声母 ch 与 z 不同、声调也不同，「重申」意思是再次声明，与「纵深」不同。"}, {"text": "纵声", "is_correct": false, "explanation": "shēng 与 shēn 的韵母 eng 与 en 不同，「纵声」意思是放开嗓门，与「纵深」不同。"}], "explanations": {"纵深": "正确：「纵深」zòng shēn，指距离很长，从前面到后面很深。", "终身": "zhōng（第一声）与 zòng（第四声）声母与声调都不同，「终身」意思是一辈子，与「纵深」不同。", "重申": "chóng（第二声）与 zòng（第四声）声母 ch 与 z 不同、声调也不同，「重申」意思是再次声明，与「纵深」不同。", "纵声": "shēng 与 shēn 的韵母 eng 与 en 不同，「纵声」意思是放开嗓门，与「纵深」不同。"}, "sentence_index": null, "correct_answer": "纵深"}, "level_3": {"options": [{"text": "纵深", "is_correct": true, "explanation": "正确：「这个院子纵深很长」指院子从前到后很长，有三个门，与句义相合。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「年龄」不能说「很长」，院子的年龄也与「有三个门」无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「颜色」不能说「很长」，与「很长」搭配不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「脾气」是人的性格，不能用「很长」修饰院子。"}], "explanations": {"纵深": "正确：「这个院子纵深很长」指院子从前到后很长，有三个门，与句义相合。", "年龄": "搭配：「年龄」不能说「很长」，院子的年龄也与「有三个门」无关。", "颜色": "搭配：「颜色」不能说「很长」，与「很长」搭配不通。", "脾气": "搭配：「脾气」是人的性格，不能用「很长」修饰院子。"}, "sentence_index": 0, "correct_answer": "纵深"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座庙的纵深很高，一层一层的。", "explanation": "这里应该用〈高度〉。纵深指前后的深度，不指竖直方向的高矮。"}, {"text": "这条路的纵深很宽，两边都是树。", "explanation": "这里应该用〈宽度〉。宽度指左右之间的距离；纵深指从前到后的距离，不说路的纵深很宽。"}, {"text": "这块石头的纵深很贵，我买不起。", "explanation": "这里应该用〈价格〉。价格指买卖的钱数；纵深指距离，不能说「很贵」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纵深", "is_correct": true, "explanation": "正确：「走进森林的纵深」指走进森林深处，与「天都黑了」的语境相合。"}, {"text": "名字", "is_correct": false, "explanation": "语义：「名字」是称呼，不能指走进的地方，与句义不合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」与走进森林的空间位置无关，不能用于此处。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：「走进」后接「声音」不通，不说「走进森林的声音」指空间位置。"}], "explanations": {"纵深": "正确：「走进森林的纵深」指走进森林深处，与「天都黑了」的语境相合。", "名字": "语义：「名字」是称呼，不能指走进的地方，与句义不合。", "价格": "语义：「价格」与走进森林的空间位置无关，不能用于此处。", "声音": "搭配：「走进」后接「声音」不通，不说「走进森林的声音」指空间位置。"}, "sentence_index": 6, "correct_answer": "纵深"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布的纵深很大，能盖住床。", "explanation": "这里应该用〈面积〉。面积指平面的大小，纵深指空间从前到后的距离。"}, {"text": "这个箱子的纵深很重，要两个人抬。", "explanation": "这里应该用〈重量〉。重量指轻重，纵深指距离，不能说「很重」。"}, {"text": "这根绳子的纵深很长，能绕一圈。", "explanation": "这里应该用〈长度〉。长度指线状物的长短；纵深指空间中从前到后的深处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老宅的纵深长很，穿过院子才能到后门。", "corrected_sentence": "这座老宅的纵深很长，穿过院子才能到后门。", "error_description": "语序错误：程度副词「很」应放在形容词「长」之前，「长很」不合语法。正确形式为「纵深很长」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子的一个纵深不够，放不下一张大床。", "corrected_sentence": "这间屋子的纵深不够，放不下一张大床。", "error_description": "错误形式用「一个」修饰「纵深」。「纵深」指空间从前到后的深度，表示范围而非可以逐个计数的事物，不能用「一个」修饰。正确形式为「这间屋子的纵深不够」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d6948-7184-40c2-8d04-dba1fc89ab25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
