INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "住在某个地方的人。", "primary_collocate": null, "pronunciation": "jū mín", "ipa": "tɕy˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "这个小区的居民都很友好。", "target_word": "居民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "居民们在楼下一起锻炼身体。", "target_word": "居民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的居民大多是老人。", "target_word": "居民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给居民发了新的通知。", "target_word": "居民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "附近的居民常常来这家超市买菜。", "target_word": "居民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为连续大雨，一些居民暂时到学校里避雨了。", "target_word": "居民", "complexity_tier": "T3", "furigana": "yīn wèi lián xù dà yǔ, yì xiē jū mín zàn shí dào xué xiào lǐ bì yǔ le.", "sentence_source": "generated"}, {"text": "我们小区有三千多位居民。", "target_word": "居民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街的居民晚上都在公园散步。", "target_word": "居民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请各位居民把垃圾放进垃圾桶。", "target_word": "居民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的居民需要先去办公室登记。", "target_word": "居民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "居民区", "label": "复合"}, {"form": "居民楼", "label": "复合"}], "register": "中性", "sense_fingerprint": "长期住在某个地方的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37088c36-b988-4c59-bd87-98a844545e6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "居民", "is_correct": true, "explanation": "“居民”指长期住在这个小区的人，与“都很友好”的描述相符。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不是人，不能“友好”，也不住在小区里。"}, {"text": "货物", "is_correct": false, "explanation": "语义：货物是商品，不是人，不能「友好」，也不住在小区里。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器不是人，不能「友好」，也不是小区里住的人。"}], "explanations": {"居民": "“居民”指长期住在这个小区的人，与“都很友好”的描述相符。", "工厂": "语义：工厂不是人，不能“友好”，也不住在小区里。", "货物": "语义：货物是商品，不是人，不能「友好」，也不住在小区里。", "机器": "语义：机器不是人，不能「友好」，也不是小区里住的人。"}, "sentence_index": 0, "correct_answer": "居民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家图书馆的居民很多。", "explanation": "这里应该用〈读者〉。居民指长期住在某地的人，来图书馆的是读者，不是居民。"}, {"text": "病房里的居民很耐心。", "explanation": "这里应该用〈护士〉。居民指住在某地的人，病房里照顾病人的是护士，不是居民。"}, {"text": "这次会议的居民很多。", "explanation": "这里应该用〈与会者〉。居民指长期住在某地的人，参加会议的人不一定住在那里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "居民", "is_correct": true, "explanation": "“居民”指住在小区里的人，“我们小区有三千多位居民”语义通顺。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员是从事表演的人，不是住在小区里的居民，“三千多位演员”的说法与语境不合。"}, {"text": "旅客", "is_correct": false, "explanation": "语义：旅客是出行途中的人，与长期住在小区里的人不合。"}, {"text": "乘务员", "is_correct": false, "explanation": "语义：乘务员是在交通工具上服务的人，不住在小区里，句子无法成立。"}], "explanations": {"居民": "“居民”指住在小区里的人，“我们小区有三千多位居民”语义通顺。", "演员": "语义：演员是从事表演的人，不是住在小区里的居民，“三千多位演员”的说法与语境不合。", "旅客": "语义：旅客是出行途中的人，与长期住在小区里的人不合。", "乘务员": "语义：乘务员是在交通工具上服务的人，不住在小区里，句子无法成立。"}, "sentence_index": 6, "correct_answer": "居民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "剧场里的居民很安静。", "explanation": "这里应该用〈观众〉。居民指住在某地的人，剧场里看演出的是观众，不是居民。"}, {"text": "这家公司的居民都很努力。", "explanation": "这里应该用〈员工〉。在公司工作的人是员工，公司里没有居民。"}, {"text": "公交车上的居民很多，大家都很挤。", "explanation": "这里应该用〈乘客〉。居民指住在某地的人，坐在车上的人是乘客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋楼里住着三位居民们。", "corrected_sentence": "这栋楼里住着三位居民。", "error_description": "错误：“三位居民们”。正确：“三位居民”。“们”表示复数，不能与具体的数量词同时使用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区有两百栋居民。", "corrected_sentence": "这个小区有两百名居民。", "error_description": "错误：“两百栋居民”。正确：“两百名居民”。居民是人，计量人的量词应用“名”或“位”，“栋”只用于房屋，不能用来计量居民。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23348, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23348, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23348, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "支点是支撑东西的点，比如跷跷板中间那个让两边动起来的地方。", "primary_collocate": null, "pronunciation": "zhī diǎn", "ipa": "ʈʂʅ˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "跷跷板的支点在中间。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头放在木板下面，当作支点。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "支点不在中间，跷跷板就会歪。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在跷跷板两边玩，支点在中间。", "target_word": "支点", "complexity_tier": "T3", "furigana": "hái zi men zài qiāoqiāobǎn liǎng biān wán, zhīdiǎn zài zhōngjiān。", "sentence_source": "generated"}, {"text": "这根杠杆的支点离重物很近。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剪刀的支点就是中间的螺丝。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了杠杆的支点。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把石头往左移，支点也跟着变了。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开瓶器用瓶口当支点，把瓶盖撬开。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有支点，再长的木棍也撬不动石头。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "杠杆、跷跷板上支撑并让两边转动的固定点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80f0202-2691-4b52-babe-45032a6cb8ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23348, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指点", "is_correct": false, "explanation": "指点（zhǐ 第三声）与支点（zhī 第一声）声调不同，意思是指教、点拨。"}, {"text": "支点", "is_correct": true, "explanation": "支点：杠杆、跷跷板上支撑并让两边转动的固定点。"}, {"text": "吃点", "is_correct": false, "explanation": "吃点（chī）与支点（zhī）声母不同（ch 与 zh），意思是吃一些东西。"}, {"text": "质点", "is_correct": false, "explanation": "质点（zhì 第四声）与支点（zhī 第一声）声调不同，是物理学中忽略大小的理想化物体。"}], "explanations": {"指点": "指点（zhǐ 第三声）与支点（zhī 第一声）声调不同，意思是指教、点拨。", "支点": "支点：杠杆、跷跷板上支撑并让两边转动的固定点。", "吃点": "吃点（chī）与支点（zhī）声母不同（ch 与 zh），意思是吃一些东西。", "质点": "质点（zhì 第四声）与支点（zhī 第一声）声调不同，是物理学中忽略大小的理想化物体。"}, "sentence_index": null, "correct_answer": "支点"}, "level_3": {"options": [{"text": "轮子", "is_correct": false, "explanation": "语义：跷跷板没有轮子，不能说“轮子在中间”。"}, {"text": "支点", "is_correct": true, "explanation": "支点：跷跷板中间让两边转动的固定点，符合句意。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：跷跷板的座位设在两端，“座位在中间”与跷跷板的结构不符。"}, {"text": "尾巴", "is_correct": false, "explanation": "语义：跷跷板没有尾巴，“尾巴在中间”不成立。"}], "explanations": {"轮子": "语义：跷跷板没有轮子，不能说“轮子在中间”。", "支点": "支点：跷跷板中间让两边转动的固定点，符合句意。", "座位": "搭配：跷跷板的座位设在两端，“座位在中间”与跷跷板的结构不符。", "尾巴": "语义：跷跷板没有尾巴，“尾巴在中间”不成立。"}, "sentence_index": 0, "correct_answer": "支点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条曲线的支点在第三个坐标处。", "explanation": "这里应该用〈拐点〉。支点指杠杆的固定支撑点；曲线方向发生转折的位置应说拐点。"}, {"text": "孩子们在跷跷板两边玩，用手推的地方叫支点。", "explanation": "这里应该用〈施力点〉。支点是支撑不动的固定点；用力推的地方应说施力点。"}, {"text": "两条直线的支点恰好在这里。", "explanation": "这里应该用〈交点〉。支点指杠杆上的固定点；两条线相交的位置应说交点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23348, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "试点", "is_correct": false, "explanation": "试点（shì 第四声）与支点（zhī）声母不同（sh 与 zh），声调也不同，意思是先行试验的地方。"}, {"text": "支点", "is_correct": true, "explanation": "支点：跷跷板、杠杆上支撑并让两边转动的固定点。"}, {"text": "终点", "is_correct": false, "explanation": "终点（zhōng）与支点（zhī）韵母不同（ōng 与 ī），声调相同，意思是路程的末端。"}, {"text": "这点", "is_correct": false, "explanation": "这点（zhè 第四声）与支点（zhī）韵母不同（è 与 ī），声调也不同，意思是这么一点。"}], "explanations": {"试点": "试点（shì 第四声）与支点（zhī）声母不同（sh 与 zh），声调也不同，意思是先行试验的地方。", "支点": "支点：跷跷板、杠杆上支撑并让两边转动的固定点。", "终点": "终点（zhōng）与支点（zhī）韵母不同（ōng 与 ī），声调相同，意思是路程的末端。", "这点": "这点（zhè 第四声）与支点（zhī）韵母不同（è 与 ī），声调也不同，意思是这么一点。"}, "sentence_index": null, "correct_answer": "支点"}, "level_3": {"options": [{"text": "夜晚", "is_correct": false, "explanation": "语义：“画”的对象应是图形或事物，“夜晚”是时间，不能画在杠杆上。"}, {"text": "支点", "is_correct": true, "explanation": "支点：杠杆上的固定点，与“画了杠杆的”搭配，符合句意。"}, {"text": "大衣", "is_correct": false, "explanation": "语义：“杠杆的大衣”不成立，杠杆不穿衣服，句意不通。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "搭配：“杠杆的”后接的应是部件或特征词，“鸡蛋”与杠杆不搭配。"}], "explanations": {"夜晚": "语义：“画”的对象应是图形或事物，“夜晚”是时间，不能画在杠杆上。", "支点": "支点：杠杆上的固定点，与“画了杠杆的”搭配，符合句意。", "大衣": "语义：“杠杆的大衣”不成立，杠杆不穿衣服，句意不通。", "鸡蛋": "搭配：“杠杆的”后接的应是部件或特征词，“鸡蛋”与杠杆不搭配。"}, "sentence_index": 6, "correct_answer": "支点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "把相机放在三脚支点上。", "explanation": "这里应该用〈支架〉。支点指杠杆的固定支撑点；固定相机的架子应说支架。"}, {"text": "这条路的支点设在山脚下。", "explanation": "这里应该用〈起点〉。支点指杠杆的固定支撑点；道路开始的地方应说起点。"}, {"text": "这把锤子的支点就是握着的地方。", "explanation": "这里应该用〈把手〉。支点是支撑物体、让它转动的固定点；握着的部分应说把手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把支点要放在中间才能让跷跷板平衡。", "corrected_sentence": "这个支点要放在中间才能让跷跷板平衡。", "error_description": "量词错误：“支点”应搭配“个”，说“这个支点”；“把”用于有柄的器具，不能修饰“支点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找到一只合适的支点。", "corrected_sentence": "他找到一个合适的支点。", "error_description": "量词错误：“支点”应搭配“个”，说“一个合适的支点”；“只”多用于动物，不能修饰“支点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
