INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动脉是身体里把血液从心脏送到全身的管子。", "primary_collocate": null, "pronunciation": "dòng mài", "ipa": "tʊŋ˥˩ maɪ˥˩", "syllable_count": 2, "sentences": [{"text": "动脉是把血液送到全身的管子。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心脏里的血先流进动脉，再到手和脚。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士在他的手腕上找到了动脉。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动脉的血从心脏出发，静脉的血回到心脏。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用手指按着他的动脉，数了数心跳。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步以后，我能摸到手腕动脉在跳。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动脉里的血流得很快，受伤了很危险。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说爷爷的动脉变硬了，要少吃肉。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动脉和静脉都是血管，但是血流的方向不同。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心割到了动脉，马上去了医院。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "主动脉", "label": "复合"}, {"form": "動脈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体里把血液从心脏送到全身的管子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '496a1d38-b3d1-4f3e-a711-3178efd8b036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "静脉", "is_correct": false, "explanation": "语义：静脉把血液从身体各处送回心脏，与“送到全身”的方向相反。"}, {"text": "动脉", "is_correct": true, "explanation": "正确：动脉是把血液从心脏送往全身的血管，与定义相符。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏是器官，不是把血液送到全身的管子。"}, {"text": "食管", "is_correct": false, "explanation": "搭配：食管输送的是食物，不能说它把血液送到全身。"}], "explanations": {"静脉": "语义：静脉把血液从身体各处送回心脏，与“送到全身”的方向相反。", "动脉": "正确：动脉是把血液从心脏送往全身的血管，与定义相符。", "心脏": "语义：心脏是器官，不是把血液送到全身的管子。", "食管": "搭配：食管输送的是食物，不能说它把血液送到全身。"}, "sentence_index": 0, "correct_answer": "动脉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "动脉的血从身体各处回到心脏。", "explanation": "这里应该用〈静脉〉。静脉把血从身体各处送回心脏，动脉则把血从心脏送出去，方向不同。"}, {"text": "我在手腕上摸到了一只动脉。", "explanation": "这里应该用〈条〉。动脉是血管，量词用“条”，“只”多用于动物。"}, {"text": "血液在动脉里交换氧气和二氧化碳。", "explanation": "这里应该用〈毛细血管〉。氧气和二氧化碳的交换发生在毛细血管里，动脉主要负责输送血液。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经", "is_correct": false, "explanation": "语义：神经里不装血液，“神经里的血流得很快”说不通。"}, {"text": "动脉", "is_correct": true, "explanation": "正确：动脉是输送血液的血管，血流快、受伤危险都与之相符。"}, {"text": "食管", "is_correct": false, "explanation": "搭配：食管是输送食物的管道，不能说它里面的血流得很快。"}, {"text": "脉搏", "is_correct": false, "explanation": "语义：脉搏指跳动的感觉，不是装血的管道，不能说“脉搏里的血”。"}], "explanations": {"神经": "语义：神经里不装血液，“神经里的血流得很快”说不通。", "动脉": "正确：动脉是输送血液的血管，血流快、受伤危险都与之相符。", "食管": "搭配：食管是输送食物的管道，不能说它里面的血流得很快。", "脉搏": "语义：脉搏指跳动的感觉，不是装血的管道，不能说“脉搏里的血”。"}, "sentence_index": 6, "correct_answer": "动脉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "动脉负责把疼痛的信号传给大脑。", "explanation": "这里应该用〈神经〉。传递信号的是神经，动脉的作用是输送血液。"}, {"text": "动脉负责过滤身体里的废物。", "explanation": "这里应该用〈肾脏〉。过滤和排出废物是肾脏的作用，动脉不承担这项功能。"}, {"text": "动脉负责消化身体里的食物。", "explanation": "这里应该用〈胃〉。消化食物是胃的作用，动脉不负责消化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的脖子上有一个很粗的动脉。", "corrected_sentence": "他的脖子上有一条很粗的动脉。", "error_description": "量词错误：动脉是血管，应用量词“条”，不能用“个”。正确的说法是“一条很粗的动脉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的动脉比毛细血管很粗。", "corrected_sentence": "他的动脉比毛细血管粗。", "error_description": "比较错误：“比”字句的谓语前不能再加“很”，应说“比毛细血管粗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
