INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指一个人自己的，不是公家的。", "primary_collocate": null, "pronunciation": "sī rén", "ipa": "sɨ˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这是我的私人电话，请不要乱打。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在家里有一间私人书房。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是私人的事，你别问了。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开着一辆私人汽车来上班。", "target_word": "私人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家私人医院的环境很好。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要看别人的私人信件。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园是大家的，不是私人的地方。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有一个私人司机，每天送他上班。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条海边的路是私人的，外人不能进。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板用公司的钱买私人用品，这样不对。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "私人的", "label": "的字结构"}, {"form": "私人医院", "label": "复合"}, {"form": "私人电话", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词，属于个人的、非公家或集体的，多修饰名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d9ab088-f832-4c2b-8bdc-c6dfd9f23bbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寂静", "is_correct": false, "explanation": "语义：「寂静」形容环境安静，不能修饰电话，与「我的」所有关系也不符。"}, {"text": "私人", "is_correct": true, "explanation": "私人：属于个人的，不是公家或集体的。这里指说话人自己的电话，正确。"}, {"text": "公用", "is_correct": false, "explanation": "语义：公用电话属于公共，与“我的”所表示的个人所有相矛盾。"}, {"text": "陌生", "is_correct": false, "explanation": "搭配：「陌生」多指来历不明的来电，不能与表示所属的「我的」搭配。"}], "explanations": {"寂静": "语义：「寂静」形容环境安静，不能修饰电话，与「我的」所有关系也不符。", "私人": "私人：属于个人的，不是公家或集体的。这里指说话人自己的电话，正确。", "公用": "语义：公用电话属于公共，与“我的”所表示的个人所有相矛盾。", "陌生": "搭配：「陌生」多指来历不明的来电，不能与表示所属的「我的」搭配。"}, "sentence_index": 0, "correct_answer": "私人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所私人的小学是政府办的，孩子们上学不要钱。", "explanation": "这里应该用〈公立〉。「私人」指不是公家的，政府办的学校属于公立，二者矛盾。"}, {"text": "这条私人的马路是市政府修建的，所有车辆都可以通行。", "explanation": "这里应该用〈公共〉。「私人」指不是公家的，市政府修建、所有人都能通行的马路属于公共，二者矛盾。"}, {"text": "这所私人的医院是省里办的，所有人都能免费看病。", "explanation": "这里应该用〈公办〉。「私人」指不是公家的，“省里办的”属于公办，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小气", "is_correct": false, "explanation": "搭配：「小气」形容人的性格，不能用来修饰「地方」。"}, {"text": "私人", "is_correct": true, "explanation": "私人：属于个人的、不是公家的。这里说公园不是个人的地方，正确。"}, {"text": "高傲", "is_correct": false, "explanation": "搭配：「高傲」形容人的态度，不能修饰「地方」。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：「狡猾」指人的心机，与公园的性质不符。"}], "explanations": {"小气": "搭配：「小气」形容人的性格，不能用来修饰「地方」。", "私人": "私人：属于个人的、不是公家的。这里说公园不是个人的地方，正确。", "高傲": "搭配：「高傲」形容人的态度，不能修饰「地方」。", "狡猾": "语义：「狡猾」指人的心机，与公园的性质不符。"}, "sentence_index": 6, "correct_answer": "私人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家私人的银行由国家设立，负责管理全国的货币。", "explanation": "这里应该用〈国有〉。「私人」指不是公家的，由国家设立、管理货币的银行属于国有，二者矛盾。"}, {"text": "我们要尊重每个人的私人。", "explanation": "这里应该用〈隐私〉。「私人」是形容词，不能单独作名词指个人的秘密。"}, {"text": "我们反对私人主义。", "explanation": "这里应该用〈个人〉。「个人主义」是固定说法，不能说“私人主义”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老板有一个私人汽车。", "corrected_sentence": "这位老板有一辆私人汽车。", "error_description": "量词错误：「汽车」应搭配量词「辆」，不能用「个」，应说“一辆私人汽车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他请了一位私人地司机。", "corrected_sentence": "他请了一位私人司机。", "error_description": "结构助词错误：「私人」是形容词，直接修饰名词时中间不加“地”，“地”只用于修饰动词、形容词等状语。应为“他请了一位私人司机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
