INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23356, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "做事有步骤、有条理的性质。", "primary_collocate": null, "pronunciation": "xì tǒng xìng", "ipa": "ɕi˥˩ tʰʊŋ˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他学汉语很有系统性。", "target_word": "系统性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲得很有系统性。", "target_word": "系统性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的复习计划很有系统性。", "target_word": "系统性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要系统性地学习语法。", "target_word": "系统性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课缺少系统性，学生听不懂。", "target_word": "系统性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事没有系统性，总是想到哪做到哪。", "target_word": "系统性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告的系统性很强。", "target_word": "系统性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲课有系统性，我们学得很快。", "target_word": "系统性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的知识很多，可是没有系统性。", "target_word": "系统性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做研究要有系统性，不能乱来。", "target_word": "系统性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "系统性地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "系统性：学习或做事有步骤、有条理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "系统性", "is_correct": true, "explanation": "系统性：做事有步骤、有条理，符合「学汉语很有……」的句意。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的温度，不能说学汉语很有体温。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：人数是数量，不能与「很有」搭配来形容学习。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是生存时间，不能用来形容学汉语的方式。"}], "explanations": {"系统性": "系统性：做事有步骤、有条理，符合「学汉语很有……」的句意。", "体温": "语义：体温是身体的温度，不能说学汉语很有体温。", "人数": "搭配：人数是数量，不能与「很有」搭配来形容学习。", "年龄": "语义：年龄是生存时间，不能用来形容学汉语的方式。"}, "sentence_index": 0, "correct_answer": "系统性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很系统性地生气。", "explanation": "这里不能用〈系统性〉。系统性形容做事一步一步、有条有理，是做事的方式，不能用来修饰生气这种情绪。"}, {"text": "今天的天气很有系统性。", "explanation": "这里应该用〈晴朗〉之类形容天气的词。系统性形容做事有步骤、有条理，不能用来形容天气。"}, {"text": "这只小猫很有系统性。", "explanation": "这里应该用〈可爱〉之类形容小猫的词。系统性形容做事的条理，不能用来描述动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "系统性", "is_correct": true, "explanation": "系统性：报告的组织有条理，符合「这份报告的……很强」的句意。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度描述冷热，不能说报告的温度很强。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：体积通常说大或小，不能与「强」搭配。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人或物的高度，报告没有身高，不能说很强。"}], "explanations": {"系统性": "系统性：报告的组织有条理，符合「这份报告的……很强」的句意。", "温度": "语义：温度描述冷热，不能说报告的温度很强。", "体积": "搭配：体积通常说大或小，不能与「强」搭配。", "身高": "语义：身高是人或物的高度，报告没有身高，不能说很强。"}, "sentence_index": 6, "correct_answer": "系统性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个公园很有系统性。", "explanation": "这里应该用〈整洁〉之类形容公园的词。系统性形容做事有步骤、有条理，不能用来描述公园这样的场所。"}, {"text": "她的笑容很有系统性。", "explanation": "这里应该用〈甜美〉之类形容笑容的词。系统性形容做事的条理，不能用来形容笑容。"}, {"text": "这碗汤很有系统性。", "explanation": "这里应该用〈鲜美〉之类形容汤的词。系统性形容做事的条理，不能用来形容食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做事很系统性。", "corrected_sentence": "他做事很有系统性。", "error_description": "「很系统性」少了「有」。「系统性」是名词，要说「很有系统性」，不能直接用「很」修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份计划不有系统性。", "corrected_sentence": "这份计划没有系统性。", "error_description": "否定词用错。「有」的否定要用「没有」，不能用「不」，应说「没有系统性」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
