INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23358, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23358, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情发生得很早，或者很久以前就做了。", "primary_collocate": null, "pronunciation": "zǎo yǐ", "ipa": "tsɑʊ²¹⁴ i²¹⁴", "syllable_count": 2, "sentences": [{"text": "我到的时候，他早已走了。", "target_word": "早已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事大家早已知道了。", "target_word": "早已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她早已习惯了一个人生活。", "target_word": "早已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车早已开走，我们只好等下一班。", "target_word": "早已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等我们赶到，比赛早已结束。", "target_word": "早已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早已不住在这里了。", "target_word": "早已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈早已把饭做好了。", "target_word": "早已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小店早已关门，现在是一家银行。", "target_word": "早已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友的名字，我早已忘记。", "target_word": "早已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天早已黑了，孩子们还在外面玩。", "target_word": "早已", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示动作或状态很早以前就已发生或完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '449b634c-ae74-4ccb-8934-b82cc0828b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早已", "is_correct": true, "explanation": "「早已」表示很早以前就已发生，与“我到的时候”的先后关系一致。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：「正在」表示动作正在进行，与“走了”所表示的已完成状态冲突。"}, {"text": "将要", "is_correct": false, "explanation": "语义：「将要」指尚未发生的事，与“我到的时候”已成过去的时刻相矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "语义：「总是」表示经常性的情况，不能用于“我到的时候”这一次性的时刻。"}], "explanations": {"早已": "「早已」表示很早以前就已发生，与“我到的时候”的先后关系一致。", "正在": "体貌：「正在」表示动作正在进行，与“走了”所表示的已完成状态冲突。", "将要": "语义：「将要」指尚未发生的事，与“我到的时候”已成过去的时刻相矛盾。", "总是": "语义：「总是」表示经常性的情况，不能用于“我到的时候”这一次性的时刻。"}, "sentence_index": 0, "correct_answer": "早已"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天我们早已出发。", "explanation": "这里应该用〈早点〉。早已表示动作已经完成，不能用于明天这样的将来时间，表示将来的早些时候要用〈早点〉。"}, {"text": "他一看到我，早已跑过来了。", "explanation": "这里应该用〈立刻〉。早已强调动作在之前就已完成，与“一看到”所表示的紧接关系不符，应说〈立刻〉。"}, {"text": "我每天早已六点起床。", "explanation": "这里应该用〈就〉。早已表示事情在说话之前已经完成，不能用于每天重复的动作；说每天六点就起床，表示时间早，要用〈就〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早已", "is_correct": true, "explanation": "「早已」表示事情在之前已经完成，与“把饭做好了”的完成结果一致。"}, {"text": "一直", "is_correct": false, "explanation": "语义：「一直」表示持续不断，与“把饭做好了”这一完成结果不合。"}, {"text": "正要", "is_correct": false, "explanation": "语义：「正要」表示即将开始，与“做好了”的完成结果相矛盾。"}, {"text": "将", "is_correct": false, "explanation": "体貌：「将」表示将来，与句中的“了”所表示的完成态冲突。"}], "explanations": {"早已": "「早已」表示事情在之前已经完成，与“把饭做好了”的完成结果一致。", "一直": "语义：「一直」表示持续不断，与“把饭做好了”这一完成结果不合。", "正要": "语义：「正要」表示即将开始，与“做好了”的完成结果相矛盾。", "将": "体貌：「将」表示将来，与句中的“了”所表示的完成态冲突。"}, "sentence_index": 6, "correct_answer": "早已"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚出生，早已会走路。", "explanation": "这里应该用〈还不〉。早已表示事情在之前就已经发生，与“刚出生”的时间不符；说刚出生还不会走路，要用〈还不〉。"}, {"text": "他正在吃饭，早已吃完了。", "explanation": "这里应该改用〈还没〉，并去掉“了”：“他正在吃饭，还没吃完。”早已表示动作已完成，与“正在吃饭”的进行状态矛盾。"}, {"text": "他下个月早已要结婚了。", "explanation": "这里应该用〈就〉。早已表示事情很早以前已经发生，不能用于下个月这样的将来时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他早已会忘了那件事。", "corrected_sentence": "他早已忘了那件事。", "error_description": "错误形式：“早已会忘了”。正确形式：“早已忘了”。“早已”表示事情很早以前就已经发生，不能再和表示将来的“会”连用，应删去“会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她早已要买好了票。", "corrected_sentence": "她早已买好了票。", "error_description": "错误形式：“早已要买好了票”。正确形式：“早已买好了票”。“早已”表示动作早就完成，不能和表示将要发生的“要”连用，应删去“要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
