INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23360, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23360, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以灵活地移动或改变。", "primary_collocate": null, "pronunciation": "jī dòng", "ipa": "tɕi˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这支球队打法机动，很难防守。", "target_word": "机动", "complexity_tier": "T3", "furigana": "zhè zhī qiúduì dǎfǎ jīdòng, hěn nán fángshǒu.", "sentence_source": "generated"}, {"text": "我们的上班时间比较机动。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支小队行动机动，速度很快。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给了我们机动的时间。", "target_word": "机动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作时间很机动，可以随时调整。", "target_word": "机动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司决策机动，能随时调整方案。", "target_word": "机动", "complexity_tier": "T3", "furigana": "zhè jiā gōngsī juécè jīdòng, néng suíshí tiáozhěng fāng''àn.", "sentence_source": "generated"}, {"text": "这支救援队很机动，哪里需要就去哪里。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事很机动，遇到问题能很快变通。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他处理问题很机动，不死板。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司让员工机动安排上下班时间。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "机动性", "label": "复合"}, {"form": "機動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "安排、行动等灵活，可随时调整", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '496a1d38-b3d1-4f3e-a711-3178efd8b036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机动", "is_correct": true, "explanation": "正确：“打法机动”指战术灵活多变，与后句“很难防守”相呼应。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：“清澈”形容水等透明，不能用来形容打法，句意不通。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写人或物的外形，不能用来形容打法。"}, {"text": "固定", "is_correct": false, "explanation": "语义：固定的打法容易被预判，与后句“很难防守”矛盾。"}], "explanations": {"机动": "正确：“打法机动”指战术灵活多变，与后句“很难防守”相呼应。", "清澈": "语义：“清澈”形容水等透明，不能用来形容打法，句意不通。", "高大": "体貌：“高大”描写人或物的外形，不能用来形容打法。", "固定": "语义：固定的打法容易被预判，与后句“很难防守”矛盾。"}, "sentence_index": 0, "correct_answer": "机动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很机动，怎么也推不动。", "explanation": "这里应该用〈稳固〉。“机动”指可以灵活移动或调整，与“怎么也推不动”自相矛盾。"}, {"text": "他的口语很机动，说得很流利。", "explanation": "这里应该用〈流利〉。形容说话流畅要说“流利”，“机动”表示行动、变化的灵活，不用于形容口语。"}, {"text": "他的听力很机动，能听清远处的声音。", "explanation": "这里应该用〈灵敏〉。形容听觉反应敏锐要说“灵敏”，“机动”指行动或战术上的灵活，不用于听力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机动", "is_correct": true, "explanation": "正确：“很机动”指能灵活调动，与“哪里需要就去哪里”相呼应。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：“清澈”形容水透明，不能形容救援队。"}, {"text": "苦涩", "is_correct": false, "explanation": "语义：“苦涩”形容味道或心情，与救援队的行动无关。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容物体能透光，不能形容队伍行动灵活。"}], "explanations": {"机动": "正确：“很机动”指能灵活调动，与“哪里需要就去哪里”相呼应。", "清澈": "语义：“清澈”形容水透明，不能形容救援队。", "苦涩": "语义：“苦涩”形容味道或心情，与救援队的行动无关。", "透明": "语义：“透明”形容物体能透光，不能形容队伍行动灵活。"}, "sentence_index": 6, "correct_answer": "机动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个歌手的嗓音很机动。", "explanation": "这里应该用〈灵活〉。形容嗓音变化自如要说“灵活”，“机动”多用于行动、计划等的可调整性。"}, {"text": "这份合同条款很机动，一个字也不能改。", "explanation": "这里应该用〈死板〉。“机动”指可以灵活调整，与“一个字也不能改”自相矛盾。"}, {"text": "她的眼神很机动，看起来很可爱。", "explanation": "这里应该用〈灵动〉。形容眼神活泼生动要说“灵动”，“机动”不用于描写眼神。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们行动很机动性，能迅速转移。", "corrected_sentence": "他们行动很机动，能迅速转移。", "error_description": "词性错误：“很”修饰的是形容词，“机动性”是名词，不能用“很”修饰。正确的说法是“行动很机动”，错误的说法是“行动很机动性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一套很机动方案。", "corrected_sentence": "这是一套很机动的方案。", "error_description": "错误：“很机动”修饰名词时，中间要加“的”，应说“很机动的方案”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
