INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情向前走。", "primary_collocate": null, "pronunciation": "tuī jìn", "ipa": "tʰweɪ̯˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "经理希望我们尽快推进这个新项目。", "target_word": "推进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在一步一步推进新计划。", "target_word": "推进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把学习计划推进得很顺利。", "target_word": "推进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国领导人一起推进双方的合作。", "target_word": "推进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项工作推进得太慢，大家都很着急。", "target_word": "推进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要更多时间来推进这件事。", "target_word": "推进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府今年大力推进了城市建设。", "target_word": "推进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了推进谈判，双方都做了让步。", "target_word": "推进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校正在推进新的教学改革。", "target_word": "推进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起努力，才能把工作推进下去。", "target_word": "推进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推进了", "label": "完成体"}, {"form": "推进着", "label": "进行体"}, {"form": "推进过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "让工作、计划等事情继续向前发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca8c494-ae71-4330-9c72-7312641af8a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23362, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "推进", "is_correct": true, "explanation": "正确。推进（tuī jìn）表示让事情向前走。"}, {"text": "推荐", "is_correct": false, "explanation": "tuī jiàn 与 tuī jìn 韵母不同（-ian 与 -in），意思是介绍好的人或事物。"}, {"text": "腿劲", "is_correct": false, "explanation": "tuǐ（第三声）与 tuī（第一声）声调不同，意思是腿的力气。"}, {"text": "退尽", "is_correct": false, "explanation": "tuì（第四声）与 tuī（第一声）声调不同，意思是退去、退完。"}], "explanations": {"推进": "正确。推进（tuī jìn）表示让事情向前走。", "推荐": "tuī jiàn 与 tuī jìn 韵母不同（-ian 与 -in），意思是介绍好的人或事物。", "腿劲": "tuǐ（第三声）与 tuī（第一声）声调不同，意思是腿的力气。", "退尽": "tuì（第四声）与 tuī（第一声）声调不同，意思是退去、退完。"}, "sentence_index": null, "correct_answer": "推进"}, "level_3": {"options": [{"text": "推进", "is_correct": true, "explanation": "正确。“尽快”与“新项目”都可以与推进搭配，表示让项目向前走。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说“吃这个新项目”。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”的对象是帽子、眼镜之类的物品，不能带“项目”作宾语。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”的对象是火、灯，不能说“熄灭项目”。"}], "explanations": {"推进": "正确。“尽快”与“新项目”都可以与推进搭配，表示让项目向前走。", "吃": "语义：“吃”的对象是食物，不能说“吃这个新项目”。", "戴": "搭配：“戴”的对象是帽子、眼镜之类的物品，不能带“项目”作宾语。", "熄灭": "搭配：“熄灭”的对象是火、灯，不能说“熄灭项目”。"}, "sentence_index": 0, "correct_answer": "推进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的鼓励推进了我去参加比赛。", "explanation": "这里应该用〈推动〉。推进用于工作、计划等事务的向前进展，不说“推进某人去做某事”。"}, {"text": "革命推进了旧政权。", "explanation": "这里应该用〈推翻〉。推进指事务向前进展，推翻政权要说“推翻”。"}, {"text": "他推进了这次邀请。", "explanation": "这里应该用〈推辞〉。推进指事务向前进展，拒绝邀请要说“推辞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推进", "is_correct": true, "explanation": "正确。“大力”与“城市建设”搭配，表示推动建设向前进行。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”的对象是食物等物体，不能说吞“城市建设”。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是桌面、玻璃等具体物体，不能擦“城市建设”。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”的对象是纸张、布料等，不能撕“城市建设”。"}], "explanations": {"推进": "正确。“大力”与“城市建设”搭配，表示推动建设向前进行。", "吞": "语义：“吞”的对象是食物等物体，不能说吞“城市建设”。", "擦": "搭配：“擦”的对象是桌面、玻璃等具体物体，不能擦“城市建设”。", "撕": "搭配：“撕”的对象是纸张、布料等，不能撕“城市建设”。"}, "sentence_index": 6, "correct_answer": "推进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "规律作息能推进身体健康。", "explanation": "这里应该用〈促进〉。推进用于事务的向前进展，身体健康要说“促进”。"}, {"text": "这件事推进他改变了想法。", "explanation": "这里应该用〈促使〉。推进的对象是事务，不能说“推进某人改变想法”。"}, {"text": "这首老歌推进了我的回忆。", "explanation": "这里应该用〈唤起〉。推进不与“回忆”搭配，勾起回忆要说“唤起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要把这个计划推进去下。", "corrected_sentence": "我们要把这个计划推进下去。", "error_description": "补语语序错误：“下去”是趋向补语，必须放在动词之后。应说“推进下去”，不能说“推进去下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次的研究推进的很快。", "corrected_sentence": "这次的研究推进得很快。", "error_description": "结构助词误用：推进后引出程度补语要用“得”，不能用“的”。应说“推进得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
