INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "燃油是机器或汽车用来跑的油。", "primary_collocate": null, "pronunciation": "rán yóu", "ipa": "ɻan˧˥ joʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我的车没有燃油了。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "燃油太贵，我们少开车。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电动车不需要燃油。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他去加油站买燃油。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这辆车很省燃油。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "卡车一次要加很多燃油。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发动机没有燃油就不能工作。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些燃油是给拖拉机用的。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "摩托车的燃油用完了。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开慢一点可以节约燃油。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "燃油车", "label": "复合"}, {"form": "燃油费", "label": "复合"}], "register": "中性", "sense_fingerprint": "汽车、机器靠它运转的油", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '496a1d38-b3d1-4f3e-a711-3178efd8b036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "燃油", "is_correct": true, "explanation": "正确：“没有燃油了”说的是汽车的油已用完，符合句意。"}, {"text": "面包", "is_correct": false, "explanation": "语义：汽车不能靠面包运转，“没有面包了”说的是食物，与汽车无关。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：汽车不靠咖啡运转，“没有咖啡了”与汽车的状态无关。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：汽车不靠牛奶运转，“车没有牛奶了”说不通。"}], "explanations": {"燃油": "正确：“没有燃油了”说的是汽车的油已用完，符合句意。", "面包": "语义：汽车不能靠面包运转，“没有面包了”说的是食物，与汽车无关。", "咖啡": "语义：汽车不靠咖啡运转，“没有咖啡了”与汽车的状态无关。", "牛奶": "语义：汽车不靠牛奶运转，“车没有牛奶了”说不通。"}, "sentence_index": 0, "correct_answer": "燃油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的轴承要定期加燃油。", "explanation": "这里应该用〈润滑油〉。轴承需要润滑，燃油是机器用来燃烧的液体燃料，不用于润滑。"}, {"text": "妈妈往菜里倒了一点燃油。", "explanation": "这里应该用〈食用油〉。做菜放的是食用油，燃油是机器用的燃料，不能吃。"}, {"text": "奶奶用燃油织了一件毛衣。", "explanation": "这里应该用〈毛线〉。织毛衣要用毛线，燃油是汽车、机器用的油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "燃油", "is_correct": true, "explanation": "正确：发动机靠燃油燃烧工作，“没有燃油就不能工作”符合常识。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：发动机没有眼睛，“眼睛”是人的器官，不能用来描述机器，句子不通。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料与发动机工作无关，“没有颜料就不能工作”不成立。"}, {"text": "地图", "is_correct": false, "explanation": "语义：发动机不靠地图运转，“没有地图就不能工作”与句意不符。"}], "explanations": {"燃油": "正确：发动机靠燃油燃烧工作，“没有燃油就不能工作”符合常识。", "眼睛": "体貌：发动机没有眼睛，“眼睛”是人的器官，不能用来描述机器，句子不通。", "颜料": "语义：颜料与发动机工作无关，“没有颜料就不能工作”不成立。", "地图": "语义：发动机不靠地图运转，“没有地图就不能工作”与句意不符。"}, "sentence_index": 6, "correct_answer": "燃油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车水箱里要加燃油。", "explanation": "这里应该用〈冷却液〉。水箱需要冷却液，燃油只用于燃烧，加进水箱会损坏发动机。"}, {"text": "他用燃油擦皮鞋，把鞋子擦得很亮。", "explanation": "这里应该用〈鞋油〉。擦鞋要用“鞋油”，“燃油”是机器、汽车用来跑的油，不用于擦鞋。"}, {"text": "钢笔里要加燃油。", "explanation": "这里应该用〈墨水〉。钢笔要加墨水，燃油是机器用的液体燃料，不能用于书写工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车加了一个燃油。", "corrected_sentence": "这辆车加了一升燃油。", "error_description": "错误：燃油是液体，量词应用“升”“桶”等，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把燃油们倒进了油箱。", "corrected_sentence": "我把燃油倒进了油箱。", "error_description": "用词错误：“们”一般只加在指人的名词后，燃油是液体，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90561d4e-4e70-4821-9129-66d542fa5dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
