INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "颗粒物是很小很小的东西，比如灰尘或烟，可以飘在空气里。", "primary_collocate": null, "pronunciation": "kē lì wù", "ipa": "kʰɤ˥ li˥˩ u˥˩", "syllable_count": 3, "sentences": [{"text": "风一吹，颗粒物就飘在空气里。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的颗粒物多，我一打扫就咳嗽。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光下能看见空中的颗粒物。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽烟会产生很多颗粒物。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家安装了空气净化器，用来清除颗粒物。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙尘天气里，颗粒物特别多。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "颗粒物太小了，口罩能挡住一部分。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子咳嗽，可能是吸入了颗粒物。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说，今天颗粒物超标了。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水能把空气中的颗粒物洗掉。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "细颗粒物", "label": "复合"}, {"form": "可吸入颗粒物", "label": "复合"}, {"form": "顆粒物", "label": "繁体"}], "register": "书面", "sense_fingerprint": "飘在空气里的很小的东西，如灰尘或烟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83fd6bf9-3bac-4e2e-a8b7-ad5e5b0c673f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颗粒物", "is_correct": true, "explanation": "正确：颗粒物是飘在空气里很小的东西，风一吹就会飘起来。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是固体块状物，不会因为风吹就飘在空气里，句义不通。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头又重又大，风吹不起来，与“飘在空气里”的描述矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "体貌：汽车体积太大，风吹不会让它飘在空气里。"}], "explanations": {"颗粒物": "正确：颗粒物是飘在空气里很小的东西，风一吹就会飘起来。", "玻璃": "语义：玻璃是固体块状物，不会因为风吹就飘在空气里，句义不通。", "石头": "体貌：石头又重又大，风吹不起来，与“飘在空气里”的描述矛盾。", "汽车": "体貌：汽车体积太大，风吹不会让它飘在空气里。"}, "sentence_index": 0, "correct_answer": "颗粒物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花园里开满了颗粒物。", "explanation": "这里应该用〈鲜花〉。“开满”用于花，颗粒物是细小微粒，不会开放。"}, {"text": "他一口气喝了三杯颗粒物。", "explanation": "这里应该用〈水〉。“喝”的对象是液体或饮料，颗粒物是飘在空气里的微粒，不能喝。"}, {"text": "他早上把颗粒物穿在身上就出门了。", "explanation": "这里应该用〈衣服〉。“穿”的对象是衣服，颗粒物是飘在空气里的微粒，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颗粒物", "is_correct": true, "explanation": "正确：颗粒物很小，口罩能挡住其中一部分，句义通顺。"}, {"text": "大树", "is_correct": false, "explanation": "体貌：大树体积很大，不会说“太小了”，与句中的描述矛盾。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，与口罩挡住的对象无关，句义不通。"}, {"text": "篮球", "is_correct": false, "explanation": "体貌：篮球并不算太小，而且不会飘在空气里被口罩挡住，与句义不符。"}], "explanations": {"颗粒物": "正确：颗粒物很小，口罩能挡住其中一部分，句义通顺。", "大树": "体貌：大树体积很大，不会说“太小了”，与句中的描述矛盾。", "冰箱": "语义：冰箱是家用电器，与口罩挡住的对象无关，句义不通。", "篮球": "体貌：篮球并不算太小，而且不会飘在空气里被口罩挡住，与句义不符。"}, "sentence_index": 6, "correct_answer": "颗粒物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子在教室里唱颗粒物。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌曲，颗粒物不能唱。"}, {"text": "妈妈在厨房里用颗粒物包饺子。", "explanation": "这里应该用〈面皮〉。包饺子要用面皮和馅料，颗粒物不是食材。"}, {"text": "他在院子里种下了一些颗粒物。", "explanation": "这里应该用〈种子〉。“种下”的对象是种子或植株，颗粒物是飘在空气里的微粒，不能种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一带的空气里飘着一只颗粒物。", "corrected_sentence": "这一带的空气里飘着大量颗粒物。", "error_description": "量词错误：颗粒物是许多细小微粒，不能用“只”计量，应该用“大量”或“一些”。正确说法是“飘着大量颗粒物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "清扫以后，屋里的颗粒物的减少了。", "corrected_sentence": "清扫以后，屋里的颗粒物减少了。", "error_description": "多了一个“的”：“颗粒物的减少”变成名词性短语，“了”没有可以附着的谓语，句子不通。应去掉这个“的”，说“屋里的颗粒物减少了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d3fd9e-6719-42ae-aecb-7908f9138bd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d3fd9e-6719-42ae-aecb-7908f9138bd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "有些东西会变成气体跑到空气里，比如水放久了会变少。", "primary_collocate": null, "pronunciation": "huī fā xìng", "ipa": "xweɪ̯˥ fa˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "酒精挥发性强，瓶盖要盖好。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水放久了会变少，是因为水有挥发性。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "香水的挥发性大，味道很快就散了。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽油的挥发性很强，要远离火。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶药水挥发性强，用完要盖紧。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热水的挥发性比冷水强。", "target_word": "挥发性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "油的挥发性不高，放着也不会变少。", "target_word": "挥发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，有挥发性的东西不要放在太阳下。", "target_word": "挥发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖没有挥发性，所以闻不到味道。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道哪种液体的挥发性最强吗？", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "揮發性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西变成气体跑到空气里的特点（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e9150-69f4-44b7-adad-dbaca64380dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挥发性", "is_correct": true, "explanation": "正确。“酒精挥发性强”说明酒精容易变成气体，所以瓶盖要盖好。"}, {"text": "纯度", "is_correct": false, "explanation": "搭配：“纯度”说高低要用“高”，不说“强”；而且纯度与瓶盖要盖好无关。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：酒精是液体，没有硬度，“酒精硬度强”不成立。"}, {"text": "密度", "is_correct": false, "explanation": "搭配：“密度”一般说“大”或“高”，不说“强”，句子不通。"}], "explanations": {"挥发性": "正确。“酒精挥发性强”说明酒精容易变成气体，所以瓶盖要盖好。", "纯度": "搭配：“纯度”说高低要用“高”，不说“强”；而且纯度与瓶盖要盖好无关。", "硬度": "语义：酒精是液体，没有硬度，“酒精硬度强”不成立。", "密度": "搭配：“密度”一般说“大”或“高”，不说“强”，句子不通。"}, "sentence_index": 0, "correct_answer": "挥发性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糖的挥发性很好，放进水里很快就化了。", "explanation": "这里应该用〈溶解性〉。放进水里很快化掉说的是溶解，挥发性指变成气体跑到空气里。"}, {"text": "铜的挥发性很好，常用来做电线。", "explanation": "这里应该用〈导电性〉。做电线是因为铜能导电，挥发性与做电线无关。"}, {"text": "这个人的挥发性很强，一说话就发脾气。", "explanation": "挥发性只用于物质，指东西变成气体的特点，不能用来形容人的脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d3fd9e-6719-42ae-aecb-7908f9138bd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挥发性", "is_correct": true, "explanation": "正确。“油的挥发性不高”说明油不容易变成气体，所以放着也不会变少。"}, {"text": "弹性", "is_correct": false, "explanation": "语义：“弹性”指物体恢复原状的能力，油没有这种性质，句子不通。"}, {"text": "韧性", "is_correct": false, "explanation": "搭配：“韧性”用来形容材料不易折断，不能用来描述油放着会不会变少。"}, {"text": "延展性", "is_correct": false, "explanation": "语义：“延展性”指材料能被拉长或压薄，与油放着会不会变少无关。"}], "explanations": {"挥发性": "正确。“油的挥发性不高”说明油不容易变成气体，所以放着也不会变少。", "弹性": "语义：“弹性”指物体恢复原状的能力，油没有这种性质，句子不通。", "韧性": "搭配：“韧性”用来形容材料不易折断，不能用来描述油放着会不会变少。", "延展性": "语义：“延展性”指材料能被拉长或压薄，与油放着会不会变少无关。"}, "sentence_index": 6, "correct_answer": "挥发性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种糖浆的挥发性很大，倒出来很慢。", "explanation": "这里应该用〈黏度〉。倒出来很慢说明的是黏稠程度，挥发性指变成气体的特点。"}, {"text": "酒精的挥发性是七十八摄氏度，加热要小心。", "explanation": "这里应该用〈沸点〉。七十八摄氏度是酒精开始沸腾的温度，挥发性不能用温度数字来表示。"}, {"text": "这块玻璃的挥发性很强，一摔就碎。", "explanation": "这里应该用〈脆性〉。一摔就碎说的是容易碎，挥发性指东西变成气体跑到空气里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d3fd9e-6719-42ae-aecb-7908f9138bd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这罐喷雾地挥发性很强，用完要拧紧。", "corrected_sentence": "这罐喷雾的挥发性很强，用完要拧紧。", "error_description": "错误形式：“喷雾地挥发性”，“地”用于修饰动词，修饰名词“挥发性”前应用“的”。正确形式：“喷雾的挥发性很强”，“的”连接名词与其修饰语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d3fd9e-6719-42ae-aecb-7908f9138bd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种香精是挥发性，用完要盖紧。", "corrected_sentence": "这种香精有挥发性，用完要盖紧。", "error_description": "错误形式：“是挥发性”，“是”用于判断，不能直接接表示性质的名词；表示物质具有某种性质应用“有”。正确形式：“有挥发性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d3fd9e-6719-42ae-aecb-7908f9138bd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
