INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23376, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "光化学是研究光如何让东西发生化学变化。", "primary_collocate": null, "pronunciation": "guāng huà xué", "ipa": "kuaŋ˥ xu̯a˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "光化学研究光怎么改变东西。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学光化学，要先知道光是什么。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光化学告诉我们，太阳光会让东西变色。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最喜欢的课是光化学。", "target_word": "光化学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "光化学能解释衣服为什么晒久会变色。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老照片会变黄，这是光化学的问题。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在大学里教光化学。", "target_word": "光化学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "光化学跟光有很大的关系。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习光化学的时候，他做了很多实验。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物靠光合作用长大，这和光化学有关系。", "target_word": "光化学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "光化学反应", "label": "复合"}, {"form": "光化学烟雾", "label": "复合"}], "register": "中性", "sense_fingerprint": "研究光怎样使物质发生化学变化的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e9150-69f4-44b7-adad-dbaca64380dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光化学", "is_correct": true, "explanation": "正确：光化学是研究光怎样改变东西的学科，句中“研究光怎么改变东西”指的正是它。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地方，不能作为研究光变化的学科。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育研究的是身体活动，与光怎样改变东西无关。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“研究”的主语应是人或学科，“面包”是食物，不能作研究的主体。"}], "explanations": {"光化学": "正确：光化学是研究光怎样改变东西的学科，句中“研究光怎么改变东西”指的正是它。", "厨房": "语义：厨房是地方，不能作为研究光变化的学科。", "体育": "语义：体育研究的是身体活动，与光怎样改变东西无关。", "面包": "搭配：“研究”的主语应是人或学科，“面包”是食物，不能作研究的主体。"}, "sentence_index": 0, "correct_answer": "光化学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师用光化学解释汽车为什么会动。", "explanation": "这里应该用〈物理〉。物理研究力与运动，光化学研究光引起的化学变化，二者不能互换。"}, {"text": "我最喜欢的一把光化学很难学。", "explanation": "这里应该用〈门〉。〈把〉用于有柄的器具，学科应用〈门〉，应说“一门光化学”。"}, {"text": "这本书专门讲解细胞的分裂，是光化学的书。", "explanation": "这里应该用〈生物学〉。生物学研究细胞和生命现象，光化学研究光引起的化学变化，细胞分裂不属于光化学的范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d3fd9e-6719-42ae-aecb-7908f9138bd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光化学", "is_correct": true, "explanation": "正确：“她在大学里教光化学”，光化学是可以教授的学科，符合句意。"}, {"text": "烤箱", "is_correct": false, "explanation": "语义：烤箱是电器，不是可以被教授的知识，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为大学里被教授的内容。"}, {"text": "地板", "is_correct": false, "explanation": "搭配：“教”的对象应是知识或技能，“地板”是物体，不能与“教”搭配。"}], "explanations": {"光化学": "正确：“她在大学里教光化学”，光化学是可以教授的学科，符合句意。", "烤箱": "语义：烤箱是电器，不是可以被教授的知识，句意不通。", "天气": "语义：天气是自然现象，不能作为大学里被教授的内容。", "地板": "搭配：“教”的对象应是知识或技能，“地板”是物体，不能与“教”搭配。"}, "sentence_index": 6, "correct_answer": "光化学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "光化学研究的是古代皇帝的故事。", "explanation": "这里应该用〈历史〉。历史研究过去的人和事，光化学研究光引起的化学变化。"}, {"text": "光化学研究的是人的情绪怎样变化，很有意思。", "explanation": "这里应该用〈心理学〉。心理学研究人的情绪与心理活动，光化学研究光引起的化学变化，不研究情绪。"}, {"text": "这门光化学研究电池里的电流，很有意思。", "explanation": "这里应该用〈电化学〉。电化学研究电与化学反应的关系，电池里的电流属于电化学；光化学研究光引起的化学变化，不研究电流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d3fd9e-6719-42ae-aecb-7908f9138bd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想学一只光化学。", "corrected_sentence": "我想学一门光化学。", "error_description": "错误：“一只光化学”，“只”用于动物或成对物件中的一个，学科应用“门”。正确为“一门光化学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d3fd9e-6719-42ae-aecb-7908f9138bd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他光化学很有兴趣。", "corrected_sentence": "他对光化学很有兴趣。", "error_description": "错误：漏掉了介词“对”。“有兴趣”的对象要用“对……有兴趣”引出，应写作“对光化学很有兴趣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4d3fd9e-6719-42ae-aecb-7908f9138bd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
