INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23378, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用一个人或东西换另一个人或东西。", "primary_collocate": null, "pronunciation": "tì dài", "ipa": "tʰi˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这种新材料可以替代塑料。", "target_word": "替代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器人正在替代工人做危险的工作。", "target_word": "替代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用电子书替代纸质书，书包轻多了。", "target_word": "替代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "糖太多不好，我用蜂蜜替代白糖。", "target_word": "替代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机已经替代了很多老式相机。", "target_word": "替代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种新技术很快替代了旧技术。", "target_word": "替代", "complexity_tier": "T3", "furigana": "zhè zhǒng xīn jì shù hěn kuài tì dài le jiù jì shù.", "sentence_source": "generated"}, {"text": "没有什么东西能替代妈妈做的饭。", "target_word": "替代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个零件坏了，要找别的来替代它。", "target_word": "替代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳能正在慢慢替代煤炭，空气会更干净。", "target_word": "替代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用新办法替代过去那个旧办法。", "target_word": "替代", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "替代了", "label": "体标"}, {"form": "替代过", "label": "体标"}, {"form": "替代品", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：用一个事物换掉另一个事物，让新的取代旧的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37088c36-b988-4c59-bd87-98a844545e6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "替代", "is_correct": true, "explanation": "“替代”表示用新的东西换掉旧的，“这种新材料可以替代塑料”语义通顺。"}, {"text": "相信", "is_correct": false, "explanation": "配价：“相信”的对象应是人或观点，不能以“塑料”作为对象。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”的对象一般是人，不能用于“塑料”这样的物体。"}, {"text": "热爱", "is_correct": false, "explanation": "搭配：“热爱”表示强烈的喜爱之情，与描述材料功能的句子不搭配。"}], "explanations": {"替代": "“替代”表示用新的东西换掉旧的，“这种新材料可以替代塑料”语义通顺。", "相信": "配价：“相信”的对象应是人或观点，不能以“塑料”作为对象。", "感谢": "配价：“感谢”的对象一般是人，不能用于“塑料”这样的物体。", "热爱": "搭配：“热爱”表示强烈的喜爱之情，与描述材料功能的句子不搭配。"}, "sentence_index": 0, "correct_answer": "替代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司用奖金替代员工的损失。", "explanation": "这里应该用〈补偿〉。替代是用一物换另一物，损失不能被替代，应该用“补偿”。"}, {"text": "节日里我们用彩灯替代房间。", "explanation": "这里应该用〈装饰〉。替代是用一物换另一物，不能用来说布置房间；布置房间要用“装饰”。"}, {"text": "老师耐心替代了我的问题。", "explanation": "这里应该用〈解答〉。替代是换掉另一物，不能用来说回答问题；回答问题要用“解答”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "替代", "is_correct": true, "explanation": "“替代”表示用一样东西代替另一样，与“没有什么东西能……妈妈做的饭”的语境相符。"}, {"text": "解释", "is_correct": false, "explanation": "语义：“解释”指说明道理，不能用来说明饭的替代，句子无法成立。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」指清扫地方，饭不能被打扫，句子不成立。"}, {"text": "夸奖", "is_correct": false, "explanation": "搭配：“夸奖”的对象多为人或其表现，不能与“妈妈做的饭”这样的泛指事物搭配。"}], "explanations": {"替代": "“替代”表示用一样东西代替另一样，与“没有什么东西能……妈妈做的饭”的语境相符。", "解释": "语义：“解释”指说明道理，不能用来说明饭的替代，句子无法成立。", "打扫": "语义：「打扫」指清扫地方，饭不能被打扫，句子不成立。", "夸奖": "搭配：“夸奖”的对象多为人或其表现，不能与“妈妈做的饭”这样的泛指事物搭配。"}, "sentence_index": 6, "correct_answer": "替代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用伞替代风雨。", "explanation": "这里应该用〈抵挡〉。替代是以一物换另一物，伞不能替代风雨；挡风雨要用“抵挡”。"}, {"text": "他替代了会议的气氛。", "explanation": "这里应该用〈营造〉。替代是以一物换另一物，不能用来表示营造气氛；营造气氛要用“营造”。"}, {"text": "这家超市替代了午饭。", "explanation": "这里应该用〈供应〉。替代需要有被换掉的对象，超市并不是替代午饭，应说“供应午饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把电子邮件替代了纸质信件。", "corrected_sentence": "他们用电子邮件替代了纸质信件。", "error_description": "错误：「把电子邮件替代了……」。正确：「用电子邮件替代了……」。「把」字句的宾语应是被替换掉的东西（纸质信件），这里把用来替换的电子邮件放在「把」后，意思颠倒了；用来替换的东西应由「用」引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个新办法很替代旧办法。", "corrected_sentence": "这个新办法能替代旧办法。", "error_description": "错误：“很替代”。正确：“能替代”。“很”用于修饰形容词，不能直接修饰“替代”这类动作动词；表示可能时应用“能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
