INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "是很多很小很小的脏东西飘在空气里，看起来像云一样，看不清远处的东西。", "primary_collocate": null, "pronunciation": "yān wù", "ipa": "jɛn˥ wu˥˩", "syllable_count": 2, "sentences": [{"text": "今天城里有烟雾，看不清远处。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的烟雾像云一样。", "target_word": "烟雾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "烟雾太大，司机把车开得很慢。", "target_word": "烟雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气里有烟雾，我不想出门。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林起火了，天空中全是烟雾。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟雾里的灰尘很脏，对身体不好。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风一吹，烟雾就散开了。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在烟雾中走了很久。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空灰灰的，全是烟雾，没有蓝天。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们看不见高楼，因为烟雾太浓。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "团", "label": "量词"}, {"form": "股", "label": "量词"}, {"form": "烟雾弹", "label": "复合"}, {"form": "煙霧", "label": "繁体"}], "register": "通用", "sense_fingerprint": "飘在空气里像云一样、让人看不清远处的细小脏东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2641bdb-13ce-41f5-bba7-a0b5d6e4f643') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烟雾", "is_correct": true, "explanation": "正确：烟雾飘在城里，让人看不清远处，句意成立。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光让人看得更清楚，与“看不清远处”矛盾。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声不影响视线，与“看不清远处”没有关系。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“城里有”后接的是可以存在的事物，“尺寸”是度量，不能这样用。"}], "explanations": {"烟雾": "正确：烟雾飘在城里，让人看不清远处，句意成立。", "阳光": "语义：阳光让人看得更清楚，与“看不清远处”矛盾。", "歌声": "语义：歌声不影响视线，与“看不清远处”没有关系。", "尺寸": "搭配：“城里有”后接的是可以存在的事物，“尺寸”是度量，不能这样用。"}, "sentence_index": 0, "correct_answer": "烟雾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天上飘着一只烟雾，像云一样。", "explanation": "这里量词应用〈团〉或〈股〉，不用“只”。烟雾不用“只”计量。"}, {"text": "我渴了，倒了一杯烟雾喝。", "explanation": "这里应该用〈水〉。烟雾是飘在空气里的脏东西，不能倒在杯子里喝。"}, {"text": "他在森林里采了一篮烟雾。", "explanation": "这里把烟雾当成了可以采摘装篮的〈野菜〉；烟雾是飘浮的颗粒，不能采来装篮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烟雾", "is_correct": true, "explanation": "正确：烟雾是一团飘浮的颗粒，风一吹就会散开，句意成立。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“散开”多用于烟雾、人群，不说雨散开，雨应说“停”。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：灯光不会被风吹散，句子不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是可以随风散开的东西。"}], "explanations": {"烟雾": "正确：烟雾是一团飘浮的颗粒，风一吹就会散开，句意成立。", "雨": "搭配：“散开”多用于烟雾、人群，不说雨散开，雨应说“停”。", "灯光": "语义：灯光不会被风吹散，句子不通。", "价格": "语义：价格不是可以随风散开的东西。"}, "sentence_index": 6, "correct_answer": "烟雾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里用烟雾煮了汤。", "explanation": "这里应该用〈蒸汽〉或〈火〉。烟雾是脏颗粒，不能用来煮东西；煮汤要用蒸汽或火。"}, {"text": "妈妈用烟雾把衣服洗干净了。", "explanation": "这里应该用〈洗衣粉〉。烟雾是脏东西，不能用来洗衣服。"}, {"text": "他把烟雾捏成一个球，放进口袋里。", "explanation": "这里把烟雾当成了可以捏成球的〈面团〉；烟雾是飘浮的颗粒，无法捏成球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天上飘着一个烟雾。", "corrected_sentence": "天上飘着一股烟雾。", "error_description": "量词错误：烟雾用“股”或“团”计量，“个”不适合。正确：一股烟雾；错误：一个烟雾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大风把烟雾们吹散了。", "corrected_sentence": "大风把烟雾吹散了。", "error_description": "“烟雾”是物质名词，不能加“们”表示复数；“们”只用于指人或拟人的名词。应去掉“们”，说“大风把烟雾吹散了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
