INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23386, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一种东西加到另一种东西里，让味道变淡。", "primary_collocate": null, "pronunciation": "xī shì", "ipa": "ɕi˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "汤太咸了，加点水稀释一下吧。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "果汁太甜，我用冰水稀释了它。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯咖啡太苦，加点牛奶稀释一下就好了。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "辣椒酱太辣，可以加番茄酱稀释。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浓茶太涩，她兑了些开水稀释。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不爱喝浓果汁，妈妈总是加水稀释。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酱油太咸，加些水稀释就不会那么咸了。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶茶太浓了，多加冰块来稀释。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜂蜜水太甜，再加点温水稀释吧。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把浓浓的咖啡用热水稀释了。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "稀释了", "label": "体标"}, {"form": "稀释过", "label": "体标"}, {"form": "稀释液", "label": "复合"}, {"form": "稀释剂", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常饮食中，加水等东西让味道变淡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2641bdb-13ce-41f5-bba7-a0b5d6e4f643') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23386, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "稀释", "is_correct": true, "explanation": "稀释指加入液体使味道变淡，是本词的读音与意思。"}, {"text": "喜事", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，喜事意思是高兴的事。"}, {"text": "失事", "is_correct": false, "explanation": "shī 与 xī 声母不同（sh 与 x），失事意思是发生事故。"}, {"text": "西施", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，西施是古代美女的名字。"}], "explanations": {"稀释": "稀释指加入液体使味道变淡，是本词的读音与意思。", "喜事": "xǐ（第三声）与 xī（第一声）声调不同，喜事意思是高兴的事。", "失事": "shī 与 xī 声母不同（sh 与 x），失事意思是发生事故。", "西施": "shī（第一声）与 shì（第四声）声调不同，西施是古代美女的名字。"}, "sentence_index": null, "correct_answer": "稀释"}, "level_3": {"options": [{"text": "稀释", "is_correct": true, "explanation": "“汤太咸了，加点水稀释一下”指加水使咸味变淡，符合语境。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：煮沸是加热到沸腾，不能使汤的咸味变淡。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干是去掉水分，与加水使汤变淡的意思相反。"}, {"text": "收集", "is_correct": false, "explanation": "搭配：“收集”需要收集的对象，不能说“加点水收集一下”。"}], "explanations": {"稀释": "“汤太咸了，加点水稀释一下”指加水使咸味变淡，符合语境。", "煮沸": "语义：煮沸是加热到沸腾，不能使汤的咸味变淡。", "烘干": "语义：烘干是去掉水分，与加水使汤变淡的意思相反。", "收集": "搭配：“收集”需要收集的对象，不能说“加点水收集一下”。"}, "sentence_index": 0, "correct_answer": "稀释"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汤太淡了，我加了点盐稀释。", "explanation": "这里应该用〈调味〉。汤太淡时要加盐调味，稀释只会让味道更淡。"}, {"text": "她用热水稀释茶叶，想泡出香味。", "explanation": "这里应该用〈泡〉。稀释指加入液体使味道变淡，不指用热水浸泡茶叶。"}, {"text": "萝卜用盐稀释一下。", "explanation": "这里应该用〈腌〉。稀释不指用盐处理食物，腌制才是用盐浸渍的做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀释", "is_correct": true, "explanation": "“加些水稀释就不会那么咸了”符合加水降低咸味的语境。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：冻结是变成固体，与加水让酱油变淡无关。"}, {"text": "过滤", "is_correct": false, "explanation": "语义：过滤是去除杂质，不能使酱油的咸味变淡。"}, {"text": "腌制", "is_correct": false, "explanation": "语义：腌制是用盐浸渍，会使食物更咸，与句意相反。"}], "explanations": {"稀释": "“加些水稀释就不会那么咸了”符合加水降低咸味的语境。", "冻结": "语义：冻结是变成固体，与加水让酱油变淡无关。", "过滤": "语义：过滤是去除杂质，不能使酱油的咸味变淡。", "腌制": "语义：腌制是用盐浸渍，会使食物更咸，与句意相反。"}, "sentence_index": 6, "correct_answer": "稀释"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "豆腐要稀释五分钟。", "explanation": "这里应该用〈蒸〉。稀释指加入液体使味道变淡，不指用蒸汽加热食物。"}, {"text": "鸡蛋要稀释十分钟。", "explanation": "这里应该用〈煮〉。稀释只能使溶液变淡，不能用于煮鸡蛋。"}, {"text": "这锅排骨要稀释两小时。", "explanation": "这里应该用〈煨〉。煨是小火长时间加热，稀释不能用于这种烹饪方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这锅汤太咸，妈妈把它稀释很淡。", "corrected_sentence": "这锅汤太咸，妈妈把它稀释得很淡。", "error_description": "补语标志缺失：程度补语前要用“得”连接，应说“稀释得很淡”，漏掉“得”则“稀释很淡”不成句。正确：稀释得很淡；错误：稀释很淡。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这瓶果子露太甜，妈妈加了冷水把它稀释。", "corrected_sentence": "这瓶果子露太甜，妈妈加了冷水把它稀释了。", "error_description": "应为“把它稀释了”。“把”字句的谓语后要有“了”或补语等成分，漏掉“了”，句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
