INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23387, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把分散的人力、物力、土地等集中起来统一经营，以提高效率、节约成本。", "primary_collocate": null, "pronunciation": "jí yuē huà", "ipa": "tɕi˧˥ ɥe˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "这个县正在推进土地集约化。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业集约化可以节约很多土地。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几家小工厂集约化后，成本低了很多。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把小仓库集约化管理。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集约化经营让农民的收入增加了。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的服务设施要集约化建设。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把分散的土地集约化，连成了一大片。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养殖业集约化后，一个场能养上万头猪。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，集约化是资源利用的好办法。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的小作坊正在走向集约化。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集約化", "label": "繁体"}, {"form": "集约化经营", "label": "复合"}, {"form": "集约化管理", "label": "复合"}], "register": "书面语", "sense_fingerprint": "集约化|把分散的人力、土地等生产要素集中起来统一经营，以提高效率", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80f0202-2691-4b52-babe-45032a6cb8ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23387, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集约化", "is_correct": true, "explanation": "正确：动词“集约化”表示把分散的土地集中起来，与“推进土地”搭配，语义通顺。"}, {"text": "扩散", "is_correct": false, "explanation": "搭配：“扩散”指向外散开，不能作“推进土地”的谓语，搭配不当。"}, {"text": "分散", "is_correct": false, "explanation": "语义：“分散”与“集约”方向相反，推进的是合并而不是分散。"}, {"text": "荒废", "is_correct": false, "explanation": "语义：“荒废”指土地闲置，与“推进”相矛盾，不符合政策语境。"}], "explanations": {"集约化": "正确：动词“集约化”表示把分散的土地集中起来，与“推进土地”搭配，语义通顺。", "扩散": "搭配：“扩散”指向外散开，不能作“推进土地”的谓语，搭配不当。", "分散": "语义：“分散”与“集约”方向相反，推进的是合并而不是分散。", "荒废": "语义：“荒废”指土地闲置，与“推进”相矛盾，不符合政策语境。"}, "sentence_index": 0, "correct_answer": "集约化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司想把大仓库集约化成几个小仓库。", "explanation": "这里应该用〈拆分〉。“集约化”是把分散的东西合并成整体，拆分与之相反。"}, {"text": "妈妈把蛋糕集约化成八块，分给大家。", "explanation": "这里应该用〈切〉。「集约化」是把分散的东西集中起来，不能表示把蛋糕分成几块；把蛋糕分成八块要用〈切〉。"}, {"text": "他把水集约化成氢和氧。", "explanation": "这里应该用〈分解〉。“集约化”是合并，分解是把化合物拆成组分，二者相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集约化", "is_correct": true, "explanation": "正确：“集约化”表示把分散的土地合并，与“连成了一大片”结果相符。"}, {"text": "分割", "is_correct": false, "explanation": "语义：“分割”是把整体切开，与“连成了一大片”的结果正好相反。"}, {"text": "拆散", "is_correct": false, "explanation": "语义：“拆散”使东西分离，与“连成了一大片”矛盾。"}, {"text": "扩建", "is_correct": false, "explanation": "搭配：“扩建”多用于建筑设施，不用来处理分散的土地，搭配不当。"}], "explanations": {"集约化": "正确：“集约化”表示把分散的土地合并，与“连成了一大片”结果相符。", "分割": "语义：“分割”是把整体切开，与“连成了一大片”的结果正好相反。", "拆散": "语义：“拆散”使东西分离，与“连成了一大片”矛盾。", "扩建": "搭配：“扩建”多用于建筑设施，不用来处理分散的土地，搭配不当。"}, "sentence_index": 6, "correct_answer": "集约化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察把人群集约化，让大家回家。", "explanation": "这里应该用〈疏散〉。“集约化”是聚合，疏散是分开，人群散去应说疏散。"}, {"text": "他的兴趣很集约化。", "explanation": "这里应该用〈广泛〉。“集约化”指把许多人或东西合成整体，不能用来形容兴趣的多少，兴趣广泛应说广泛。"}, {"text": "老师把任务集约化给学生。", "explanation": "这里应该用〈分配〉。“集约化”是聚拢，不是把任务分发给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把几家小店集约化了经营。", "corrected_sentence": "他们把几家小店集约化经营。", "error_description": "“集约化经营”是固定组合，“了”不能插在“集约化”和“经营”之间；应说“他们把几家小店集约化经营”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把分散的货物很集约化，统一运走。", "corrected_sentence": "他们把分散的货物集约化，统一运走。", "error_description": "副词错误：“很”不能修饰动作性动词“集约化”，应删去“很”，说“他们把分散的货物集约化，统一运走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
