INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23390, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让做得不好或不够好的地方变得更好。", "primary_collocate": null, "pronunciation": "gǎi shàn fú wù", "ipa": "kai˨˩˦ ʂan˥˩ fu˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "网店老板答应改善服务，不再让客人等很久。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食堂改善服务后，学生不用排长队了。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家旅行社改善服务，客人给了好评。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请客人提意见，就是想改善服务。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站改善服务，增加了不少帮助乘客的人员。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过培训，店里的人都学会了怎么改善服务。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想改善服务，就先从笑脸迎客做起。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆改善服务，晚上也开门了。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望银行能改善服务，别让老人太着急。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人投诉以后，经理马上要求大家改善服务。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改善服務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把做得不够好的服务做得更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abb8f175-d215-4d05-b870-efdc6b6faf90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23390, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改善服务", "is_correct": true, "explanation": "正确：“答应改善服务”指让服务变好，与“不再让客人等很久”相符。"}, {"text": "停止服务", "is_correct": false, "explanation": "语义：“停止服务”意味着不再提供服务，与“不再让客人等很久”的承诺相矛盾。"}, {"text": "冷落服务", "is_correct": false, "explanation": "搭配：“冷落”的对象通常是人，不能用来搭配“服务”。"}, {"text": "熄灭服务", "is_correct": false, "explanation": "搭配：“熄灭”用于火、灯等，不能用来搭配“服务”。"}], "explanations": {"改善服务": "正确：“答应改善服务”指让服务变好，与“不再让客人等很久”相符。", "停止服务": "语义：“停止服务”意味着不再提供服务，与“不再让客人等很久”的承诺相矛盾。", "冷落服务": "搭配：“冷落”的对象通常是人，不能用来搭配“服务”。", "熄灭服务": "搭配：“熄灭”用于火、灯等，不能用来搭配“服务”。"}, "sentence_index": 0, "correct_answer": "改善服务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这颗蛀牙需要改善服务。", "explanation": "这里应该用〈治疗〉。改善服务只用于提供服务的一方，牙病要说〈治疗〉。"}, {"text": "这面墙太旧了，需要改善服务。", "explanation": "这里应该用〈翻修〉。墙壁是建筑，不是服务，改善服务不能用于它。"}, {"text": "顾客一直改善服务，所以店里越来越好。", "explanation": "这里应该用〈提建议〉。改善服务的主体是提供服务的一方，顾客只能提建议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改善服务", "is_correct": true, "explanation": "正确：“他想改善服务，就先从笑脸迎客做起”，与句中的积极行动相符。"}, {"text": "偷懒", "is_correct": false, "explanation": "语义：“偷懒”与后文“笑脸迎客”的积极做法相矛盾。"}, {"text": "拒绝服务", "is_correct": false, "explanation": "语义：“拒绝服务”与后文“笑脸迎客”的做法直接矛盾。"}, {"text": "怀念服务", "is_correct": false, "explanation": "搭配：“怀念”的对象多为过去的人或事，不能直接搭配“服务”作为行动。"}], "explanations": {"改善服务": "正确：“他想改善服务，就先从笑脸迎客做起”，与句中的积极行动相符。", "偷懒": "语义：“偷懒”与后文“笑脸迎客”的积极做法相矛盾。", "拒绝服务": "语义：“拒绝服务”与后文“笑脸迎客”的做法直接矛盾。", "怀念服务": "搭配：“怀念”的对象多为过去的人或事，不能直接搭配“服务”作为行动。"}, "sentence_index": 6, "correct_answer": "改善服务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的数学成绩很差，所以要改善服务。", "explanation": "这里应该用〈提高〉。改善服务只能用于提供服务的一方，学习成绩要说〈提高〉。"}, {"text": "他的字写得不好，需要改善服务。", "explanation": "这里应该用〈练字〉。改善服务只用于提供服务的行业，写字水平要靠练字来提高。"}, {"text": "这个小区的绿化需要改善服务。", "explanation": "这里应该用〈美化〉。改善服务只用于提供服务的行业，绿化要说〈美化〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店改善服务过，客人明显变多了。", "corrected_sentence": "这家店改善服务了，客人明显变多了。", "error_description": "错误：“改善服务过”；正确：“改善服务了”。“过”表示经历，不能放在宾语“服务”之后表示完成；表示完成应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理把改善服务，还请了新员工。", "corrected_sentence": "经理改善服务，还请了新员工。", "error_description": "错误：“把改善服务”；正确：“改善服务”。“改善服务”是动宾结构，不能被“把”拆开；“把”字句须是“把+宾语+动词”，应去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
