INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23398, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一定时期内交通运输中运送旅客的数量。", "primary_collocate": null, "pronunciation": "kè yùn liàng", "ipa": "kʰɤ˥˩ yn˥˩ ljɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这个汽车站每天的客运量不小。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末地铁的客运量比平时大很多。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，公交车的客运量会变少。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的客运量一年比一年高。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节前，火车站的客运量最大。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条公交线路客运量太小，要取消了。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场的客运量夏天比冬天多。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们统计了这个月汽车站的客运量。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新地铁开通以后，市里的客运量增加了。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日期间，轮渡的客运量特别高。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "交通运输中运送的旅客人次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2641bdb-13ce-41f5-bba7-a0b5d6e4f643') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客运量", "is_correct": true, "explanation": "正确：客运量指坐车的旅客人数，“不小”形容人数多，搭配自然。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身高，汽车站没有身高，句子说不通。"}, {"text": "语法", "is_correct": false, "explanation": "语义：“语法”指语言的组织规则，与汽车站无关，句意不合。"}, {"text": "发音", "is_correct": false, "explanation": "语义：“发音”指说话的声音，汽车站不会发音，句意不合。"}], "explanations": {"客运量": "正确：客运量指坐车的旅客人数，“不小”形容人数多，搭配自然。", "身高": "体貌：“身高”指人的身高，汽车站没有身高，句子说不通。", "语法": "语义：“语法”指语言的组织规则，与汽车站无关，句意不合。", "发音": "语义：“发音”指说话的声音，汽车站不会发音，句意不合。"}, "sentence_index": 0, "correct_answer": "客运量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家港口去年的客运量超过了一亿吨。", "explanation": "这里应该用〈货运量〉。港口的货物吞吐量以吨计，要用货运量；运送旅客的人数才用客运量。"}, {"text": "这家商场周末的客运量最大。", "explanation": "这里应该用〈客流量〉。商场里的人流要用客流量，客运量只指交通运输中运送的旅客。"}, {"text": "晚高峰时，这个路口的客运量每小时都有三千辆。", "explanation": "这里应该用〈车流量〉。客运量指运送旅客的人数，单位时间内经过路口的车辆数要用车流量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客运量", "is_correct": true, "explanation": "正确：客运量指坐车的人数，“夏天比冬天多”描述的正是人数的多少，搭配自然。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指人的身体重量，机场没有体重，句子说不通。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”指受教育的程度，机场没有学历，与季节比较无关。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：机场的年龄不会随季节比较多少，句意不合。"}], "explanations": {"客运量": "正确：客运量指坐车的人数，“夏天比冬天多”描述的正是人数的多少，搭配自然。", "体重": "体貌：“体重”指人的身体重量，机场没有体重，句子说不通。", "学历": "语义：“学历”指受教育的程度，机场没有学历，与季节比较无关。", "年龄": "语义：机场的年龄不会随季节比较多少，句意不合。"}, "sentence_index": 6, "correct_answer": "客运量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这节车厢的客运量最多能容纳一百人。", "explanation": "这里应该用〈载客量〉。客运量指一定时期内运送旅客的总数，一节车厢能坐多少人要用载客量。"}, {"text": "这列火车的客运量达到了百分之九十。", "explanation": "这里应该用〈上座率〉。上座率是座位被占用的比例，用百分数表示；客运量计算的是运送的人数，不用百分比。"}, {"text": "这个景区门口一到节假日，客运量就特别大。", "explanation": "这里应该用〈人流量〉。客运量指运送旅客的人数，景区门口聚集的游客人群要用人流量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年国庆假期，这条地铁线路的客运量达到了两百万个。", "corrected_sentence": "今年国庆假期，这条地铁线路的客运量达到了两百万人次。", "error_description": "“客运量”的计量单位应为“人次”，不能用“个”。“客运量”计算的是运送旅客的人次，所以应说“两百万人次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年底我们吃了机场的客运量。", "corrected_sentence": "年底我们统计了机场的客运量。", "error_description": "动词搭配错误：“客运量”是可以统计的数量，不能用“吃”。应说“统计了机场的客运量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '455a3f7a-9642-49ae-a384-48a0bd5854e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
