INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "脏东西让空气、水和土地变坏了。", "primary_collocate": null, "pronunciation": "huán jìng wū rǎn", "ipa": "xwan˧˥ tɕiŋ˥˩ u˥ ɻan˨˩˦", "syllable_count": 4, "sentences": [{"text": "垃圾太多会造成环境污染。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境污染让河水变臭了。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了减少环境污染，我们坐地铁上班。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的环境污染很严重。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车多了，环境污染也变重了。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，乱扔垃圾会带来环境污染。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境污染使鸟儿越来越少。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在研究怎么治理环境污染。", "target_word": "环境污染", "complexity_tier": "T3", "furigana": "huán jìng wū rǎn", "sentence_source": "generated"}, {"text": "环境污染对我们的身体不好。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近的工厂造成了环境污染。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境污染", "label": "繁体"}], "register": "中性", "sense_fingerprint": "垃圾、废气、废水让空气、水和土地变脏变坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa6fc4b-3b94-4372-8dfa-3cb1d7e50379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境污染", "is_correct": true, "explanation": "正确：「造成」的结果是环境污染，与「垃圾太多」的因果关系相符。"}, {"text": "好运", "is_correct": false, "explanation": "语义：垃圾太多不会带来好运，与前文的因果语境相反。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：垃圾不能造成友谊，「造成友谊」与前文语境不符。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：「造成」后接抽象的结果，「眼睛」是器官，不能说「造成眼睛」。"}], "explanations": {"环境污染": "正确：「造成」的结果是环境污染，与「垃圾太多」的因果关系相符。", "好运": "语义：垃圾太多不会带来好运，与前文的因果语境相反。", "友谊": "语义：垃圾不能造成友谊，「造成友谊」与前文语境不符。", "眼睛": "搭配：「造成」后接抽象的结果，「眼睛」是器官，不能说「造成眼睛」。"}, "sentence_index": 0, "correct_answer": "环境污染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村子开展了环境污染。", "explanation": "这里应该用〈环境治理〉。「开展」的对象是有组织的工作，环境污染是要消除的现象，不能被开展。"}, {"text": "这次活动的目的是环境污染。", "explanation": "这里应该用〈生态保护〉。活动的目的应是积极的目标，环境污染是要消除的问题，不能作为目的。"}, {"text": "我在河边看到一只环境污染。", "explanation": "这里应该用〈种〉。「只」多用于动物和单件物品，环境污染是抽象现象，量词应用「种」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境污染", "is_correct": true, "explanation": "正确：「使鸟儿越来越少」的原因是环境污染，与句意相符。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不会使鸟儿越来越少，与句中的因果语境相反。"}, {"text": "笑容", "is_correct": false, "explanation": "语义：笑容不会影响鸟类数量，「笑容使鸟儿越来越少」不成立。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：「使」后的施事应是能导致变化的事物，「食堂」是场所，不能与「使鸟儿越来越少」搭配。"}], "explanations": {"环境污染": "正确：「使鸟儿越来越少」的原因是环境污染，与句意相符。", "阳光": "语义：阳光不会使鸟儿越来越少，与句中的因果语境相反。", "笑容": "语义：笑容不会影响鸟类数量，「笑容使鸟儿越来越少」不成立。", "食堂": "搭配：「使」后的施事应是能导致变化的事物，「食堂」是场所，不能与「使鸟儿越来越少」搭配。"}, "sentence_index": 6, "correct_answer": "环境污染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片湖正在进行环境污染。", "explanation": "这里应该用〈环境恢复〉。「进行」后接治理、恢复等工作，环境污染是需要消除的现象，不能被进行。"}, {"text": "专家进行了环境污染。", "explanation": "这里应该用〈环境评估〉。「进行」后接评估、检测等工作，环境污染不是可以进行的工作。"}, {"text": "我在新闻里看到一条环境污染。", "explanation": "这里应该用〈种〉。「条」多用于河流、消息、道路等，环境污染是抽象现象，量词应用「种」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市民们一起抗议这家工厂造成地环境污染。", "corrected_sentence": "市民们一起抗议这家工厂造成的环境污染。", "error_description": "定语标记错误：修饰名词「环境污染」的动词性定语后应用「的」，不能用「地」（「地」用于动词前作状语）。正确形式是「造成的环境污染」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子存在一块严重的环境污染。", "corrected_sentence": "这个村子存在一种严重的环境污染。", "error_description": "量词错误：「块」用于有块状形状的具体物体或地块，环境污染是抽象现象，应用「种」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23404, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "残缺", "is_correct": true, "explanation": "“残缺”指不完整，与“全”的“不缺少”相反。"}, {"text": "冷", "is_correct": false, "explanation": "“冷”指温度低，与“全”没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "“高”指位置或程度在上，与“全”没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "“快”指速度大，与“全”没有反义关系。"}], "correct_answer": "残缺", "explanations": {"残缺": "“残缺”指不完整，与“全”的“不缺少”相反。", "冷": "“冷”指温度低，与“全”没有反义关系。", "高": "“高”指位置或程度在上，与“全”没有反义关系。", "快": "“快”指速度大，与“全”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23404, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "残缺", "is_correct": true, "explanation": "“残缺”指不完整，与“全”的“不缺少”相反。"}, {"text": "薄", "is_correct": false, "explanation": "“薄”指厚度小，与“全”没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”指速度低，与“全”没有反义关系。"}, {"text": "远", "is_correct": false, "explanation": "“远”指距离大，与“全”没有反义关系。"}], "correct_answer": "残缺", "explanations": {"残缺": "“残缺”指不完整，与“全”的“不缺少”相反。", "薄": "“薄”指厚度小，与“全”没有反义关系。", "慢": "“慢”指速度低，与“全”没有反义关系。", "远": "“远”指距离大，与“全”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23404, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "全部，一个都不少。", "primary_collocate": null, "pronunciation": "quán", "ipa": "tɕʰɥɛn˧˥", "syllable_count": 1, "sentences": [{"text": "人还没来全，我们再等一会儿。", "target_word": "全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书不全，少了第三本。", "target_word": "全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜都上全了，我们开始吃吧。", "target_word": "全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的衣服很全，什么都有。", "target_word": "全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名单上的名字不全，请再看看。", "target_word": "全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把要带的东西都带全了。", "target_word": "全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表还没填全，老师不收。", "target_word": "全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的水果很全，你想买什么都有。", "target_word": "全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子不全，只有五个。", "target_word": "全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试要带的东西你带全了吗？", "target_word": "全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全部", "label": "复合"}, {"form": "齐全", "label": "复合"}], "register": "中性", "sense_fingerprint": "齐全；不缺少；一个都不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61123057-4989-4a95-82bf-725897152c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23404, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全", "is_correct": true, "explanation": "正确答案“全”quán，意思是全部、一个都不少。"}, {"text": "圈", "is_correct": false, "explanation": "quān（第一声）与 quán（第二声）声调不同，意思是圈子。"}, {"text": "劝", "is_correct": false, "explanation": "quàn（第四声）与 quán（第二声）声调不同，意思是劝说。"}, {"text": "犬", "is_correct": false, "explanation": "quǎn（第三声）与 quán（第二声）声调不同，意思是狗。"}], "explanations": {"全": "正确答案“全”quán，意思是全部、一个都不少。", "圈": "quān（第一声）与 quán（第二声）声调不同，意思是圈子。", "劝": "quàn（第四声）与 quán（第二声）声调不同，意思是劝说。", "犬": "quǎn（第三声）与 quán（第二声）声调不同，意思是狗。"}, "sentence_index": null, "correct_answer": "全"}, "level_3": {"options": [{"text": "全", "is_correct": true, "explanation": "“来全”表示人一个都不少地来了，符合“再等一会儿”的句意。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：“饱”指吃够了，不能作“来”的结果补语。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”不能作“来”的结果补语，句子不通。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”指身体肥，与人有没有到齐无关。"}], "explanations": {"全": "“来全”表示人一个都不少地来了，符合“再等一会儿”的句意。", "饱": "搭配：“饱”指吃够了，不能作“来”的结果补语。", "高": "搭配：“高”不能作“来”的结果补语，句子不通。", "胖": "语义：“胖”指身体肥，与人有没有到齐无关。"}, "sentence_index": 0, "correct_answer": "全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个杯子全了，别再倒了。", "explanation": "这里应该用〈满〉。“全”指一个都不少，说容器装满要用“满”，不能说杯子“全了”。"}, {"text": "这件衣服太全了，我穿不上。", "explanation": "这里应该用〈小〉。“全”指一个都不少，不能形容衣服的大小。"}, {"text": "这条路很全，车开得很快。", "explanation": "这里应该用〈宽〉。“全”指齐全、不缺少，不能形容道路的宽窄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全", "is_correct": true, "explanation": "“全”作结果补语，表示填完整，与“老师不收”的意思吻合。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“远”指距离大，不能作“填”的结果补语，句子不通。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”指温度低，与表格有没有填完整无关。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线明亮，与“表格有没有填完整”无关。"}], "explanations": {"全": "“全”作结果补语，表示填完整，与“老师不收”的意思吻合。", "远": "搭配：“远”指距离大，不能作“填”的结果补语，句子不通。", "冷": "语义：“冷”指温度低，与表格有没有填完整无关。", "亮": "语义：“亮”指光线明亮，与“表格有没有填完整”无关。"}, "sentence_index": 6, "correct_answer": "全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的手机存储全了，拍不了照。", "explanation": "这里应该用〈满〉。“存储满”指空间装满，“全”指齐全、无遗漏，不能说存储“全了”。"}, {"text": "体育馆全了，观众都进不去了。", "explanation": "这里应该用〈满〉。场所装满、坐满要用“满”，“全”指齐全、无遗漏，不能说场所“全了”。"}, {"text": "我们全个人都报名了。", "explanation": "这里应该用〈每个人〉。“全”后面不能直接接量词“个”，要说“每个人”或“所有人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套书全不，少了一本。", "corrected_sentence": "这套书不全，少了一本。", "error_description": "否定词“不”要放在“全”前面，应说“不全”，不说“全不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们全的来了。", "corrected_sentence": "我们全来了。", "error_description": "副词“全”修饰动词时不能加“的”，应说“全来了”，不说“全的来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
