INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23406, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示更加，意思更深。", "primary_collocate": null, "pronunciation": "gèng wéi", "ipa": "kɤŋ˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "健康比金钱更为重要。", "target_word": "更为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法更为简单。", "target_word": "更为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年冬天比去年更为寒冷。", "target_word": "更为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对学生来说，习惯更为重要。", "target_word": "更为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上购物比去商店更为方便。", "target_word": "更为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第二个问题比第一个更为复杂。", "target_word": "更为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新方法比旧方法更为有效。", "target_word": "更为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与大城市相比，小城市的生活更为安静。", "target_word": "更为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的服务比那家更为周到。", "target_word": "更为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大以后，学习变得更为紧张。", "target_word": "更为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "更为：比较之下程度更深，常用于书面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同进行，不能修饰“重要”这类性质，说“比金钱一起重要”不通。"}, {"text": "更为", "is_correct": true, "explanation": "正确：“更为”表示程度更深，可以用在“比”字比较句中。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示动作进行中，不能修饰“重要”这类性质，句中没有进行的语境。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”表示限定，不能与“比……”的程度比较搭配。"}], "explanations": {"一起": "语义：“一起”表示共同进行，不能修饰“重要”这类性质，说“比金钱一起重要”不通。", "更为": "正确：“更为”表示程度更深，可以用在“比”字比较句中。", "正在": "语义：“正在”表示动作进行中，不能修饰“重要”这类性质，句中没有进行的语境。", "只": "搭配：“只”表示限定，不能与“比……”的程度比较搭配。"}, "sentence_index": 0, "correct_answer": "更为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个答案更为唯一。", "explanation": "这里不能用〈更为〉。“更为”表示程度加深，需要能够比较程度的形容词；“唯一”表示只有一个，没有程度之分，不能说“更为唯一”。"}, {"text": "这两个数更为质数。", "explanation": "这里不能用〈更为〉。“质数”是数的类别，没有程度深浅，与“更为”表示程度加深的意思不相容。"}, {"text": "这两件事更为同一。", "explanation": "这里不能用〈更为〉。“同一”表示完全相同，没有程度深浅，与“更为”表示程度加深的意思相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更为", "is_correct": true, "explanation": "正确：“更为”表示程度更深，与“比”引出的对象搭配，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“比……很……”不是合法的比较句格式，“很”不能与“比”搭配。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“比……最……”不能构成比较句，与“比”的比较结构相冲突。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同进行，不能修饰比较句中的程度，句意不通。"}], "explanations": {"更为": "正确：“更为”表示程度更深，与“比”引出的对象搭配，符合句意。", "很": "搭配：“比……很……”不是合法的比较句格式，“很”不能与“比”搭配。", "最": "搭配：“比……最……”不能构成比较句，与“比”的比较结构相冲突。", "一起": "语义：“一起”表示共同进行，不能修饰比较句中的程度，句意不通。"}, "sentence_index": 6, "correct_answer": "更为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的人数更为相同。", "explanation": "“更为”表示程度加深，“相同”表示完全没有差别、没有程度深浅，二者不能搭配，这里应去掉“更为”。"}, {"text": "这个数字更为偶数。", "explanation": "这里不能用〈更为〉。“偶数”是数的类别，没有程度深浅，“更为”表示程度加深，二者不能搭配。"}, {"text": "这件事昨天更为发生了。", "explanation": "这里不能用〈更为〉。“更为”表示程度加深，要修饰能分程度的形容词或心理动词，“发生”是事件动词，没有程度深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法更为很有效。", "corrected_sentence": "这个方法更为有效。", "error_description": "程度副词重复。“更为”已经表示程度加深，前面不能再加“很”，应说“更为有效”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作更为的轻松。", "corrected_sentence": "这份工作更为轻松。", "error_description": "“更为”后面不能直接加“的”来修饰形容词，应去掉“的”，说“更为轻松”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
