INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23408, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "算一算钱或东西有多少。", "primary_collocate": null, "pronunciation": "hé suàn", "ipa": "xɤ˧˥ suan˥˩", "syllable_count": 2, "sentences": [{"text": "月底我要核算一下这个月花了多少钱。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请同学们核算一下班费一共花了多少钱。", "target_word": "核算", "complexity_tier": "T3", "furigana": "lǎoshī qǐng tóngxuémen hésuàn yíxià bānfèi yígòng huāle duōshao qián", "sentence_source": "generated"}, {"text": "商店老板每天晚上核算当天的收入。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在核算今年家里的开支。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发以前，我们先核算一下这次野餐要花多少钱。", "target_word": "核算", "complexity_tier": "T3", "furigana": "chūfā yǐqián wǒmen xiān hésuàn yíxià zhè cì yěcān yào huā duōshao qián", "sentence_source": "generated"}, {"text": "他把所有成本核算了一遍，一共两万元。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司核算了一下，这次活动要花五千元。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂每个月都要核算原材料的成本。", "target_word": "核算", "complexity_tier": "T3", "furigana": "gōngchǎng měi gè yuè dōu yào hésuàn yuáncáiliào de chéngběn", "sentence_source": "generated"}, {"text": "你能帮我核算一下旅行的费用吗？", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "核算以后，我们发现钱不够用。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "核算了", "label": "体标"}, {"form": "核算过", "label": "体标"}, {"form": "成本核算", "label": "复合"}, {"form": "核算员", "label": "复合"}], "register": "中性", "sense_fingerprint": "算出钱或东西的数量、花费", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3430cc5-80a4-4de2-a1d0-e0c20ca887f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "核算", "is_correct": true, "explanation": "正确：“核算一下”指算一算这个月花了多少钱。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶指操纵车辆，与算钱无关，“驾驶一下这个月花了多少钱”说不通。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”的对象是景点，不能带“花了多少钱”这样的宾语。"}, {"text": "同意", "is_correct": false, "explanation": "配价：“同意”要求的是事项或意见，不能这样直接接一个数量小句。"}], "explanations": {"核算": "正确：“核算一下”指算一算这个月花了多少钱。", "驾驶": "语义：驾驶指操纵车辆，与算钱无关，“驾驶一下这个月花了多少钱”说不通。", "游览": "搭配：“游览”的对象是景点，不能带“花了多少钱”这样的宾语。", "同意": "配价：“同意”要求的是事项或意见，不能这样直接接一个数量小句。"}, "sentence_index": 0, "correct_answer": "核算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我正在核算圆的面积。", "explanation": "这里应该用〈计算〉。核算用于钱款和账目，求圆的面积要用“计算”。"}, {"text": "他一直在核算自己的身高。", "explanation": "这里应该用〈测量〉。核算只用于钱款、账目等的计算核对，量身高要用“测量”。"}, {"text": "小孩正在核算一首歌。", "explanation": "这里应该用〈唱〉。核算与金钱、账目有关，唱歌要用“唱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "核算", "is_correct": true, "explanation": "正确：“核算”指算出钱或东西的数量，与“这次活动要花五千元”相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是步行活动，与算钱无关。"}, {"text": "赠送", "is_correct": false, "explanation": "配价：“赠送”需要接受者和所赠之物两个成分，句中缺少接受者。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或卫生，不能用来算费用。"}], "explanations": {"核算": "正确：“核算”指算出钱或东西的数量，与“这次活动要花五千元”相符。", "散步": "语义：散步是步行活动，与算钱无关。", "赠送": "配价：“赠送”需要接受者和所赠之物两个成分，句中缺少接受者。", "打扫": "搭配：“打扫”的对象是场所或卫生，不能用来算费用。"}, "sentence_index": 6, "correct_answer": "核算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这篇文章核算成英文。", "explanation": "这里应该用〈翻译〉。核算是计算钱款或数目，把文章译成另一种语言要用“翻译”。"}, {"text": "工人核算了一座桥。", "explanation": "这里应该用〈修建〉。核算用于数目和钱款，建造桥梁要用“修建”。"}, {"text": "设计师核算了一座新房子。", "explanation": "这里应该用〈设计〉。核算指计算数目或钱款，规划房子的样式要用“设计”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几天他一直在核算了工程的成本。", "corrected_sentence": "这几天他一直在核算工程的成本。", "error_description": "错误形式：“在核算了”；正确形式：“在核算”。“在”表示动作正在进行，与表示完成的“了”不能同时用在同一个动词上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不核算过这次旅行的费用。", "corrected_sentence": "我没核算过这次旅行的费用。", "error_description": "错误形式：“不核算过”；正确形式：“没核算过”。表示没有过某种经历，要用“没（有）”，不能用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
