INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23410, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "路上跑的、有轮子的交通工具，可以坐人或拉东西。", "primary_collocate": null, "pronunciation": "chē liàng", "ipa": "ʈʂʰɤ˥ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "路上的车辆很多，我们走得很慢。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯亮了，所有车辆都停了下来。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种车辆可以坐二十个人。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着路上来来往往的车辆。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路时要小心车辆。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些车辆是用来拉货的。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪以后，车辆开得很慢。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司新买了一批车辆，用来送货。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上街上的车辆比白天少。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车辆太多，我们坐地铁去吧。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批车辆", "label": "量词"}, {"form": "机动车辆", "label": "复合"}, {"form": "非机动车辆", "label": "复合"}], "register": "中性", "sense_fingerprint": "路上跑的、能载人或拉货的车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3430cc5-80a4-4de2-a1d0-e0c20ca887f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "车门", "is_correct": false, "explanation": "语义：车门是车的一部分，路上不会有很多车门，与“路上的……很多”不符。"}, {"text": "车驾", "is_correct": false, "explanation": "语域：“车驾”是书面敬称，专指帝王或贵人的车，不能用于一般的车。"}, {"text": "车辆", "is_correct": true, "explanation": "正确：车辆指路上跑的车，“路上的车辆很多”自然，“我们走得很慢”也由车多引起。"}, {"text": "车厢", "is_correct": false, "explanation": "语义：车厢是列车的一部分，不能说路上很多车厢。"}], "explanations": {"车门": "语义：车门是车的一部分，路上不会有很多车门，与“路上的……很多”不符。", "车驾": "语域：“车驾”是书面敬称，专指帝王或贵人的车，不能用于一般的车。", "车辆": "正确：车辆指路上跑的车，“路上的车辆很多”自然，“我们走得很慢”也由车多引起。", "车厢": "语义：车厢是列车的一部分，不能说路上很多车厢。"}, "sentence_index": 0, "correct_answer": "车辆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把车辆放进了口袋里。", "explanation": "这里应该用〈钥匙〉。车辆是很大的交通工具，不能放进口袋；能放进口袋的是钥匙这类小东西。"}, {"text": "他骑着车辆在路上来来往往。", "explanation": "这里应该用〈自行车〉。车辆是统称，“骑”要搭配具体的车，不能说“骑车辆”。"}, {"text": "车辆上同学们在跑步。", "explanation": "这里应该用〈操场〉。车辆是交通工具，不能当作跑步的场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人群", "is_correct": false, "explanation": "搭配：“开”的对象是车辆，人群不能“开”，“开得很慢”说不通。"}, {"text": "车辆", "is_correct": true, "explanation": "正确：车辆可以“开”，与“下雪以后，……开得很慢”搭配。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：雪花不能被开，句子说的是有人驾驶的东西慢慢开。"}, {"text": "行人", "is_correct": false, "explanation": "搭配：行人不能“开”，“开得很慢”要求驾驶的东西。"}], "explanations": {"人群": "搭配：“开”的对象是车辆，人群不能“开”，“开得很慢”说不通。", "车辆": "正确：车辆可以“开”，与“下雪以后，……开得很慢”搭配。", "雪花": "语义：雪花不能被开，句子说的是有人驾驶的东西慢慢开。", "行人": "搭配：行人不能“开”，“开得很慢”要求驾驶的东西。"}, "sentence_index": 6, "correct_answer": "车辆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天给车辆让座。", "explanation": "这里应该用〈老人〉。让座的对象必须是人，车辆不能接受让座。"}, {"text": "车辆在天上飞来飞去。", "explanation": "这里应该用〈飞机〉。车辆是在路上跑的交通工具，在天上飞的要说飞机。"}, {"text": "我买了一张车辆。", "explanation": "这里应该用〈车票〉。“张”用于纸片类东西，车辆是交通工具，不能用“张”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "广场上停着一个车辆。", "corrected_sentence": "广场上停着一批车辆。", "error_description": "错误：“一个车辆”，应为“一批车辆”。“车辆”是统称，计量一批用“批”；不能用“个”，也不能用单台的“辆”（说“一辆车辆”同样重复）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条街上停着一辆车辆。", "corrected_sentence": "这条街上停着一批车辆。", "error_description": "错误：“一辆车辆”重复计量，应为“一批车辆”。“车辆”是统称，不能再加单台的量词“辆”；集合计量用“批”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
