INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23412, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把数字或东西记到总数里。", "primary_collocate": null, "pronunciation": "jì rù", "ipa": "tɕi˥˩ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "请把这个数字计入总数。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的三分也计入了全队的分数。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打折的东西不计入这次的总价。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把新来的学生计入了班级人数。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书也要计入图书馆的总数里。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有来，所以不计入参加的人数。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的钱都计入了这个月的总数。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的数据也计入了这周的总数。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "送你的礼物不用计入花费。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天卖的水果全部计入了总数。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "计入了", "label": "体标"}, {"form": "计入过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把数字或东西算进总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3430cc5-80a4-4de2-a1d0-e0c20ca887f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23412, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "计入", "is_correct": true, "explanation": "计入（jì rù）：把数字或东西记到总数里。"}, {"text": "记录", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），意思是把事情写下来。"}, {"text": "挤入", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是挤进去。"}, {"text": "进入", "is_correct": false, "explanation": "jìn 比 jì 多一个韵尾 n，意思是走进某个地方。"}, {"text": "置入", "is_correct": false, "explanation": "zhì 与 jì 声母不同（zh 与 j），意思是放置进去。"}], "explanations": {"计入": "计入（jì rù）：把数字或东西记到总数里。", "记录": "lù 与 rù 声母不同（l 与 r），意思是把事情写下来。", "挤入": "jǐ（第三声）与 jì（第四声）声调不同，意思是挤进去。", "进入": "jìn 比 jì 多一个韵尾 n，意思是走进某个地方。", "置入": "zhì 与 jì 声母不同（zh 与 j），意思是放置进去。"}, "sentence_index": null, "correct_answer": "计入"}, "level_3": {"options": [{"text": "计入", "is_correct": true, "explanation": "正确：“计入总数”指把这个数字算进总数，与句意相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪指做饭，与把数字算进总数无关。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”的对象是景点，不能用来表示把数字算进总数。"}, {"text": "同意", "is_correct": false, "explanation": "配价：“同意”要求的是意见或事项，不能直接带“总数”这类宾语。"}], "explanations": {"计入": "正确：“计入总数”指把这个数字算进总数，与句意相符。", "烹饪": "语义：烹饪指做饭，与把数字算进总数无关。", "游览": "搭配：“游览”的对象是景点，不能用来表示把数字算进总数。", "同意": "配价：“同意”要求的是意见或事项，不能直接带“总数”这类宾语。"}, "sentence_index": 0, "correct_answer": "计入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他计入了山顶。", "explanation": "这里应该用〈登上〉。计入指把数目记进总数，到达山顶要用“登上”。"}, {"text": "他把书计入了箱子里。", "explanation": "这里应该用〈装进〉。计入表示记进总数，把书放进箱子要用“装进”。"}, {"text": "他计入了房间的门。", "explanation": "这里应该用〈关〉。计入不能用于门，关门要用“关”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "计入", "is_correct": true, "explanation": "正确：“计入总数”指把每个人的钱算进这个月的总数。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶指操纵车辆，与把钱算进总数无关。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或卫生，不能与“总数”搭配。"}, {"text": "赠送", "is_correct": false, "explanation": "配价：“赠送”需要接受者和所赠之物，句中缺少接受者。"}], "explanations": {"计入": "正确：“计入总数”指把每个人的钱算进这个月的总数。", "驾驶": "语义：驾驶指操纵车辆，与把钱算进总数无关。", "打扫": "搭配：“打扫”的对象是场所或卫生，不能与“总数”搭配。", "赠送": "配价：“赠送”需要接受者和所赠之物，句中缺少接受者。"}, "sentence_index": 6, "correct_answer": "计入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们计入了这篇文章。", "explanation": "这里应该用〈读〉。计入指把数目记进总数，阅读文章要用“读”。"}, {"text": "他计入了这座城市。", "explanation": "这里应该用〈进入〉。计入指把数目算进总数，走进一座城市要用“进入”。"}, {"text": "老师计入了这篇课文。", "explanation": "这里应该用〈讲〉。计入不表示讲授，给学生讲课文要用“讲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些钱我从来没计入了总账。", "corrected_sentence": "这些钱我从来没计入过总账。", "error_description": "错误形式：“从来没计入了”；正确形式：“从来没计入过”。表示从未有过的经历要用“过”，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把这些奖金计入着今年的收入。", "corrected_sentence": "我们把这些奖金计入了今年的收入。", "error_description": "错误形式：“计入着”；正确形式：“计入了”。“计入”是瞬时完成的动作，表示完成要用“了”，“着”表示持续状态，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
