INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大家生活需要的公共设施，比如道路、桥梁、水电。", "primary_collocate": null, "pronunciation": "jī chǔ shè shī", "ipa": "tɕi˥ ʈʂʰu˨˩˦ ʂɤ˥˩ ʂʅ˥", "syllable_count": 4, "sentences": [{"text": "这个城市的基础设施很好。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的基础设施还不够完善。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在建设新的基础设施。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路和桥都是重要的基础设施。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村要多花钱建设基础设施。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的基础设施老了，路也不好走。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了好的基础设施，人们生活更方便。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水、电和网络都是基础设施。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校附近的基础设施越来越多。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为小镇修建了基础设施。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基礎設施", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大家生活需要的公共设施，如道路、桥梁、水电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '810ac7fa-1260-4d9e-be13-37017ce45fe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基础设施", "is_correct": true, "explanation": "正确：「基础设施」指道路、水电等大家共用的设施，可以作为城市的特点来评价，符合「很好」。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：「噪音」不能用「很好」来评价，「这个城市的噪音很好」语义不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：「垃圾」是需要清理的东西，不能说城市的垃圾「很好」。"}, {"text": "疾病", "is_correct": false, "explanation": "搭配：「很好」用于评价状态或质量，不与「疾病」搭配。"}], "explanations": {"基础设施": "正确：「基础设施」指道路、水电等大家共用的设施，可以作为城市的特点来评价，符合「很好」。", "噪音": "语义：「噪音」不能用「很好」来评价，「这个城市的噪音很好」语义不通。", "垃圾": "语义：「垃圾」是需要清理的东西，不能说城市的垃圾「很好」。", "疾病": "搭配：「很好」用于评价状态或质量，不与「疾病」搭配。"}, "sentence_index": 0, "correct_answer": "基础设施"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂今年买了很多新的基础设施，用来生产汽车。", "explanation": "这里应该用〈设备〉。「基础设施」指道路、桥梁、水电等大家共用的公共设施，工厂的生产机器属于设备，不能说成基础设施。"}, {"text": "这篇文章的基础设施很清楚，读起来很容易。", "explanation": "这里应该用〈结构〉。「基础设施」指道路、水电等大家共用的公共设施，文章的组织框架要说「结构」。"}, {"text": "运动员们用的基础设施都很新。", "explanation": "这里应该用〈器材〉。运动员用的是体育器材，「基础设施」指公共设施，不指运动用的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基础设施", "is_correct": true, "explanation": "正确：「好的基础设施」能让人们的生活更方便，与后句的「生活更方便」因果一致。"}, {"text": "肥料", "is_correct": false, "explanation": "语义：「肥料」是给庄稼用的，与「人们生活更方便」没有关系。"}, {"text": "烟雾", "is_correct": false, "explanation": "语义：「烟雾」会让生活变差，与「生活更方便」的结果矛盾。"}, {"text": "化石", "is_correct": false, "explanation": "搭配：「好的化石」不是常见说法，且「化石」与便利的生活无关。"}], "explanations": {"基础设施": "正确：「好的基础设施」能让人们的生活更方便，与后句的「生活更方便」因果一致。", "肥料": "语义：「肥料」是给庄稼用的，与「人们生活更方便」没有关系。", "烟雾": "语义：「烟雾」会让生活变差，与「生活更方便」的结果矛盾。", "化石": "搭配：「好的化石」不是常见说法，且「化石」与便利的生活无关。"}, "sentence_index": 6, "correct_answer": "基础设施"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵们背着新的基础设施去训练。", "explanation": "这里应该用〈装备〉。士兵背的是个人装备，「基础设施」是大家共用的公共设施，不能背在身上。"}, {"text": "他的基础设施很好，一学就会。", "explanation": "这里应该用〈功底〉。「基础设施」指道路、水电等大家共用的公共设施，说个人的学习水平要用「功底」，不能说「基础设施」。"}, {"text": "客厅里摆着新买的基础设施，很漂亮。", "explanation": "这里应该用〈家具〉。「基础设施」指道路、水电等公共设施，不指客厅里的家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一把基础设施是去年建成的。", "corrected_sentence": "这一套基础设施是去年建成的。", "error_description": "量词错误：「基础设施」应与「套」搭配，说「这一套基础设施」，不能用「把」（「把」用于有柄的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条基础设施已经用了十年。", "corrected_sentence": "这套基础设施已经用了十年。", "error_description": "量词错误：「基础设施」应用「套」计量，「条」用于细长的事物，不能修饰「基础设施」，应说「这套基础设施」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23416, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破坏", "is_correct": true, "explanation": "反义：“破坏”指使东西受损、不再完好，与“维护”（保持良好）相对。"}, {"text": "制造", "is_correct": false, "explanation": "无关：“制造”指做出东西，与“维护”没有反义关系。"}, {"text": "设计", "is_correct": false, "explanation": "无关：“设计”指事先规划图样，与“维护”的反义无关。"}, {"text": "欣赏", "is_correct": false, "explanation": "无关：“欣赏”指觉得美好而加以赞赏，与“维护”没有反义关系。"}], "correct_answer": "破坏", "explanations": {"破坏": "反义：“破坏”指使东西受损、不再完好，与“维护”（保持良好）相对。", "制造": "无关：“制造”指做出东西，与“维护”没有反义关系。", "设计": "无关：“设计”指事先规划图样，与“维护”的反义无关。", "欣赏": "无关：“欣赏”指觉得美好而加以赞赏，与“维护”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23416, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破坏", "is_correct": true, "explanation": "反义：“破坏”指使东西受损、不再完好，与“维护”相对。"}, {"text": "观察", "is_correct": false, "explanation": "无关：“观察”指仔细看，与“维护”没有反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "无关：“收藏”指保存珍贵的东西，与“维护”没有反义关系。"}, {"text": "打扮", "is_correct": false, "explanation": "无关：“打扮”指修饰外表，与“维护”没有反义关系。"}], "correct_answer": "破坏", "explanations": {"破坏": "反义：“破坏”指使东西受损、不再完好，与“维护”相对。", "观察": "无关：“观察”指仔细看，与“维护”没有反义关系。", "收藏": "无关：“收藏”指保存珍贵的东西，与“维护”没有反义关系。", "打扮": "无关：“打扮”指修饰外表，与“维护”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23416, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西保持好的样子，不坏掉。", "primary_collocate": null, "pronunciation": "wéi hù", "ipa": "weɪ˧˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "工人每天都在维护这台机器。", "target_word": "维护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们定期维护学校的网站。", "target_word": "维护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要好好维护公园里的设施。", "target_word": "维护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车需要经常维护。", "target_word": "维护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校定期维护教室里的空调。", "target_word": "维护", "complexity_tier": "T3", "furigana": "xuéxiào dìngqī wéihù jiàoshì lǐ de kōngtiáo.", "sentence_source": "generated"}, {"text": "爸爸每个月都会维护一次电脑。", "target_word": "维护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅正在维护路灯。", "target_word": "维护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥已经很久没有人维护了。", "target_word": "维护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好好维护，自行车可以用很多年。", "target_word": "维护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天花一小时维护花园。", "target_word": "维护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "维护了", "label": "体标"}, {"form": "维护着", "label": "体标"}, {"form": "维护过", "label": "体标"}, {"form": "維護", "label": "繁体"}], "register": "中性", "sense_fingerprint": "检查修理设备、设施，使其保持良好状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23416, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "维护", "is_correct": true, "explanation": "正确答案。“维护”读 wéi hù，指让东西保持良好的样子，不坏掉。"}, {"text": "维度", "is_correct": false, "explanation": "dù（第四声）与 hù（第四声）只差声母 h 和 d，“维度”指事物的方面或量度。"}, {"text": "帷幕", "is_correct": false, "explanation": "mù（第四声）与 hù（第四声）只差声母 m 和 h，“帷幕”指遮挡用的布幕。"}, {"text": "围湖", "is_correct": false, "explanation": "hú（第二声）与 hù（第四声）声调不同，“围湖”指用堤坝圈起湖面。"}], "explanations": {"维护": "正确答案。“维护”读 wéi hù，指让东西保持良好的样子，不坏掉。", "维度": "dù（第四声）与 hù（第四声）只差声母 h 和 d，“维度”指事物的方面或量度。", "帷幕": "mù（第四声）与 hù（第四声）只差声母 m 和 h，“帷幕”指遮挡用的布幕。", "围湖": "hú（第二声）与 hù（第四声）声调不同，“围湖”指用堤坝圈起湖面。"}, "sentence_index": null, "correct_answer": "维护"}, "level_3": {"options": [{"text": "维护", "is_correct": true, "explanation": "正确：“维护”指保养，使机器保持良好状态，与“每天都在”的日常保养相符。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”指窃取别人的东西，与“工人每天都在……这台机器”的正常工作语境冲突。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”指买下某物，同一台机器不会每天都在被购买。"}, {"text": "吃", "is_correct": false, "explanation": "语义：机器不能被吃，“吃”的对象应当是食物。"}], "explanations": {"维护": "正确：“维护”指保养，使机器保持良好状态，与“每天都在”的日常保养相符。", "偷": "语义：“偷”指窃取别人的东西，与“工人每天都在……这台机器”的正常工作语境冲突。", "购买": "搭配：“购买”指买下某物，同一台机器不会每天都在被购买。", "吃": "语义：机器不能被吃，“吃”的对象应当是食物。"}, "sentence_index": 0, "correct_answer": "维护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上都维护一首新歌。", "explanation": "这里应该用〈创作〉。维护指保持事物完好，不指写作或谱曲。"}, {"text": "他用剪刀把纸维护成了一只小鸟。", "explanation": "这里应该用〈剪〉。维护指保持事物完好，不指剪裁。"}, {"text": "医生正在维护断掉的腿。", "explanation": "这里应该用〈治疗〉。维护指保持物品的良好状态，不用来指治疗人的伤病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "维护", "is_correct": true, "explanation": "正确：“维护”指保养路灯，使其保持正常工作，与“师傅正在”相符。"}, {"text": "喂", "is_correct": false, "explanation": "语义：路灯不能被喂，“喂”的对象应是人或动物。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”的对象是可以被咬的东西，路灯不能被咬。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”后面接的通常是歌曲，“唱路灯”说法不通。"}], "explanations": {"维护": "正确：“维护”指保养路灯，使其保持正常工作，与“师傅正在”相符。", "喂": "语义：路灯不能被喂，“喂”的对象应是人或动物。", "咬": "语义：“咬”的对象是可以被咬的东西，路灯不能被咬。", "唱": "搭配：“唱”后面接的通常是歌曲，“唱路灯”说法不通。"}, "sentence_index": 6, "correct_answer": "维护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里维护了一桌丰盛的晚饭。", "explanation": "这里应该用〈准备〉。维护指保持事物良好状态，不指备办、制作饭菜。"}, {"text": "他维护了一封长信，寄给了老朋友。", "explanation": "这里应该用〈写〉。维护指保持事物完好，不指写作，写信要用〈写〉。"}, {"text": "老师在黑板上维护了一幅地图。", "explanation": "这里应该用〈画〉。维护指保持事物完好，不指画图，画地图要用〈画〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把房子维护很好。", "corrected_sentence": "他把房子维护得很好。", "error_description": "错误在于补语前漏了结构助词“得”。“维护”后接补语“很好”时要说“维护得很好”，不能说“维护很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "师傅把路灯维护。", "corrected_sentence": "师傅把路灯维护好了。", "error_description": "“把”字句中动词“维护”后不能只用一个光杆动词，要补上结果成分并加“了”，应说“把路灯维护好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
