INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "直升机缓缓攀升在山顶上空。", "corrected_sentence": "直升机缓缓攀升到山顶上空。", "error_description": "错误形式“攀升在山顶上空”：表示向高处到达某处时，“攀升”后要用“到”引出到达的位置，应说“攀升到山顶上空”，“在”不能这样用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b01896c-1d35-4e53-8e4f-ce9653cbeb59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
