INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23436, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西研制或做出来。", "primary_collocate": null, "pronunciation": "kāi fā", "ipa": "kʰai˥ fa˥", "syllable_count": 2, "sentences": [{"text": "小明想开发一个新的小游戏。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈开发出了一道新菜。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们开发了一种新玩法。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店开发了三种新口味的茶。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自己开发了一个学习网站。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班开发了一个有趣的小程序。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己开发的小游戏给朋友玩。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起开发出了一个小机器人。", "target_word": "开发", "complexity_tier": "T3", "furigana": "dà jiā yì qǐ kāi fā chū le yí gè xiǎo jī qì rén", "sentence_source": "generated"}, {"text": "爸爸正在开发一个记账的软件。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具是工厂新开发的。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开发了", "label": "体标"}, {"form": "开发过", "label": "体标"}, {"form": "开发着", "label": "体标"}, {"form": "开发者", "label": "复合"}, {"form": "開發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开发：把东西做出来（简单义，新玩法、新口味、小程序）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b809308f-d846-4c23-9255-519bc2949b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23436, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确答案：开发（kāi fā），指把东西做出来。"}, {"text": "开放", "is_correct": false, "explanation": "fàng 与 fā 韵母不同（fàng 带 -ng），声调也不同，意思是开放。"}, {"text": "开方", "is_correct": false, "explanation": "fāng 与 fā 只多了韵尾 -ng，声调相同，意思是开方（数学运算）。"}, {"text": "开花", "is_correct": false, "explanation": "huā 与 fā 声母不同（h 与 f），声调相同，意思是开花。"}, {"text": "开饭", "is_correct": false, "explanation": "fàn 与 fā 韵尾不同（-n）且声调不同，意思是开饭、开始吃饭。"}], "explanations": {"开发": "正确答案：开发（kāi fā），指把东西做出来。", "开放": "fàng 与 fā 韵母不同（fàng 带 -ng），声调也不同，意思是开放。", "开方": "fāng 与 fā 只多了韵尾 -ng，声调相同，意思是开方（数学运算）。", "开花": "huā 与 fā 声母不同（h 与 f），声调相同，意思是开花。", "开饭": "fàn 与 fā 韵尾不同（-n）且声调不同，意思是开饭、开始吃饭。"}, "sentence_index": null, "correct_answer": "开发"}, "level_3": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确：“开发”指做出新游戏，与“小游戏”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能说吃一个游戏。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”用于植物，不能说种游戏。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，不能带“游戏”作宾语。"}], "explanations": {"开发": "正确：“开发”指做出新游戏，与“小游戏”搭配，符合句意。", "吃": "语义：“吃”指进食，不能说吃一个游戏。", "种": "搭配：“种”用于植物，不能说种游戏。", "咳嗽": "配价：“咳嗽”是不及物动词，不能带“游戏”作宾语。"}, "sentence_index": 0, "correct_answer": "开发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷开发了一个有趣的故事。", "explanation": "这里应该用〈讲〉。开发指做出或研制新东西，不说开发故事，讲故事要用讲。"}, {"text": "妹妹开发了一幅漂亮的画。", "explanation": "这里应该用〈画〉。开发不用于绘画，画画要用画。"}, {"text": "她开发了一首好听的歌。", "explanation": "这里应该用〈唱〉。开发不用于唱歌，唱歌要用唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b01896c-1d35-4e53-8e4f-ce9653cbeb59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确：“开发的小游戏”指自己做出的小游戏，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，不能用来修饰做出的游戏。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”用于动物，不能说饲养小游戏。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”指流泪，与做游戏毫无关系。"}], "explanations": {"开发": "正确：“开发的小游戏”指自己做出的小游戏，与句意相符。", "唱": "语义：“唱”指发出歌声，不能用来修饰做出的游戏。", "饲养": "搭配：“饲养”用于动物，不能说饲养小游戏。", "哭": "语义：“哭”指流泪，与做游戏毫无关系。"}, "sentence_index": 6, "correct_answer": "开发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开发了一次愉快的旅行。", "explanation": "这里应该用〈进行〉。开发指做出或研制新东西，旅行要用进行。"}, {"text": "姐姐开发了一封温暖的信。", "explanation": "这里应该用〈写〉。开发指做出或研制新东西，写信要用写。"}, {"text": "我们开发了一场精彩的比赛。", "explanation": "这里应该用〈举办〉。开发指做出新东西，比赛要用举办。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b01896c-1d35-4e53-8e4f-ce9653cbeb59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹想开发过一个会唱歌的小机器人。", "corrected_sentence": "妹妹想开发一个会唱歌的小机器人。", "error_description": "错误：“想”表示打算，动作尚未发生，不能用表示经历的“过”。应删去“开发”后的“过”，说“妹妹想开发一个会唱歌的小机器人。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b01896c-1d35-4e53-8e4f-ce9653cbeb59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把这个小游戏开发出了来。", "corrected_sentence": "我们把这个小游戏开发出来了。", "error_description": "错误：“出来”是趋向补语，“了”应放在“出来”之后，应说“开发出来了”，不能说“开发出了来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b01896c-1d35-4e53-8e4f-ce9653cbeb59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变冷", "is_correct": true, "explanation": "「变冷」指天气转凉，与「变暖」构成反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "「出发」与「变暖」没有反义关系，不是答案。"}, {"text": "唱歌", "is_correct": false, "explanation": "「唱歌」与「变暖」没有反义关系，不是答案。"}, {"text": "写字", "is_correct": false, "explanation": "「写字」与「变暖」没有反义关系，不是答案。"}], "correct_answer": "变冷", "explanations": {"变冷": "「变冷」指天气转凉，与「变暖」构成反义关系。", "出发": "「出发」与「变暖」没有反义关系，不是答案。", "唱歌": "「唱歌」与「变暖」没有反义关系，不是答案。", "写字": "「写字」与「变暖」没有反义关系，不是答案。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
