INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "天气由冷变得暖和了。", "primary_collocate": null, "pronunciation": "biàn nuǎn", "ipa": "pjɛn˥˩ nwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "三月以后，天气慢慢变暖了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天变暖了，我们可以去公园玩。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，天气开始变暖。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变暖，我就不穿厚衣服了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了今天，天气会变暖一点儿。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气一变暖，花就开了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个星期天气会变暖。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变暖了，河里的冰也化了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等天变暖，我们去爬山。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天天气变暖，街上的人多了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "變暖", "label": "繁体"}, {"form": "变暖了", "label": "体标"}], "register": "口语", "sense_fingerprint": "变暖|天气由冷变得暖和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f80f0202-2691-4b52-babe-45032a6cb8ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变暖", "is_correct": true, "explanation": "「变暖」指天气由冷转暖，与「三月以后」的春天语境相符。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：「融化」多说冰雪，不说天气融化。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：「结冰」指水变成冰，与三月转暖的语境不合。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：「发芽」是植物的生长动作，不能用来描述天气。"}], "explanations": {"变暖": "「变暖」指天气由冷转暖，与「三月以后」的春天语境相符。", "融化": "搭配：「融化」多说冰雪，不说天气融化。", "结冰": "语义：「结冰」指水变成冰，与三月转暖的语境不合。", "发芽": "语义：「发芽」是植物的生长动作，不能用来描述天气。"}, "sentence_index": 0, "correct_answer": "变暖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书包里的书变暖了。", "explanation": "这里应该用〈减少〉。「变暖」只用于天气或温度，书的数量变化要用〈减少〉。"}, {"text": "今天的物价变暖了。", "explanation": "这里应该用〈降低〉。「变暖」说气温上升，物价的下降要用〈降低〉。"}, {"text": "这个城市的人口变暖得很快。", "explanation": "这里应该用〈增长〉。「变暖」只用于温度，人口的变化要用〈增长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生锈", "is_correct": false, "explanation": "搭配：「生锈」用于金属，不说天气生锈。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：「点燃」指使东西着火，天气不能被点燃。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」是人的行为，天气不会结婚。"}, {"text": "变暖", "is_correct": true, "explanation": "「变暖」指天气转暖，符合「下个星期」的时间语境。"}], "explanations": {"生锈": "搭配：「生锈」用于金属，不说天气生锈。", "点燃": "语义：「点燃」指使东西着火，天气不能被点燃。", "结婚": "语义：「结婚」是人的行为，天气不会结婚。", "变暖": "「变暖」指天气转暖，符合「下个星期」的时间语境。"}, "sentence_index": 6, "correct_answer": "变暖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的收入变暖了。", "explanation": "这里应该用〈增加〉。「变暖」只用于天气或温度，收入的增长要用〈增加〉。"}, {"text": "这家公司的规模变暖了。", "explanation": "这里应该用〈扩大〉。「变暖」只用于温度，说公司规模要用〈扩大〉。"}, {"text": "这次考试的难度变暖了。", "explanation": "这里应该用〈提高〉。「变暖」只说温度上升，难度的变化要用〈提高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天到了，天气很变暖了。", "corrected_sentence": "春天到了，天气变暖了。", "error_description": "副词错误：「很」不能直接修饰动词「变暖」；应删去「很」，说「天气变暖了」或「天气变得很暖和」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个星期天气被变暖了，大家都出来了。", "corrected_sentence": "这个星期天气变暖了，大家都出来了。", "error_description": "被字句错误：「变暖」是不及物动词，不能用「被」字句；应说「天气变暖了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07e277-5fc3-44cc-9af2-34f0f1118fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
