INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个东西从开始到结束的时间。", "primary_collocate": null, "pronunciation": "shēng mìng zhōu qī", "ipa": "ʂɤŋ˥˥ miŋ˥˩ ʈʂoʊ˥˥ tɕʰi˥˥", "syllable_count": 4, "sentences": [{"text": "手机的生命周期大约是三年。", "target_word": "生命周期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶的生命周期有四个阶段。", "target_word": "生命周期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种产品的生命周期很短。", "target_word": "生命周期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "了解植物的生命周期，才能照顾好它。", "target_word": "生命周期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树的生命周期比人长得多。", "target_word": "生命周期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要延长产品的生命周期。", "target_word": "生命周期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚊子的生命周期只有几周。", "target_word": "生命周期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个软件都有自己的生命周期。", "target_word": "生命周期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池的生命周期和使用方法有关。", "target_word": "生命周期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了青蛙的生命周期。", "target_word": "生命周期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "产品生命周期", "label": "复合"}, {"form": "生命週期", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物从开始到结束的全过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生命周期", "is_correct": true, "explanation": "原句说手机从开始到结束的时间大约三年，“生命周期”指事物的全过程，正合适。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是钱数，不能表示时间长短。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“大约是三年”要求可以计时的过程作主语，“颜色”不能这样用。"}, {"text": "性格", "is_correct": false, "explanation": "语义：手机没有性格，且“性格”不表示时间。"}], "explanations": {"生命周期": "原句说手机从开始到结束的时间大约三年，“生命周期”指事物的全过程，正合适。", "价格": "语义：“价格”是钱数，不能表示时间长短。", "颜色": "搭配：“大约是三年”要求可以计时的过程作主语，“颜色”不能这样用。", "性格": "语义：手机没有性格，且“性格”不表示时间。"}, "sentence_index": 0, "correct_answer": "生命周期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天的生命周期很快乐。", "explanation": "这里应该用〈心情〉。“生命周期”指事物从开始到结束的全过程，人的情绪要用“心情”。"}, {"text": "我们的生命周期在市中心。", "explanation": "这里应该用〈地点〉。“生命周期”是时间过程，不能表示位置，应说“地点”或“位置”。"}, {"text": "他这次的生命周期很好。", "explanation": "这里应该用〈成绩〉。“生命周期”不能用来评价一次考试或比赛的结果，应说“成绩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生命周期", "is_correct": true, "explanation": "原句说蚊子从出生到死亡的时间只有几周，“生命周期”正合适。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是重量，不能用“只有几周”来描述。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”不表示时间长短，不能用“几周”来形容。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能与“只有几周”搭配。"}], "explanations": {"生命周期": "原句说蚊子从出生到死亡的时间只有几周，“生命周期”正合适。", "体重": "语义：“体重”是重量，不能用“只有几周”来描述。", "脾气": "语义：“脾气”不表示时间长短，不能用“几周”来形容。", "身高": "搭配：“身高”不能与“只有几周”搭配。"}, "sentence_index": 6, "correct_answer": "生命周期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的生命周期是五公斤。", "explanation": "这里应该用〈重量〉。“生命周期”指时间上的全过程，苹果的分量要用“重量”。"}, {"text": "这间教室的生命周期很大。", "explanation": "这里应该用〈面积〉。“生命周期”是时间过程，空间大小要用“面积”或“大小”。"}, {"text": "这件衣服的生命周期很贵。", "explanation": "这里应该用〈价格〉。“生命周期”不能表示花多少钱，衣服的花费要用“价格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个产品有一只完整的生命周期。", "corrected_sentence": "这个产品有一个完整的生命周期。", "error_description": "量词错误：“生命周期”是抽象概念，应用量词“个”；“只”通常用于动物，不能说“一只生命周期”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个软件的生命周期已经结束着。", "corrected_sentence": "这个软件的生命周期已经结束了。", "error_description": "“着”表示持续的状态，“结束”是一次性完成的动作，应用“了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
