INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23454, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23454, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "意思藏在话里，不直接说出来。", "primary_collocate": null, "pronunciation": "yǐn hán", "ipa": "in˨˩ xan˧˥", "syllable_count": 2, "sentences": [{"text": "他说“天气真热”，话里隐含着想开空调的意思。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的话隐含着希望我早点回家。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话隐含着拒绝的意思。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没说“不行”，但话里隐含了这个意思。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她问我几点了，话里其实隐含着想走的意思。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事隐含着一个道理。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的话隐含着对大家的要求。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的问题里隐含着一点不高兴。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说的每句话都隐含着关心。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你听得出他话里隐含的意思吗？", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐含着", "label": "体标（着）"}, {"form": "隐含了", "label": "体标（了）"}, {"form": "隱含", "label": "繁体"}], "register": "书面", "sense_fingerprint": "话里藏着没有直说的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3430cc5-80a4-4de2-a1d0-e0c20ca887f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23454, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扩散", "is_correct": false, "explanation": "搭配：“扩散”用于气味、疾病、消息，不能带“想开空调”这类意愿。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”需要多人交流，与一个人说“天气真热”的表达不符。"}, {"text": "隐含", "is_correct": true, "explanation": "正确：隐含着，表示话里藏着没有直说的意思，与“他说‘天气真热’”的语境相合。"}, {"text": "宣布", "is_correct": false, "explanation": "搭配：“宣布”不接“想开空调”这类意愿，说“宣布着想开空调”不通。"}], "explanations": {"扩散": "搭配：“扩散”用于气味、疾病、消息，不能带“想开空调”这类意愿。", "讨论": "语义：“讨论”需要多人交流，与一个人说“天气真热”的表达不符。", "隐含": "正确：隐含着，表示话里藏着没有直说的意思，与“他说‘天气真热’”的语境相合。", "宣布": "搭配：“宣布”不接“想开空调”这类意愿，说“宣布着想开空调”不通。"}, "sentence_index": 0, "correct_answer": "隐含"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他隐含了真相。", "explanation": "这里应该用〈掩盖〉。隐含指意思藏在话语里，是话本身带有的内容，不能由人主动去遮盖真相，因此不能说“隐含了真相”。"}, {"text": "这份名单隐含十个人。", "explanation": "这里应该用〈包括〉。隐含只用于意思、情感，不能说名单中包含的人被“隐含”。"}, {"text": "这篇文章隐含了三个段落。", "explanation": "这里应该用〈包含〉。隐含只用于意思、情感，不能说文章里的段落被“隐含”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”是不准做某事，与“要求”的含义相左，说“禁止要求”不通。"}, {"text": "追问", "is_correct": false, "explanation": "搭配：“追问”针对问题或事情，不能与“要求”搭配。"}, {"text": "隐含", "is_correct": true, "explanation": "正确：隐含着，表示经理的话里藏着对大家的要求，与“经理的话”的语境相合。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有轻视的意思，与经理向大家提出要求的语境不符。"}], "explanations": {"禁止": "语义：“禁止”是不准做某事，与“要求”的含义相左，说“禁止要求”不通。", "追问": "搭配：“追问”针对问题或事情，不能与“要求”搭配。", "隐含": "正确：隐含着，表示经理的话里藏着对大家的要求，与“经理的话”的语境相合。", "嘲笑": "语义：“嘲笑”带有轻视的意思，与经理向大家提出要求的语境不符。"}, "sentence_index": 6, "correct_answer": "隐含"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙隐含在花盆下。", "explanation": "这里应该用〈藏〉。隐含只指意思或情感藏在话里，不能用于把钥匙藏在某处。"}, {"text": "小鸟隐含在树叶里。", "explanation": "这里应该用〈躲藏〉。隐含只指意思或情感藏在话里，不能用于小鸟躲在树叶间。"}, {"text": "这座城市隐含了三所大学。", "explanation": "这里应该用〈拥有〉。隐含只用于意思、情感，不能用来说城市拥有的机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没说要走，但话里很隐含着想走的意思。", "corrected_sentence": "他没说要走，但话里隐含着想走的意思。", "error_description": "错误：“很隐含着”，应删去“很”。“隐含”表示意思藏在话里，是不分程度的动作，一般不受程度副词“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的沉默里隐含了着一丝失望。", "corrected_sentence": "他的沉默里隐含着一丝失望。", "error_description": "错误：“隐含了着”，应为“隐含着”。表示持续存在要用“着”，“了”与“着”不能同时用在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
