INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23456, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很大很大的城市，有很多很多人，很高的楼房。", "primary_collocate": null, "pronunciation": "dà dū shì", "ipa": "ta˥˩ tu˥ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "北京是一个大都市。", "target_word": "大都市", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大都市里有很多人。", "target_word": "大都市", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大都市的楼房很高。", "target_word": "大都市", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我哥哥住在大都市。", "target_word": "大都市", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大都市里的路上车很多。", "target_word": "大都市", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她想去大都市看看高楼。", "target_word": "大都市", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个大都市有很多商店。", "target_word": "大都市", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家离大都市很远。", "target_word": "大都市", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在大都市工作了三年。", "target_word": "大都市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大都市的晚上也很热闹。", "target_word": "大都市", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人多楼高的很大的城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94b4d57c-ba46-40c9-9d83-b3978f6c429b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小村庄", "is_correct": false, "explanation": "语义：北京是很大的城市，“小村庄”与北京的实际规模相矛盾。"}, {"text": "农场", "is_correct": false, "explanation": "语义：北京不是农场，农场与城市的性质不相符。"}, {"text": "乡下", "is_correct": false, "explanation": "语义：“乡下”指农村，北京是城市，不能说北京是乡下。"}, {"text": "大都市", "is_correct": true, "explanation": "大都市指很大很大、人很多、楼房很高的城市，与北京相符。"}], "explanations": {"小村庄": "语义：北京是很大的城市，“小村庄”与北京的实际规模相矛盾。", "农场": "语义：北京不是农场，农场与城市的性质不相符。", "乡下": "语义：“乡下”指农村，北京是城市，不能说北京是乡下。", "大都市": "大都市指很大很大、人很多、楼房很高的城市，与北京相符。"}, "sentence_index": 0, "correct_answer": "大都市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥住在大都市，那里只有几户人家。", "explanation": "这里应该用〈小村庄〉。大都市指人很多、楼房很高的城市，不能说只有几户人家。"}, {"text": "我哥哥住在大都市，那里的楼房都很矮。", "explanation": "这里应该用〈小镇〉。大都市的楼房很高，楼房都很矮要说小镇，不能说大都市。"}, {"text": "我哥哥住在大都市，那里的田地很多。", "explanation": "这里应该用〈乡下〉。大都市是人口密集的城市，田地很多的地方要说乡下，不能说大都市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农田", "is_correct": false, "explanation": "语义：农田是种庄稼的地方，不会有很多商店，与“很多商店”相矛盾。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林里没有很多商店，与句子的说法不符。"}, {"text": "沙漠", "is_correct": false, "explanation": "搭配：“有很多商店”一般用于人口聚集的地方，“沙漠”不能这样搭配。"}, {"text": "大都市", "is_correct": true, "explanation": "大都市指很大很大的城市，有很多很多人、很高的楼房，也会有很多商店，与句子相符。"}], "explanations": {"农田": "语义：农田是种庄稼的地方，不会有很多商店，与“很多商店”相矛盾。", "森林": "语义：森林里没有很多商店，与句子的说法不符。", "沙漠": "搭配：“有很多商店”一般用于人口聚集的地方，“沙漠”不能这样搭配。", "大都市": "大都市指很大很大的城市，有很多很多人、很高的楼房，也会有很多商店，与句子相符。"}, "sentence_index": 6, "correct_answer": "大都市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大都市的晚上也很热闹，可是那里只住着十几个人。", "explanation": "这里应该用〈小村子〉。大都市人很多，只住着十几个人的地方是小村子，不能说大都市。"}, {"text": "很小的大都市的晚上也很热闹。", "explanation": "这里应该用〈小城镇〉。〈大都市〉指很大很大的城市，不能用“很小”来形容它。"}, {"text": "矮矮的大都市的晚上也很热闹。", "explanation": "这里应该用〈小镇〉。〈大都市〉楼房很高，〈矮矮的〉更像低矮的小镇，两者不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她搬到一只大都市去住。", "corrected_sentence": "她搬到一座大都市去住。", "error_description": "量词错误：大都市是城市，应用量词“座”。“只”多用于动物，不能用来数城市。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐很喜欢大都市地生活。", "corrected_sentence": "姐姐很喜欢大都市的生活。", "error_description": "的/地误用：修饰名词“生活”要用“的”，“地”用于修饰动词，“大都市地生活”不成立，应为“大都市的生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
