INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "买卖东西的事情。", "primary_collocate": null, "pronunciation": "shāng yè", "ipa": "ʂɑŋ˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市的商业很发达。", "target_word": "商业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥大学学的是商业。", "target_word": "商业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街上的商业很热闹，店很多。", "target_word": "商业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在网上的商业越来越发达。", "target_word": "商业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小城的商业慢慢发展起来了。", "target_word": "商业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从事商业已经十年了。", "target_word": "商业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地方既有工业，又有商业。", "target_word": "商业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对商业很感兴趣，所以想开一家公司。", "target_word": "商业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的商业发展得很快。", "target_word": "商业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发展商业，首先要了解客人想要什么。", "target_word": "商业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "商业区", "label": "复合"}, {"form": "商业街", "label": "复合"}, {"form": "商业化", "label": "复合"}], "register": "中性", "sense_fingerprint": "商业：买卖东西、做生意这一行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc7d612e-20ca-4dd1-8228-5889a24a7062') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肌肉", "is_correct": false, "explanation": "语义：肌肉属于人或动物，城市没有肌肉，句子说不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“发达”不能用来形容身高，句子说不通。"}, {"text": "商业", "is_correct": true, "explanation": "正确：商业指买卖东西的行业，城市的商业可以很发达。"}, {"text": "牙齿", "is_correct": false, "explanation": "语义：牙齿是人或动物的器官，城市不可能有牙齿。"}], "explanations": {"肌肉": "语义：肌肉属于人或动物，城市没有肌肉，句子说不通。", "身高": "搭配：“发达”不能用来形容身高，句子说不通。", "商业": "正确：商业指买卖东西的行业，城市的商业可以很发达。", "牙齿": "语义：牙齿是人或动物的器官，城市不可能有牙齿。"}, "sentence_index": 0, "correct_answer": "商业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小就很喜欢读书，商业一直很好。", "explanation": "这里应该用〈学业〉。说学习的成绩和情况要用〈学业〉，“商业”指买卖的行业，不能用来说读书的情况。"}, {"text": "这家商业卖各种各样的衣服。", "explanation": "这里应该用〈商店〉。“商业”指买卖的行业，不指卖东西的地方，应说〈商店〉。"}, {"text": "他的商业是教小学生，每天都要上课。", "explanation": "这里应该用〈工作〉。说职业要用〈工作〉，“商业”指买卖的行业，教小学生不属于买卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "血液", "is_correct": false, "explanation": "语义：地方不可能有血液，“又有”后面接的应该是地方的事物。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人或动物的身体状况，不能用来描述一个地方。"}, {"text": "商业", "is_correct": true, "explanation": "正确：商业与“工业”并列，“既有……又有”正好说这个地方的经济活动。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：“又有”后面不能接“身材”，地方没有身材，搭配不通。"}], "explanations": {"血液": "语义：地方不可能有血液，“又有”后面接的应该是地方的事物。", "体温": "语义：体温是人或动物的身体状况，不能用来描述一个地方。", "商业": "正确：商业与“工业”并列，“既有……又有”正好说这个地方的经济活动。", "身材": "搭配：“又有”后面不能接“身材”，地方没有身材，搭配不通。"}, "sentence_index": 6, "correct_answer": "商业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名商业，常去外地进货。", "explanation": "这里应该用〈商人〉。“商业”指买卖的行业，不指做买卖的人，人要说〈商人〉。"}, {"text": "饭店请了一位商业，负责做菜。", "explanation": "这里应该用〈厨师〉。负责做菜的人要说〈厨师〉，“商业”不能指人。"}, {"text": "公司门口站着一个商业，负责看门。", "explanation": "这里应该用〈保安〉。负责看门的人要说〈保安〉，“商业”指买卖的行业，不指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小城的商业的很繁荣。", "corrected_sentence": "这座小城的商业很繁荣。", "error_description": "“的”多余：“这座小城的商业”中的“的”已经连接修饰语，“商业”后面不能再加“的”，应说“这座小城的商业很繁荣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在商业很感兴趣。", "corrected_sentence": "他对商业很感兴趣。", "error_description": "介词用错：表示对某方面有兴趣要说“对……感兴趣”，不能说“在商业感兴趣”，应说“他对商业很感兴趣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23460, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失业", "is_correct": true, "explanation": "反义：就业指找到工作，失业指失去工作，两者意义相反。"}, {"text": "休息", "is_correct": false, "explanation": "无关：休息指停下来放松，与就业没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：旅行指外出游览，与就业没有反义关系。"}, {"text": "结婚", "is_correct": false, "explanation": "无关：结婚指组成家庭，与就业没有反义关系。"}], "correct_answer": "失业", "explanations": {"失业": "反义：就业指找到工作，失业指失去工作，两者意义相反。", "休息": "无关：休息指停下来放松，与就业没有反义关系。", "旅行": "无关：旅行指外出游览，与就业没有反义关系。", "结婚": "无关：结婚指组成家庭，与就业没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23460, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失业", "is_correct": true, "explanation": "反义：就业指找到工作，失业指失去工作，两者意义相反。"}, {"text": "出发", "is_correct": false, "explanation": "无关：出发指动身离开，与就业没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "无关：游泳指在水中运动，与就业没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：唱歌指用声音表演，与就业没有反义关系。"}], "correct_answer": "失业", "explanations": {"失业": "反义：就业指找到工作，失业指失去工作，两者意义相反。", "出发": "无关：出发指动身离开，与就业没有反义关系。", "游泳": "无关：游泳指在水中运动，与就业没有反义关系。", "唱歌": "无关：唱歌指用声音表演，与就业没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23460, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "找到一个工作，开始做事情赚钱。", "primary_collocate": null, "pronunciation": "jiù yè", "ipa": "tɕjoʊ˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他想早点就业，帮家里赚钱。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学毕业三个月后，她终于就业了。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就业以后，我每个月给妈妈寄钱。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥没上大学，高中毕业就业了。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚就业，还不懂公司的规矩。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹在银行就业，工作很稳定。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们夫妻都已经就业，生活不愁。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业生要先就业，再慢慢攒钱买房。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸三十年前就业，一直在工厂工作。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了就业，认真学了英语。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "就业了", "label": "体标"}, {"form": "就业过", "label": "体标"}], "register": "中性", "sense_fingerprint": "找到工作并开始赚钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4275a2c9-4bff-40c5-ac87-bdb8abddd072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就业", "is_correct": true, "explanation": "就业：指找到工作、开始赚钱，与“想早点……帮家里赚钱”的语境一致。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休指年老后不再工作，与“想早点”“帮家里赚钱”的语境矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳是水中运动，与“想早点……帮家里赚钱”的语境不符，句意不通。"}, {"text": "失恋", "is_correct": false, "explanation": "语义：失恋指恋爱失败，与“帮家里赚钱”无关，句意不通。"}], "explanations": {"就业": "就业：指找到工作、开始赚钱，与“想早点……帮家里赚钱”的语境一致。", "退休": "语义：退休指年老后不再工作，与“想早点”“帮家里赚钱”的语境矛盾。", "游泳": "语义：游泳是水中运动，与“想早点……帮家里赚钱”的语境不符，句意不通。", "失恋": "语义：失恋指恋爱失败，与“帮家里赚钱”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "就业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哥哥正在四处就业，还没有找到工作。", "explanation": "这里应该用〈求职〉。就业指找到工作、开始工作，不能用于正在寻找工作的过程；找工作要说求职。"}, {"text": "哥哥每天早上七点就业，晚上六点回家。", "explanation": "这里应该用〈上班〉。就业指找到工作这件事，每天的上下班要说上班。"}, {"text": "哥哥每天下午去公园就业，锻炼身体。", "explanation": "这里应该用〈锻炼〉。就业指找到工作，去公园锻炼身体不是找工作，应说锻炼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就业", "is_correct": true, "explanation": "就业：指找到工作、开始赚钱，与“夫妻都已经……，生活不愁”的语境相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是身体患病，与“生活不愁”的语境没有关系，句意不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：驾驶及物，需要带宾语（如驾驶汽车），不能单独作谓语。"}, {"text": "上学", "is_correct": false, "explanation": "语义：上学指学生去学校读书，与“夫妻都已经”的成年人身份矛盾。"}], "explanations": {"就业": "就业：指找到工作、开始赚钱，与“夫妻都已经……，生活不愁”的语境相符。", "感冒": "语义：感冒是身体患病，与“生活不愁”的语境没有关系，句意不通。", "驾驶": "配价：驾驶及物，需要带宾语（如驾驶汽车），不能单独作谓语。", "上学": "语义：上学指学生去学校读书，与“夫妻都已经”的成年人身份矛盾。"}, "sentence_index": 6, "correct_answer": "就业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被派到外地担任镇长，下周就业。", "explanation": "这里应该用〈上任〉。上任指正式就任官职或领导职务；就业指找到工作，不用于就任职务。"}, {"text": "她在公司干了三年，因为怀孕，上个月就业了。", "explanation": "这里应该用〈辞职〉。她原本已有工作，离开工作要说辞职；就业指找到工作、开始工作，与“干了三年”的情况矛盾。"}, {"text": "她高中毕业后考上了大学，现在正在就业。", "explanation": "这里应该用〈上学〉。就业指找到工作、开始工作；在大学读书要说上学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他毕业后老家就业了。", "corrected_sentence": "他毕业后在老家就业了。", "error_description": "介词遗漏：表示就业地点的「老家」前要用介词「在」，应说「在老家就业」，不能省略「在」。正确句为「他毕业后在老家就业了。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她终于在深圳就业着了。", "corrected_sentence": "她终于在深圳就业了。", "error_description": "错误在于多加了“着”。“着”表示持续状态，与“就业”这种一次完成的动作不兼容，表示完成时只用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
