INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为大家提供的设施和服务，比如医院、学校。", "primary_collocate": null, "pronunciation": "gōng gòng fú wù", "ipa": "kʊŋ˥ kʊŋ˥˩ fu˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "医院和学校都是公共服务。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近的公共服务很好，有医院，也有学校。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园、图书馆和医院都是公共服务。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的公共服务很全，走几步就有医院。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在城里，用公共服务很方便。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都可以用公共服务，不用花很多钱。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村新修了学校，公共服务变好了。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片新区的公共服务还比较少，只有一个小学。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子上学和看病都要用公共服务。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校、医院和图书馆是给大家用的公共服务。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公共服務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "医院、学校等给大家使用的设施和服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4275a2c9-4bff-40c5-ac87-bdb8abddd072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共服务", "is_correct": true, "explanation": "公共服务：指医院、学校等给大家使用的设施和服务，与“医院和学校都是”相符。"}, {"text": "农药", "is_correct": false, "explanation": "搭配：“是”后面的名词要能指医院、学校这类公共设施，农药不能。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物与医院、学校不属于同一类，句意不通。"}, {"text": "收入", "is_correct": false, "explanation": "语义：收入不是医院或学校这类设施，“医院和学校都是收入”句意不通。"}], "explanations": {"公共服务": "公共服务：指医院、学校等给大家使用的设施和服务，与“医院和学校都是”相符。", "农药": "搭配：“是”后面的名词要能指医院、学校这类公共设施，农药不能。", "宠物": "语义：宠物与医院、学校不属于同一类，句意不通。", "收入": "语义：收入不是医院或学校这类设施，“医院和学校都是收入”句意不通。"}, "sentence_index": 0, "correct_answer": "公共服务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的公共服务很好，服务员很热情。", "explanation": "这里应该用〈商业服务〉。餐厅是私人经营，其待客服务属于商业服务，不属于公共机构为大家提供的公共服务。"}, {"text": "这家公司给员工的公共服务很多，包括年终奖和补贴。", "explanation": "这里应该用〈福利〉。年终奖和补贴是公司给员工的福利，不是公共服务。"}, {"text": "这家工厂生产的公共服务很受欢迎。", "explanation": "这里应该用〈产品〉。工厂生产的是产品，公共服务不是工厂生产的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共服务", "is_correct": true, "explanation": "公共服务：指给大家使用的设施和服务，与“我们村新修了学校”后的变化相符。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“变好”一般搭配环境、条件、质量，不能搭配面积。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不会因为新修学校而变好，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会因为新修学校而变好，句意不通。"}], "explanations": {"公共服务": "公共服务：指给大家使用的设施和服务，与“我们村新修了学校”后的变化相符。", "面积": "搭配：“变好”一般搭配环境、条件、质量，不能搭配面积。", "体重": "语义：体重不会因为新修学校而变好，句意不通。", "年龄": "语义：年龄不会因为新修学校而变好，句意不通。"}, "sentence_index": 6, "correct_answer": "公共服务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校新买了一批公共服务，给学生上课用。", "explanation": "这里应该用〈设备〉。课桌、电脑等是可以购买的设备；公共服务是提供的服务，不能购买。"}, {"text": "我每天骑着一个公共服务去上班。", "explanation": "这里应该用〈自行车〉。公共服务是设施和服务，不能骑；每天骑着去上班的是自行车。"}, {"text": "这栋楼有很大的公共服务，可以停放自行车。", "explanation": "这里应该用〈空间〉。可以停放自行车的是公共空间，公共服务不是场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市有一座重要的公共服务。", "corrected_sentence": "这个城市有一项重要的公共服务。", "error_description": "量词错误：“公共服务”应使用量词“项”，不能用“座”，因为“座”多用于大型建筑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区去年为老人生产了公共服务。", "corrected_sentence": "社区去年为老人提供了公共服务。", "error_description": "搭配错误：“生产”的对象是产品，公共服务不能“生产”，应说“提供”。正确句为「社区去年为老人提供了公共服务。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
